const e={"level-7":{id:"level-7",kind:"level",level:7,src:"level:7",title:"Level 7 · Letters and Ratios",body:"Multiplying and dividing negatives, kinds of number, ratio, percentage change and speed, first letters for numbers, circles and volume, chance as a fraction, and factorials and arrangements.",more:"Its lands: Signs that multiply · Kinds of number · Percentages, ratio and rates · Letters for numbers · Circles, triangles and solids · Chance and arrangements · Roots by sight · The board solves for two · Clever ways round.",where:"Level 7 · maths age 12",route:"#/journey/7",cta:"See the road"},"land-l7-negatives":{id:"land-l7-negatives",kind:"land",level:7,src:"land:l7-negatives",title:"Signs that multiply — in The Deep Mine",body:"4 stops on this stretch of the road: A day of ups and downs · Multiplying negatives · Dividing negatives · Squares and brackets.",art:"art/w-mine.webp",more:"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.",where:"The Deep Mine · Level 7",route:"#/world/mine",cta:"Visit Mine"},"land-l7-factors":{id:"land-l7-factors",kind:"land",level:7,src:"land:l7-factors",title:"Kinds of number — in The Prime Quarry",body:"4 stops on this stretch of the road: Square, triangle, cube or prime · Building with prime stones · How far to test a prime · Cubes and cube roots.",art:"art/w-quarry.webp",more:"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.",where:"The Prime Quarry · Level 7",route:"#/world/quarry",cta:"Visit Quarry"},"land-l7-decimals":{id:"land-l7-decimals",kind:"land",level:7,src:"land:l7-decimals",title:"Percentages, ratio and rates — in The Decimal Dock",body:"6 stops on this stretch of the road: Percentages of an amount · Find one, then scale · Sales and rises · Ratio: simplify and share · Speed, distance and time · Simple interest.",art:"art/w-dock.webp",more:"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.",where:"The Decimal Dock · Level 7",route:"#/world/dock",cta:"Visit Dock"},"land-l7-algebra":{id:"land-l7-algebra",kind:"land",level:7,src:"land:l7-algebra",title:"Letters for numbers — in Set Island",body:"4 stops on this stretch of the road: Working backwards · Letters for numbers · Collecting like terms · Solving equations on a balance.",art:"art/w-setisland.webp",more:"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.",where:"Set Island · Level 7",route:"#/world/setisland",cta:"Visit Set Island"},"land-l7-shape":{id:"land-l7-shape",kind:"land",level:7,src:"land:l7-shape",title:"Circles, triangles and solids — in Shape City",body:"3 stops on this stretch of the road: Round the circle · Building a triangle from three sides · Volume and surface area.",art:"art/w-shapecity.webp",more:"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.",where:"Shape City · Level 7",route:"#/world/shapecity",cta:"Visit Shape City"},"land-l7-data":{id:"land-l7-data",kind:"land",level:7,src:"land:l7-data",title:"Chance and arrangements — in The Data Carnival",body:"4 stops on this stretch of the road: Chance as a fraction · Counting all the ways · Factorials · Putting things in order.",art:"art/w-carnival.webp",more:"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.",where:"The Data Carnival · Level 7",route:"#/world/carnival",cta:"Visit Carnival"},"land-l7-vedic":{id:"land-l7-vedic",kind:"land",level:7,src:"land:l7-vedic",title:"Roots by sight — in The Sutra Ladder",body:"5 stops on this stretch of the road: Straight division: the flag · The duplex, and any square · Square roots by sight · Cube roots by sight · Divisibility by osculators.",art:"art/w-ladder.webp",more:"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.",where:"The Sutra Ladder · Level 7",route:"#/world/ladder",cta:"Visit Ladder"},"land-l7-chinese":{id:"land-l7-chinese",kind:"land",level:7,src:"land:l7-chinese",title:"The board solves for two — in The Counting Court",body:"4 stops on this stretch of the road: Too many, too few · Fangcheng: clearing the columns · Remainders by multipliers · The sea island survey.",art:"art/w-court.webp",more:"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.",where:"The Counting Court · Level 7",route:"#/world/court",cta:"Visit Court"},"land-l7-contest":{id:"land-l7-contest",kind:"land",level:7,src:"land:l7-contest",title:"Clever ways round — in The Strategy School",body:"6 stops on this stretch of the road: Work backwards · Find the rule · Pretend they are all the same · The gap never changes · Try a smaller one first · Closing the gap.",art:"art/w-strategy.webp",more:"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.",where:"The Strategy School · Level 7",route:"#/world/strategy",cta:"Visit Strategy"},"trick-volume-cuboid-idea":{id:"trick-volume-cuboid-idea",kind:"trick",src:"stop:volume-cuboid#idea",title:"Volume and surface area",body:"Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs. Fill the bottom of the box with 1 cm cubes. They make a rectangle, so the bottom layer holds length × width cubes — 5 × 3 = 15. Every layer above is the same, and there are as many layers as the box is tall: 15 × 4 = 60 cm³.",more:"In algebra: V = l × w × h · SA = 2(lw + lh + wh)",cta:"Learn the trick",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|learn"},"story-volume-cuboid-open":{id:"story-volume-cuboid-open",kind:"story",src:"story:volume-cuboid#open",badge:{id:"story",label:"A story"},title:"Packing the crate",body:"At the harbour, Suki and Kwame pack cube-shaped tins into a crate 5 tins long, 3 wide and 4 tall. — with Suki and Kwame.",more:"The trick inside: Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",art:"art/s-harbour.webp",cta:"Read the story",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|story|0"},"hook-volume-cuboid-hook":{id:"hook-volume-cuboid-hook",kind:"hook",src:"stop:volume-cuboid#hook",title:"Can you? — Volume and surface area",body:"A box is 5 cm long, 3 cm wide and 4 cm tall. How many 1 cm cubes fill it?",more:"The way in: Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",cta:"Find out how",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|learn"},"idea-volume-cuboid-case0":{id:"idea-volume-cuboid-case0",kind:"idea",src:"stop:volume-cuboid#case0",title:"Volume and surface area: Volume",body:"Count the cubes in the bottom layer, then multiply by the number of layers. The answer is in cm³.",more:"The method: Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",cta:"See it worked",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|learn|0"},"worked-volume-cuboid-worked0":{id:"worked-volume-cuboid-worked0",kind:"worked",src:"stop:volume-cuboid#worked0",title:"Worked out — Volume and surface area: Volume",body:"A box is 5 cm long, 3 cm wide and 4 cm tall. What is its volume, in cm³?: Cubes in the bottom layer: 5 × 3 → 15 · Number of layers → 4 · 15 × 4 → 60",more:"What is special here: Count the cubes in the bottom layer, then multiply by the number of layers. The answer is in cm³.",cta:"Watch it step by step",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|learn|0"},"idea-volume-cuboid-case1":{id:"idea-volume-cuboid-case1",kind:"idea",src:"stop:volume-cuboid#case1",title:"Volume and surface area: Surface area",body:"Now you want the wrapping, not the filling: three different faces, each appearing twice. The answer is in cm².",more:"The method: Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",cta:"See it worked",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|learn|1"},"worked-volume-cuboid-worked1":{id:"worked-volume-cuboid-worked1",kind:"worked",src:"stop:volume-cuboid#worked1",title:"Worked out — Volume and surface area: Surface area",body:"A box is 5 cm long, 3 cm wide and 4 cm tall. What is its total surface area, in cm²?: Front and back: 2 × 5 × 4 → 40 · Top and bottom: 2 × 5 × 3 → 30 · The two ends: 2 × 3 × 4 → 24 · Add the six faces → 94",more:"What is special here: Now you want the wrapping, not the filling: three different faces, each appearing twice. The answer is in cm².",cta:"Watch it step by step",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|learn|1"},"why-volume-cuboid-why1":{id:"why-volume-cuboid-why1",kind:"why",src:"stop:volume-cuboid#why1",title:"Why “Volume and surface area” works",body:"Surface area is the wrapping paper, not the filling. A box has six flat faces, and opposite faces are the same size: front and back, top and bottom, left and right. So you find three areas and double each one.",more:"The trick: Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",cta:"See why",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|learn"},"why-volume-cuboid-why2":{id:"why-volume-cuboid-why2",kind:"why",src:"stop:volume-cuboid#why2",title:"Why “Volume and surface area” works",body:"Volume counts cubes (cm³, three lengths multiplied) and surface area counts squares (cm², two lengths multiplied). That is why a box can hold a lot but need little paper, or the other way round.",more:"The trick: Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",cta:"See why",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|learn"},"moment-volume-cuboid-beat3":{id:"moment-volume-cuboid-beat3",kind:"moment",src:"story:volume-cuboid#beat3",badge:{id:"story",label:"A story"},title:"Packing the crate — on the notepad",body:"Kwame: Four layers of fifteen. 15 × 4 = 60",more:"The trick in the story: Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",cta:"Read the story",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|story|3"},"moral-volume-cuboid-beat5":{id:"moral-volume-cuboid-beat5",kind:"moral",src:"story:volume-cuboid#beat5",badge:{id:"story",label:"A story"},title:"Kwame, in “Packing the crate”",body:"Sixty tins fill it. Length times width times height.",more:"The trick in the story: Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",cta:"Read the story",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|story|5"},"algebra-volume-cuboid-alg":{id:"algebra-volume-cuboid-alg",kind:"algebra",src:"stop:volume-cuboid#alg",title:"The algebra behind “Volume and surface area”",body:"V = l × w × h · SA = 2(lw + lh + wh)",more:"In words: Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",cta:"See why",where:"The Clock Tower · Level 7",level:7,route:"#/stop/volume-cuboid|learn"},"try-volume-cuboid-L7":{id:"try-volume-cuboid-L7",kind:"try",level:7,src:"try:volume-cuboid@7/1#0",title:"Volume and surface area — your turn",where:"The Clock Tower · Level 7",route:"#/stop/volume-cuboid|drill",cta:"Practise this stop",play:{q:"A box is 4 cm long, 5 cm wide and 4 cm tall. What is its volume, in cm³?",opts:["80","20","800"],after:"Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs.",show:[2,1,0]}},"trick-interest-simple-idea":{id:"trick-interest-simple-idea",kind:"trick",src:"stop:interest-simple#idea",title:"Simple interest",body:"Work out one year's interest — the rate per cent of the amount you put in — then multiply by the years. Interest is what a bank pays you for letting it use your money. This story's bank pays 5% a year: for every 100 coins you leave with it, it pays 5 coins each year. So 200 coins earns 5% of 200 = 10 coins a year.",more:"In algebra: I = P × r × t ÷ 100",cta:"Learn the trick",where:"Coin Street · Level 7",level:7,route:"#/stop/interest-simple|learn"},"story-interest-simple-open":{id:"story-interest-simple-open",kind:"story",src:"story:interest-simple#open",badge:{id:"story",label:"A story"},title:"The story bank",body:"In the city, the bank in this story pays 5% a year. Suki puts in 200 coins for 3 years. — with Ines and Suki.",more:"The trick inside: Work out one year's interest — the rate per cent of the amount you put in — then multiply by the years.",art:"art/s-city.webp",cta:"Read the story",where:"Coin Street · Level 7",level:7,route:"#/stop/interest-simple|story|0"},"idea-interest-simple-case0":{id:"idea-interest-simple-case0",kind:"idea",src:"stop:interest-simple#case0",title:"Simple interest: The interest",body:"One year's interest is the same every year, because it is always worked out on what was first put in. Multiply by the years.",more:"The method: Work out one year's interest — the rate per cent of the amount you put in — then multiply by the years.",cta:"See it worked",where:"Coin Street · Level 7",level:7,route:"#/stop/interest-simple|learn|0"},"why-interest-simple-why1":{id:"why-interest-simple-why1",kind:"why",src:"stop:interest-simple#why1",title:"Why “Simple interest” works",body:"With simple interest the interest is always worked out on the amount you first put in, so every year is the same helping: 10, 10 and 10. Three years is 3 × 10 = 30 coins, and the account ends with 230.",more:"The trick: Work out one year's interest — the rate per cent of the amount you put in — then multiply by the years.",cta:"See why",where:"Coin Street · Level 7",level:7,route:"#/stop/interest-simple|learn"},"moment-interest-simple-beat4":{id:"moment-interest-simple-beat4",kind:"moment",src:"story:interest-simple#beat4",badge:{id:"story",label:"A story"},title:"The story bank — on the notepad",body:"Ines: Three years of it. 10 × 3 = 30",more:"The trick in the story: Work out one year's interest — the rate per cent of the amount you put in — then multiply by the years.",cta:"Read the story",where:"Coin Street · Level 7",level:7,route:"#/stop/interest-simple|story|4"},"trick-round-the-circle-idea":{id:"trick-round-the-circle-idea",kind:"trick",src:"stop:round-the-circle#idea",title:"Round the circle",body:"The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter. The radius goes from the centre to the edge. The diameter goes right across through the centre, so it is one radius out and another radius back: two radii.",more:"In algebra: d = 2r · C = π × d ≈ 3.14 × d",cta:"Learn the trick",where:"Shape City · Level 7",level:7,route:"#/stop/round-the-circle|learn"},"story-round-the-circle-open":{id:"story-round-the-circle-open",kind:"story",src:"story:round-the-circle#open",badge:{id:"story",label:"A story"},title:"The rolling wheel",body:"Dax and Vesper wheel a bike through the city. Its wheel is 60 cm across. — with Vesper and Dax.",more:"The trick inside: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.",art:"art/s-city.webp",cta:"Read the story",where:"Shape City · Level 7",level:7,route:"#/stop/round-the-circle|story|0"},"idea-round-the-circle-case0":{id:"idea-round-the-circle-case0",kind:"idea",src:"stop:round-the-circle#case0",title:"Round the circle: Radius to diameter",body:"The diameter goes right across through the centre: one radius out and one radius back, so double it.",more:"The method: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.",cta:"See it worked",where:"Shape City · Level 7",level:7,route:"#/stop/round-the-circle|learn|0"},"idea-round-the-circle-case1":{id:"idea-round-the-circle-case1",kind:"idea",src:"stop:round-the-circle#case1",title:"Round the circle: Diameter to radius",body:"Going the other way, the radius is only halfway across — so halve the diameter.",more:"The method: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.",cta:"See it worked",where:"Shape City · Level 7",level:7,route:"#/stop/round-the-circle|learn|1"},"idea-round-the-circle-case2":{id:"idea-round-the-circle-case2",kind:"idea",src:"stop:round-the-circle#case2",title:"Round the circle: Round, from the diameter",body:"The distance round is a little more than 3 diameters: 3.14 × the diameter. Do the 3 × first, then add the small 0.14 ×.",more:"The method: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.",cta:"See it worked",where:"Shape City · Level 7",level:7,route:"#/stop/round-the-circle|learn|2"},"idea-round-the-circle-case3":{id:"idea-round-the-circle-case3",kind:"idea",src:"stop:round-the-circle#case3",title:"Round the circle: Round, from the radius",body:"π works with the diameter, so double the radius FIRST. Multiplying the radius by 3.14 gives only half the way round.",more:"The method: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.",cta:"See it worked",where:"Shape City · Level 7",level:7,route:"#/stop/round-the-circle|learn|3"},"why-round-the-circle-why1":{id:"why-round-the-circle-why1",kind:"why",src:"stop:round-the-circle#why1",title:"Why “Round the circle” works",body:"Every circle is a scaled-up or scaled-down copy of every other circle. So the distance round divided by the distance across is the same number for all of them. That number is called pi (π), and it is a little more than 3.14.",more:"The trick: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.",cta:"See why",where:"Shape City · Level 7",level:7,route:"#/stop/round-the-circle|learn"},"moment-round-the-circle-beat4":{id:"moment-round-the-circle-beat4",kind:"moment",src:"story:round-the-circle#beat4",badge:{id:"story",label:"A story"},title:"The rolling wheel — on the notepad",body:"Vesper: Then the small part. 0.14 × 60 = 8.4",more:"The trick in the story: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.",cta:"Read the story",where:"Shape City · Level 7",level:7,route:"#/stop/round-the-circle|story|4"},"try-round-the-circle-L7":{id:"try-round-the-circle-L7",kind:"try",level:7,src:"try:round-the-circle@7/1#0",title:"Round the circle — your turn",where:"Shape City · Level 7",route:"#/stop/round-the-circle|drill",cta:"Practise this stop",play:{q:"A circle has a radius of 10 cm. What is its diameter, in cm?",opts:["20","30","200"],after:"The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.",show:[1,0,2]}},"trick-construct-triangle-idea":{id:"trick-construct-triangle-idea",kind:"trick",src:"stop:construct-triangle#idea",title:"Building a triangle from three sides",body:"Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest. Draw the longest side as the base, from A to B. The third corner must be 3 cm from A, and every point 3 cm from A lies on a circle round A — so open the compasses to 3 cm and swing an arc from A. Do the same from B with 4 cm. The third corner is wherever the two arcs cross.",more:"In algebra: sides a ≤ b ≤ c make a triangle only if a + b > c · third side x: (b − a) < x < (a + b)",cta:"Learn the trick",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn"},"story-construct-triangle-open":{id:"story-construct-triangle-open",kind:"story",src:"story:construct-triangle#open",badge:{id:"story",label:"A story"},title:"Three straws",body:"Pip has three straws, 3 cm, 4 cm and 7 cm long, and wants a triangle. Mira gets out a ruler and compasses. — with Mira and Pip.",more:"The trick inside: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",art:"art/s-room.webp",cta:"Read the story",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|story|0"},"hook-construct-triangle-hook":{id:"hook-construct-triangle-hook",kind:"hook",src:"stop:construct-triangle#hook",title:"Can you? — Building a triangle from three sides",body:"Three sticks: 3 cm, 4 cm and 7 cm. Can they make a triangle? Build it with a ruler and compasses before you guess.",more:"The way in: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"Find out how",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn"},"idea-construct-triangle-case0":{id:"idea-construct-triangle-case0",kind:"idea",src:"stop:construct-triangle#case0",title:"Building a triangle from three sides: The arcs cross",body:"The two shorter sides together reach further than the base, so the arcs cross above it and the third corner is there.",more:"The method: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"See it worked",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn|0"},"worked-construct-triangle-worked0":{id:"worked-construct-triangle-worked0",kind:"worked",src:"stop:construct-triangle#worked0",title:"Worked out — Building a triangle from three sides: The arcs cross",body:"Can a triangle be built with sides of 5 cm, 6 cm and 8 cm?: The longest side — draw it as the base → 8 · Add the other two sides → 11 · The arcs cross only if that is MORE than 8. Can the triangle be built? → Yes",more:"What is special here: The two shorter sides together reach further than the base, so the arcs cross above it and the third corner is there.",cta:"Watch it step by step",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn|0"},"idea-construct-triangle-case1":{id:"idea-construct-triangle-case1",kind:"idea",src:"stop:construct-triangle#case1",title:"Building a triangle from three sides: The arcs never meet",body:"The two shorter sides together do not even reach across the base, so the arcs stop short of each other.",more:"The method: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"See it worked",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn|1"},"idea-construct-triangle-case2":{id:"idea-construct-triangle-case2",kind:"idea",src:"stop:construct-triangle#case2",title:"Building a triangle from three sides: The arcs only touch",body:"The trap: the shorter sides add up to EXACTLY the base. The arcs meet on the base line, the triangle lies flat — so the answer is still no.",more:"The method: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"See it worked",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn|2"},"worked-construct-triangle-worked2":{id:"worked-construct-triangle-worked2",kind:"worked",src:"stop:construct-triangle#worked2",title:"Worked out — Building a triangle from three sides: The arcs only touch",body:"Can a triangle be built with sides of 3 cm, 4 cm and 7 cm?: The longest side — draw it as the base → 7 · Add the other two sides → 7 · The arcs cross only if that is MORE than 7. Can the triangle be built? → No",more:"What is special here: The trap: the shorter sides add up to EXACTLY the base. The arcs meet on the base line, the triangle lies flat — so the answer is still no.",cta:"Watch it step by step",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn|2"},"idea-construct-triangle-case3":{id:"idea-construct-triangle-case3",kind:"idea",src:"stop:construct-triangle#case3",title:"Building a triangle from three sides: Longest third side",body:"The third side must be shorter than the other two laid end to end — so one less than their sum, as a whole number.",more:"The method: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"See it worked",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn|3"},"worked-construct-triangle-worked3":{id:"worked-construct-triangle-worked3",kind:"worked",src:"stop:construct-triangle#worked3",title:"Worked out — Building a triangle from three sides: Longest third side",body:"Two sides of a triangle are 5 cm and 8 cm. The third side is a whole number of cm. What is the longest it can be, in cm?: The two sides end to end: 5 + 8 → 13 · The third side must be shorter than that. The longest whole number it can be → 12",more:"What is special here: The third side must be shorter than the other two laid end to end — so one less than their sum, as a whole number.",cta:"Watch it step by step",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn|3"},"idea-construct-triangle-case4":{id:"idea-construct-triangle-case4",kind:"idea",src:"stop:construct-triangle#case4",title:"Building a triangle from three sides: Shortest third side",body:"The short side and the third side must reach past the long one — so the third side must be MORE than the difference.",more:"The method: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"See it worked",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn|4"},"worked-construct-triangle-worked4":{id:"worked-construct-triangle-worked4",kind:"worked",src:"stop:construct-triangle#worked4",title:"Worked out — Building a triangle from three sides: Shortest third side",body:"Two sides of a triangle are 5 cm and 8 cm. The third side is a whole number of cm. What is the shortest it can be, in cm?: The gap the short side cannot close: 8 − 5 → 3 · The third side must be longer than that. The shortest whole number it can be → 4",more:"What is special here: The short side and the third side must reach past the long one — so the third side must be MORE than the difference.",cta:"Watch it step by step",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn|4"},"why-construct-triangle-why1":{id:"why-construct-triangle-why1",kind:"why",src:"stop:construct-triangle#why1",title:"Why “Building a triangle from three sides” works",body:'The arcs can only cross if the two shorter sides, laid end to end, reach further than the base. If they add up to less, the arcs never meet. If they add up to exactly the base — 3 + 4 = 7 — the arcs only touch, on the base line itself: the "triangle" lies flat and has no third corner. So the two shorter sides must add up to more than the longest one.',more:"The trick: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"See why",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn"},"why-construct-triangle-why2":{id:"why-construct-triangle-why2",kind:"why",src:"stop:construct-triangle#why2",title:"Why “Building a triangle from three sides” works",body:"When the arcs do cross, the triangle is fixed: any triangle with those three sides fits exactly on top of yours. That is why a frame of three rods is rigid when four rods wobble. It also tells you what a missing third side can be: longer than the difference of the other two, shorter than their sum, and never exactly either.",more:"The trick: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"See why",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn"},"moment-construct-triangle-beat5":{id:"moment-construct-triangle-beat5",kind:"moment",src:"story:construct-triangle#beat5",badge:{id:"story",label:"A story"},title:"Three straws — on the notepad",body:"Pip: So if the long one were a bit shorter, the arcs would cross above the base? 7 − 1 = 6",more:"The trick in the story: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"Read the story",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|story|5"},"moral-construct-triangle-beat6":{id:"moral-construct-triangle-beat6",kind:"moral",src:"story:construct-triangle#beat6",badge:{id:"story",label:"A story"},title:"Mira, in “Three straws”",body:"Yes. The two shorter sides must add up to MORE than the longest. 3 + 4 is not more than 7, so no triangle.",more:"The trick in the story: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"Read the story",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|story|6"},"algebra-construct-triangle-alg":{id:"algebra-construct-triangle-alg",kind:"algebra",src:"stop:construct-triangle#alg",title:"The algebra behind “Building a triangle from three sides”",body:"sides a ≤ b ≤ c make a triangle only if a + b > c · third side x: (b − a) < x < (a + b)",more:"In words: Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",cta:"See why",where:"Shape City · Level 7",level:7,route:"#/stop/construct-triangle|learn"},"try-construct-triangle-L7":{id:"try-construct-triangle-L7",kind:"try",level:7,src:"try:construct-triangle@7/1#0",title:"Building a triangle from three sides — your turn",where:"Shape City · Level 7",route:"#/stop/construct-triangle|drill",cta:"Practise this stop",play:{q:"Can a triangle be built with sides of 10 cm, 3 cm and 7 cm?",opts:["No","Yes"],after:"Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest.",show:[1,0]}},"trick-ups-and-downs-idea":{id:"trick-ups-and-downs-idea",kind:"trick",src:"stop:ups-and-downs#idea",title:"A day of ups and downs",body:"Add up all the ups, add up all the downs, and then do one sum at the end. A long string of pluses and minuses is a lift log: each number is a trip, up or down. You could ride every trip in turn, crossing ground level again and again. But the order of the trips does not change where the lift ends up — up 8 then down 9 lands in the same place as down 9 then up 8.",more:"In algebra: a₁ + a₂ + … = (sum of the positives) − (sum of the sizes of the negatives)",cta:"Learn the trick",where:"The Deep Mine · Level 7",level:7,route:"#/stop/ups-and-downs|learn"},"story-ups-and-downs-open":{id:"story-ups-and-downs-open",kind:"story",src:"story:ups-and-downs#open",badge:{id:"story",label:"A story"},title:"The fair game",body:"At the fair, Rafi’s game scores go: −5, then +8, −9, +3 and −6. — with Theo and Rafi.",more:"The trick inside: Add up all the ups, add up all the downs, and then do one sum at the end.",art:"art/s-fair.webp",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/ups-and-downs|story|0"},"hook-ups-and-downs-hook":{id:"hook-ups-and-downs-hook",kind:"hook",src:"stop:ups-and-downs#hook",title:"Can you? — A day of ups and downs",body:"−5 + 8 − 9 + 3 − 6. Do you have to ride every trip one by one?",more:"The way in: Add up all the ups, add up all the downs, and then do one sum at the end.",cta:"Find out how",where:"The Deep Mine · Level 7",level:7,route:"#/stop/ups-and-downs|learn"},"worked-ups-and-downs-worked0":{id:"worked-ups-and-downs-worked0",kind:"worked",src:"stop:ups-and-downs#worked0",title:"Worked out — A day of ups and downs",body:"−5 + 8 − 9 + 3 − 6: All the ups: 8 + 3 → 11 · All the downs: 5 + 9 + 6 → 20 · Up 11 and down 20: where do you finish? → -9",more:"The method: Add up all the ups, add up all the downs, and then do one sum at the end.",cta:"Watch it step by step",where:"The Deep Mine · Level 7",level:7,route:"#/stop/ups-and-downs|learn|0"},"why-ups-and-downs-why1":{id:"why-ups-and-downs-why1",kind:"why",src:"stop:ups-and-downs#why1",title:"Why “A day of ups and downs” works",body:"So sort them. Put every up trip together and every down trip together. In −5 + 8 − 9 + 3 − 6 the ups are 8 and 3, which make 11. The downs are 5, 9 and 6, which make 20.",more:"The trick: Add up all the ups, add up all the downs, and then do one sum at the end.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/ups-and-downs|learn"},"why-ups-and-downs-why2":{id:"why-ups-and-downs-why2",kind:"why",src:"stop:ups-and-downs#why2",title:"Why “A day of ups and downs” works",body:"Now there is only one sum left: up 11 and down 20. The downs win by 9, so the lift finishes 9 below ground, at −9. Two easy additions and one take-away, instead of five trips across zero.",more:"The trick: Add up all the ups, add up all the downs, and then do one sum at the end.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/ups-and-downs|learn"},"moment-ups-and-downs-beat3":{id:"moment-ups-and-downs-beat3",kind:"moment",src:"story:ups-and-downs#beat3",badge:{id:"story",label:"A story"},title:"The fair game — on the notepad",body:"Rafi: And all the downs together. 5 + 9 + 6 = 20",more:"The trick in the story: Add up all the ups, add up all the downs, and then do one sum at the end.",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/ups-and-downs|story|3"},"moral-ups-and-downs-beat5":{id:"moral-ups-and-downs-beat5",kind:"moral",src:"story:ups-and-downs#beat5",badge:{id:"story",label:"A story"},title:"Rafi, in “The fair game”",body:"My score is −9. Two additions and one take-away.",more:"The trick in the story: Add up all the ups, add up all the downs, and then do one sum at the end.",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/ups-and-downs|story|5"},"algebra-ups-and-downs-alg":{id:"algebra-ups-and-downs-alg",kind:"algebra",src:"stop:ups-and-downs#alg",title:"The algebra behind “A day of ups and downs”",body:"a₁ + a₂ + … = (sum of the positives) − (sum of the sizes of the negatives)",more:"In words: Add up all the ups, add up all the downs, and then do one sum at the end.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/ups-and-downs|learn"},"try-ups-and-downs-L7":{id:"try-ups-and-downs-L7",kind:"try",level:7,src:"try:ups-and-downs@7/1#0",title:"A day of ups and downs — your turn",where:"The Deep Mine · Level 7",route:"#/stop/ups-and-downs|drill",cta:"Practise this stop",play:{q:"2 − 4 + 3 = ?",opts:["1","4","5"],after:"Add up all the ups, add up all the downs, and then do one sum at the end.",show:[1,2,0]}},"trick-multiply-signs-idea":{id:"trick-multiply-signs-idea",kind:"trick",src:"stop:multiply-signs#idea",title:"Multiplying negatives",body:"Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative. Start with a positive times a negative: 3 × (−4) is three bills of 4, which is a bill of 12, so −12. Three lots of going down 4 takes you 12 below ground.",more:"In algebra: (−a) × b = −(ab) ; (−a) × (−b) = ab",cta:"Learn the trick",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn"},"story-multiply-signs-open":{id:"story-multiply-signs-open",kind:"story",src:"story:multiply-signs#open",badge:{id:"story",label:"A story"},title:"The table that kept going",body:"Mira and Kwame are doing homework in Mira’s room. The question is −4 × (−8). — with Mira and Kwame.",more:"The trick inside: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",art:"art/s-room.webp",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|story|0"},"hook-multiply-signs-hook":{id:"hook-multiply-signs-hook",kind:"hook",src:"stop:multiply-signs#hook",title:"Can you? — Multiplying negatives",body:"−4 × (−8). Two negatives — why on earth is the answer positive?",more:"The way in: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",cta:"Find out how",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn"},"idea-multiply-signs-case0":{id:"idea-multiply-signs-case0",kind:"idea",src:"stop:multiply-signs#case0",title:"Multiplying negatives: One negative",body:"Lots of a bill is a bigger bill: one negative number in the product makes the answer negative.",more:"The method: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn|0"},"worked-multiply-signs-worked0":{id:"worked-multiply-signs-worked0",kind:"worked",src:"stop:multiply-signs#worked0",title:"Worked out — Multiplying negatives: One negative",body:"3 × (−4): Ignore the signs: 3 × 4 → 12 · How many of the numbers are negative? → 1 · Each pair of negatives makes a positive. So the answer is → -12",more:"What is special here: Lots of a bill is a bigger bill: one negative number in the product makes the answer negative.",cta:"Watch it step by step",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn|0"},"idea-multiply-signs-case1":{id:"idea-multiply-signs-case1",kind:"idea",src:"stop:multiply-signs#case1",title:"Multiplying negatives: Two negatives",body:"The pair of negatives cancels out, so the answer is positive — the times-table pattern leaves no other choice.",more:"The method: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn|1"},"worked-multiply-signs-worked1":{id:"worked-multiply-signs-worked1",kind:"worked",src:"stop:multiply-signs#worked1",title:"Worked out — Multiplying negatives: Two negatives",body:"−4 × (−8): Ignore the signs: 4 × 8 → 32 · How many of the numbers are negative? → 2 · Each pair of negatives makes a positive. So the answer is → 32",more:"What is special here: The pair of negatives cancels out, so the answer is positive — the times-table pattern leaves no other choice.",cta:"Watch it step by step",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn|1"},"idea-multiply-signs-case2":{id:"idea-multiply-signs-case2",kind:"idea",src:"stop:multiply-signs#case2",title:"Multiplying negatives: Three negatives",body:"Two of them pair up and cancel; the third is left over on its own, so the answer is negative again.",more:"The method: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn|2"},"worked-multiply-signs-worked2":{id:"worked-multiply-signs-worked2",kind:"worked",src:"stop:multiply-signs#worked2",title:"Worked out — Multiplying negatives: Three negatives",body:"−2 × (−3) × (−5): Ignore the signs: 2 × 3 × 5 → 30 · How many of the numbers are negative? → 3 · Each pair of negatives makes a positive. So the answer is → -30",more:"What is special here: Two of them pair up and cancel; the third is left over on its own, so the answer is negative again.",cta:"Watch it step by step",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn|2"},"why-multiply-signs-why1":{id:"why-multiply-signs-why1",kind:"why",src:"stop:multiply-signs#why1",title:"Why “Multiplying negatives” works",body:"Now write out the times table for −4 and walk the multiplier down the lift shaft: 2 × (−4) = −8, 1 × (−4) = −4, 0 × (−4) = 0. Each step down, the answer goes UP by 4. Carry on below ground and the pattern must hold: −1 × (−4) = 4, −2 × (−4) = 8. A negative times a negative is positive — the pattern leaves no other choice.",more:"The trick: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn"},"why-multiply-signs-why2":{id:"why-multiply-signs-why2",kind:"why",src:"stop:multiply-signs#why2",title:"Why “Multiplying negatives” works",body:"So for any product, multiply the sizes and then count the negatives. Each pair of negatives cancels out to a positive. Two negatives: positive. Three: negative again. The size never depends on the signs — only which side of zero you land.",more:"The trick: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn"},"moment-multiply-signs-beat4":{id:"moment-multiply-signs-beat4",kind:"moment",src:"story:multiply-signs#beat4",badge:{id:"story",label:"A story"},title:"The table that kept going — on the notepad",body:"Kwame: Keep the pattern going below zero. −1 × (−8) = 8",more:"The trick in the story: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|story|4"},"moral-multiply-signs-beat6":{id:"moral-multiply-signs-beat6",kind:"moral",src:"story:multiply-signs#beat6",badge:{id:"story",label:"A story"},title:"Kwame, in “The table that kept going”",body:"The pattern had no other choice. Negative times negative is positive.",more:"The trick in the story: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|story|6"},"algebra-multiply-signs-alg":{id:"algebra-multiply-signs-alg",kind:"algebra",src:"stop:multiply-signs#alg",title:"The algebra behind “Multiplying negatives”",body:"(−a) × b = −(ab) ; (−a) × (−b) = ab",more:"In words: Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/multiply-signs|learn"},"try-multiply-signs-L7":{id:"try-multiply-signs-L7",kind:"try",level:7,src:"try:multiply-signs@7/1#0",title:"Multiplying negatives — your turn",where:"The Deep Mine · Level 7",route:"#/stop/multiply-signs|drill",cta:"Practise this stop",play:{q:"−5 × 4 = ?",opts:["-20","-30","-200"],after:"Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative.",show:[0,1,2]}},"trick-divide-signs-idea":{id:"trick-divide-signs-idea",kind:"trick",src:"stop:divide-signs#idea",title:"Dividing negatives",body:"Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative. Division undoes multiplication. −42 ÷ (−6) asks: what times −6 makes −42? Try 7: 7 × (−6) = −42. So the answer is 7, a positive number, even though both numbers in the question were negative.",more:"In algebra: (−a) ÷ b = −(a ÷ b) ; (−a) ÷ (−b) = a ÷ b",cta:"Learn the trick",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn"},"story-divide-signs-open":{id:"story-divide-signs-open",kind:"story",src:"story:divide-signs#open",badge:{id:"story",label:"A story"},title:"The new freezer",body:"Vesper’s family has a new freezer. In 4 hours its temperature falls by 24 degrees. — with Vesper and Ines.",more:"The trick inside: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",art:"art/s-kitchen.webp",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|story|0"},"hook-divide-signs-hook":{id:"hook-divide-signs-hook",kind:"hook",src:"stop:divide-signs#hook",title:"Can you? — Dividing negatives",body:"−42 ÷ (−6). Positive or negative — and how would you know?",more:"The way in: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"Find out how",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn"},"idea-divide-signs-case0":{id:"idea-divide-signs-case0",kind:"idea",src:"stop:divide-signs#case0",title:"Dividing negatives: Negative ÷ positive",body:"A negative shared out stays negative: different signs give a negative answer.",more:"The method: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn|0"},"worked-divide-signs-worked0":{id:"worked-divide-signs-worked0",kind:"worked",src:"stop:divide-signs#worked0",title:"Worked out — Dividing negatives: Negative ÷ positive",body:"−42 ÷ 6: Ignore the signs: 42 ÷ 6 → 7 · The signs are different. So the answer is → -7",more:"What is special here: A negative shared out stays negative: different signs give a negative answer.",cta:"Watch it step by step",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn|0"},"idea-divide-signs-case1":{id:"idea-divide-signs-case1",kind:"idea",src:"stop:divide-signs#case1",title:"Dividing negatives: Positive ÷ negative",body:"Different signs again, just the other way round — still a negative answer. Check: what times −6 makes 42?",more:"The method: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn|1"},"idea-divide-signs-case2":{id:"idea-divide-signs-case2",kind:"idea",src:"stop:divide-signs#case2",title:"Dividing negatives: Negative ÷ negative",body:"Same signs, so the answer is positive — because a positive number times −6 is what makes −42.",more:"The method: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn|2"},"idea-divide-signs-case3":{id:"idea-divide-signs-case3",kind:"idea",src:"stop:divide-signs#case3",title:"Dividing negatives: Positive ÷ positive",body:"Same signs, positive answer: the ordinary division you already know. The rule just agrees with it.",more:"The method: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn|3"},"worked-divide-signs-worked3":{id:"worked-divide-signs-worked3",kind:"worked",src:"stop:divide-signs#worked3",title:"Worked out — Dividing negatives: Positive ÷ positive",body:"42 ÷ 6: Ignore the signs: 42 ÷ 6 → 7 · The signs are the same. So the answer is → 7",more:"What is special here: Same signs, positive answer: the ordinary division you already know. The rule just agrees with it.",cta:"Watch it step by step",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn|3"},"why-divide-signs-why1":{id:"why-divide-signs-why1",kind:"why",src:"stop:divide-signs#why1",title:"Why “Dividing negatives” works",body:"That is why division follows exactly the same sign rule as multiplication — every division is a multiplication read backwards. Same signs give a positive answer; different signs give a negative one.",more:"The trick: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn"},"why-divide-signs-why2":{id:"why-divide-signs-why2",kind:"why",src:"stop:divide-signs#why2",title:"Why “Dividing negatives” works",body:"Real life does this too. A freezer that cools by 24 degrees in 4 hours changes by −24 ÷ 4 = −6 degrees each hour: a negative change shared out stays negative. The size of the answer never depends on the signs; only the side of zero does.",more:"The trick: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn"},"moment-divide-signs-beat4":{id:"moment-divide-signs-beat4",kind:"moment",src:"story:divide-signs#beat4",badge:{id:"story",label:"A story"},title:"The new freezer — on the notepad",body:"Vesper: Check it backwards. Four hours of −6. 4 × (−6) = -24",more:"The trick in the story: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|story|4"},"moral-divide-signs-beat5":{id:"moral-divide-signs-beat5",kind:"moral",src:"story:divide-signs#beat5",badge:{id:"story",label:"A story"},title:"Ines, in “The new freezer”",body:"Minus six degrees an hour. Same rule as multiplying.",more:"The trick in the story: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|story|5"},"algebra-divide-signs-alg":{id:"algebra-divide-signs-alg",kind:"algebra",src:"stop:divide-signs#alg",title:"The algebra behind “Dividing negatives”",body:"(−a) ÷ b = −(a ÷ b) ; (−a) ÷ (−b) = a ÷ b",more:"In words: Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/divide-signs|learn"},"try-divide-signs-L7":{id:"try-divide-signs-L7",kind:"try",level:7,src:"try:divide-signs@7/1#0",title:"Dividing negatives — your turn",where:"The Deep Mine · Level 7",route:"#/stop/divide-signs|drill",cta:"Practise this stop",play:{q:"15 ÷ (−5) = ?",opts:["-3","3","1"],after:"Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative.",show:[2,0,1]}},"trick-negative-squares-idea":{id:"trick-negative-squares-idea",kind:"trick",src:"stop:negative-squares#idea",title:"Squares and brackets",body:"Powers come before the minus sign in front — unless brackets put the minus inside the square. (−3)² means (−3) × (−3): the bracket says square the whole thing, minus and all. Two negatives multiplied make a positive, so (−3)² = 9. Any number squared, below zero or above, is never negative.",more:"In algebra: (−a)² = a² ; −a² = −(a²) ; c − d × (−e) = c + de",cta:"Learn the trick",where:"The Deep Mine · Level 7",level:7,route:"#/stop/negative-squares|learn"},"story-negative-squares-open":{id:"story-negative-squares-open",kind:"story",src:"story:negative-squares#open",badge:{id:"story",label:"A story"},title:"The calculator argument",body:"In the library, Dax types −3² into a calculator and it says −9. He is sure it is broken. — with Theo and Dax.",more:"The trick inside: Powers come before the minus sign in front — unless brackets put the minus inside the square.",art:"art/s-library.webp",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/negative-squares|story|0"},"idea-negative-squares-case0":{id:"idea-negative-squares-case0",kind:"idea",src:"stop:negative-squares#case0",title:"Squares and brackets: Square in brackets",body:"The bracket puts the minus inside the square, so it is multiplied by itself too — and two negatives make a positive.",more:"The method: Powers come before the minus sign in front — unless brackets put the minus inside the square.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/negative-squares|learn|0"},"idea-negative-squares-case1":{id:"idea-negative-squares-case1",kind:"idea",src:"stop:negative-squares#case1",title:"Squares and brackets: Minus, no brackets",body:"No brackets, so the power goes first and the minus waits: square the number, then make it negative.",more:"The method: Powers come before the minus sign in front — unless brackets put the minus inside the square.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/negative-squares|learn|1"},"idea-negative-squares-case2":{id:"idea-negative-squares-case2",kind:"idea",src:"stop:negative-squares#case2",title:"Squares and brackets: Square, then take away",body:"Powers come before take-away: square the bracket first, then subtract.",more:"The method: Powers come before the minus sign in front — unless brackets put the minus inside the square.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/negative-squares|learn|2"},"idea-negative-squares-case3":{id:"idea-negative-squares-case3",kind:"idea",src:"stop:negative-squares#case3",title:"Squares and brackets: Times a negative",body:"Multiply before you take away. Then taking away a negative is the same as adding.",more:"The method: Powers come before the minus sign in front — unless brackets put the minus inside the square.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/negative-squares|learn|3"},"idea-negative-squares-case4":{id:"idea-negative-squares-case4",kind:"idea",src:"stop:negative-squares#case4",title:"Squares and brackets: Minus square plus a product",body:"Two jobs before the add: the power (square, then the minus) and the multiplication. Only then add.",more:"The method: Powers come before the minus sign in front — unless brackets put the minus inside the square.",cta:"See it worked",where:"The Deep Mine · Level 7",level:7,route:"#/stop/negative-squares|learn|4"},"why-negative-squares-why1":{id:"why-negative-squares-why1",kind:"why",src:"stop:negative-squares#why1",title:"Why “Squares and brackets” works",body:"But −3² has no brackets, and powers come before everything except brackets. So you square the 3 first, which is 9, and only then apply the minus: −3² = −9. It means “the negative of 3²”. Many calculators read it exactly this way.",more:"The trick: Powers come before the minus sign in front — unless brackets put the minus inside the square.",cta:"See why",where:"The Deep Mine · Level 7",level:7,route:"#/stop/negative-squares|learn"},"moment-negative-squares-beat3":{id:"moment-negative-squares-beat3",kind:"moment",src:"story:negative-squares#beat3",badge:{id:"story",label:"A story"},title:"The calculator argument — on the notepad",body:"Theo: Without them, the power goes first. Square the 3. 3 × 3 = 9",more:"The trick in the story: Powers come before the minus sign in front — unless brackets put the minus inside the square.",cta:"Read the story",where:"The Deep Mine · Level 7",level:7,route:"#/stop/negative-squares|story|3"},"try-negative-squares-L7":{id:"try-negative-squares-L7",kind:"try",level:7,src:"try:negative-squares@7/1#0",title:"Squares and brackets — your turn",where:"The Deep Mine · Level 7",route:"#/stop/negative-squares|drill",cta:"Practise this stop",play:{q:"(−8)² = ?",opts:["64","54","46"],after:"Powers come before the minus sign in front — unless brackets put the minus inside the square.",show:[2,1,0]}},"trick-number-types-idea":{id:"trick-number-types-idea",kind:"trick",src:"stop:number-types#idea",title:"Square, triangle, cube or prime",body:"Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime. Numbers have shapes. A square number of dots stands in a perfect square — 16 is 4 rows of 4. A triangular number stands in a triangle: a row of 1, then 2, then 3… so 10 is 1 + 2 + 3 + 4. A cube number stacks into a perfect cube: 27 is 3 layers of 3 × 3.",more:"In algebra: square n² · triangular 1 + 2 + … + n = n(n + 1) ÷ 2 · cube n³ · prime: factors only 1 and itself",cta:"Learn the trick",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn"},"story-number-types-open":{id:"story-number-types-open",kind:"story",src:"story:number-types#open",badge:{id:"story",label:"A story"},title:"The pebble shapes",body:"Mira has 28 smooth pebbles from the garden path. Can they make a square, a triangle or a cube? — with Mira and Pip.",more:"The trick inside: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",art:"art/s-garden.webp",cta:"Read the story",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|story|0"},"hook-number-types-hook":{id:"hook-number-types-hook",kind:"hook",src:"stop:number-types#hook",title:"Can you? — Square, triangle, cube or prime",body:"28 pebbles — can they make a square? A triangle? A cube? Or none of them?",more:"The way in: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"Find out how",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn"},"idea-number-types-case0":{id:"idea-number-types-case0",kind:"idea",src:"stop:number-types#case0",title:"Square, triangle, cube or prime: Square",body:"Some number of rows with that same number in each: 25 is 5 rows of 5.",more:"The method: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"See it worked",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn|0"},"worked-number-types-worked0":{id:"worked-number-types-worked0",kind:"worked",src:"stop:number-types#worked0",title:"Worked out — Square, triangle, cube or prime: Square",body:"25 dots — which shape can they make?: Is 25 a square — some number times itself? → Yes · So its shape is → square",more:"What is special here: Some number of rows with that same number in each: 25 is 5 rows of 5.",cta:"Watch it step by step",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn|0"},"idea-number-types-case1":{id:"idea-number-types-case1",kind:"idea",src:"stop:number-types#case1",title:"Square, triangle, cube or prime: Triangular",body:"Rows of 1, 2, 3… each one longer: keep adding the next number and see if you land on it exactly. 28 is 1 + 2 + … + 7.",more:"The method: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"See it worked",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn|1"},"worked-number-types-worked1":{id:"worked-number-types-worked1",kind:"worked",src:"stop:number-types#worked1",title:"Worked out — Square, triangle, cube or prime: Triangular",body:"28 dots — which shape can they make?: Is 28 a square — some number times itself? → No · Is 28 triangular — 1 + 2 + 3 + … up to some number? → Yes · So its shape is → triangular",more:"What is special here: Rows of 1, 2, 3… each one longer: keep adding the next number and see if you land on it exactly. 28 is 1 + 2 + … + 7.",cta:"Watch it step by step",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn|1"},"idea-number-types-case2":{id:"idea-number-types-case2",kind:"idea",src:"stop:number-types#case2",title:"Square, triangle, cube or prime: Cube",body:"Some number times itself, times itself again: 27 is 3 layers of 3 × 3. It is not a square, so test for a cube next.",more:"The method: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"See it worked",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn|2"},"idea-number-types-case3":{id:"idea-number-types-case3",kind:"idea",src:"stop:number-types#case3",title:"Square, triangle, cube or prime: Prime",body:"None of the three shapes fits, and the dots will only stand in one long line — no rectangle at all.",more:"The method: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"See it worked",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn|3"},"worked-number-types-worked3":{id:"worked-number-types-worked3",kind:"worked",src:"stop:number-types#worked3",title:"Worked out — Square, triangle, cube or prime: Prime",body:"23 dots — which shape can they make?: Is 23 a square — some number times itself? → No · Is 23 triangular — 1 + 2 + 3 + … up to some number? → No · Is 23 a cube — some number times itself, times itself again? → No · Is 23 prime — can it only stand in one straight line? → Yes · So its shape is → prime",more:"What is special here: None of the three shapes fits, and the dots will only stand in one long line — no rectangle at all.",cta:"Watch it step by step",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn|3"},"why-number-types-why1":{id:"why-number-types-why1",kind:"why",src:"stop:number-types#why1",title:"Why “Square, triangle, cube or prime” works",body:'A prime number refuses every rectangle. 7 dots can only stand in one long line of 7 — any other number of rows leaves some over. That is exactly what "its only factors are 1 and itself" means.',more:"The trick: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"See why",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn"},"why-number-types-why2":{id:"why-number-types-why2",kind:"why",src:"stop:number-types#why2",title:"Why “Square, triangle, cube or prime” works",body:"Some numbers wear two shapes: 36 is a square AND a triangle, and 64 is a square AND a cube. The questions here only use numbers with exactly one of these four shapes, so test them in order and stop at the first one that fits.",more:"The trick: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"See why",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn"},"moment-number-types-beat2":{id:"moment-number-types-beat2",kind:"moment",src:"story:number-types#beat2",badge:{id:"story",label:"A story"},title:"The pebble shapes — on the notepad",body:"Mira: A cube needs 3 × 3 × 3. That’s 27 — one pebble short of 28. 3 × 3 × 3 = 27",more:"The trick in the story: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"Read the story",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|story|2"},"moral-number-types-beat5":{id:"moral-number-types-beat5",kind:"moral",src:"story:number-types#beat5",badge:{id:"story",label:"A story"},title:"Pip, in “The pebble shapes”",body:"Every pebble used. 28 is triangular!",more:"The trick in the story: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"Read the story",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|story|5"},"algebra-number-types-alg":{id:"algebra-number-types-alg",kind:"algebra",src:"stop:number-types#alg",title:"The algebra behind “Square, triangle, cube or prime”",body:"square n² · triangular 1 + 2 + … + n = n(n + 1) ÷ 2 · cube n³ · prime: factors only 1 and itself",more:"In words: Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",cta:"See why",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/number-types|learn"},"try-number-types-L7":{id:"try-number-types-L7",kind:"try",level:7,src:"try:number-types@7/2#0",title:"Square, triangle, cube or prime — your turn",where:"The Prime Quarry · Level 7",route:"#/stop/number-types|drill",cta:"Practise this stop",play:{q:"9 dots — which shape can they make?",opts:["square","triangular","cube"],after:"Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime.",show:[2,0,1]}},"hook-prime-stones-hook":{id:"hook-prime-stones-hook",kind:"hook",src:"stop:prime-stones#hook",title:"Can you? — Building with prime stones",body:"2 × 2 × 3 × 5 — which number do these four stones build?",more:"The way in: Multiply the prime stones together one at a time. To find a missing stone, multiply the ones you have and divide.",cta:"Find out how",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/prime-stones|learn"},"worked-prime-stones-worked0":{id:"worked-prime-stones-worked0",kind:"worked",src:"stop:prime-stones#worked0",title:"Worked out — Building with prime stones: Build the number",body:"2 × 2 × 3 × 5 = ?: 2 × 2 → 4 · 4 × 3 → 12 · 12 × 5 → 60",more:"What is special here: Multiply the stones one at a time, carrying the answer along: 2 × 2, then × 3, then × 5.",cta:"Watch it step by step",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/prime-stones|learn|0"},"worked-prime-stones-worked1":{id:"worked-prime-stones-worked1",kind:"worked",src:"stop:prime-stones#worked1",title:"Worked out — Building with prime stones: Find the missing stone",body:"210 = 2 × 3 × 7 × ?: Multiply the stones you have: 2 × 3 × 7 → 42 · 210 ÷ 42 → 5",more:"What is special here: Backwards: multiply the stones you can see, then divide the number by that. What is left is the one missing prime.",cta:"Watch it step by step",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/prime-stones|learn|1"},"why-prime-stones-why2":{id:"why-prime-stones-why2",kind:"why",src:"stop:prime-stones#why2",title:"Why “Building with prime stones” works",body:"The surprising part is that there is only ONE set of stones for each number. Split 60 as 6 × 10 or as 4 × 15 and you still end with two 2s, a 3 and a 5. That is why a missing stone can always be found: the stones you are shown, multiplied, leave exactly one prime to finish the number.",more:"The trick: Multiply the prime stones together one at a time. To find a missing stone, multiply the ones you have and divide.",cta:"See why",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/prime-stones|learn"},"moral-prime-stones-beat5":{id:"moral-prime-stones-beat5",kind:"moral",src:"story:prime-stones#beat5",badge:{id:"story",label:"A story"},title:"Nova, in “Towers of stones”",body:"Every number has exactly one set of prime stones. Only the order can change.",more:"The trick in the story: Multiply the prime stones together one at a time. To find a missing stone, multiply the ones you have and divide.",cta:"Read the story",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/prime-stones|story|5"},"algebra-prime-stones-alg":{id:"algebra-prime-stones-alg",kind:"algebra",src:"stop:prime-stones#alg",title:"The algebra behind “Building with prime stones”",body:"every n > 1 = p₁ × p₂ × … × pₖ, one way only (apart from order)",more:"In words: Multiply the prime stones together one at a time. To find a missing stone, multiply the ones you have and divide.",cta:"See why",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/prime-stones|learn"},"try-prime-stones-L7":{id:"try-prime-stones-L7",kind:"try",level:7,src:"try:prime-stones@7/2#0",title:"Building with prime stones — your turn",where:"The Prime Quarry · Level 7",route:"#/stop/prime-stones|drill",cta:"Practise this stop",play:{q:"5 × 5 × 7 = ?",opts:["175","275","1750"],after:"Multiply the prime stones together one at a time. To find a missing stone, multiply the ones you have and divide.",show:[1,2,0]}},"trick-sieve-root-idea":{id:"trick-sieve-root-idea",kind:"trick",src:"stop:sieve-root#idea",title:"How far to test a prime",body:"Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one. If a number is NOT prime, it splits into two factors: 187 = 11 × 17. The two factors cannot both be bigger than 13, because 14 × 14 is already 196 — more than 187. So one of them is always 13 or smaller. If no prime up to 13 divides 187, nothing bigger can, and the number is prime.",more:"In algebra: n not prime ⇒ n has a prime factor p with p × p ≤ n",cta:"Learn the trick",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|learn"},"story-sieve-root-open":{id:"story-sieve-root-open",kind:"story",src:"story:sieve-root#open",badge:{id:"story",label:"A story"},title:"The library puzzle",body:"In the library, Theo finds a puzzle card: is 187 a prime number? — with Theo and Suki.",more:"The trick inside: Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",art:"art/s-library.webp",cta:"Read the story",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|story|0"},"hook-sieve-root-hook":{id:"hook-sieve-root-hook",kind:"hook",src:"stop:sieve-root#hook",title:"Can you? — How far to test a prime",body:"To check whether 187 is prime, must you try every number up to 186?",more:"The way in: Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",cta:"Find out how",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|learn"},"idea-sieve-root-case0":{id:"idea-sieve-root-case0",kind:"idea",src:"stop:sieve-root#case0",title:"How far to test a prime: The root is a prime",body:"13 × 13 = 169 is the last square not past 187, and 13 is itself prime — so 13 is the last one to try.",more:"The method: Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",cta:"See it worked",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|learn|0"},"worked-sieve-root-worked0":{id:"worked-sieve-root-worked0",kind:"worked",src:"stop:sieve-root#worked0",title:"Worked out — How far to test a prime: The root is a prime",body:"To test whether 187 is prime, what is the biggest prime you might have to try dividing by?: The biggest whole number whose square is not more than 187 → 13 · The biggest prime that is not more than 13 → 13",more:"What is special here: 13 × 13 = 169 is the last square not past 187, and 13 is itself prime — so 13 is the last one to try.",cta:"Watch it step by step",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|learn|0"},"idea-sieve-root-case1":{id:"idea-sieve-root-case1",kind:"idea",src:"stop:sieve-root#case1",title:"How far to test a prime: Step down to a prime",body:"14 × 14 = 196 is not past 221, but 14 is not prime. Step down to the biggest prime below it: 13.",more:"The method: Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",cta:"See it worked",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|learn|1"},"why-sieve-root-why1":{id:"why-sieve-root-why1",kind:"why",src:"stop:sieve-root#why1",title:"Why “How far to test a prime” works",body:"And you only try primes, because every other number is built from prime stones: if 9 went into a number, 3 would go in too, and you would already have found it. That is the idea of the sieve: write out the numbers, cross out the multiples of 2, then of 3, then 5, then 7… Whatever is never crossed out is prime.",more:"The trick: Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",cta:"See why",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|learn"},"why-sieve-root-why2":{id:"why-sieve-root-why2",kind:"why",src:"stop:sieve-root#why2",title:"Why “How far to test a prime” works",body:"So the job is: find the square just below your number, take its root, and the largest prime not bigger than that root is the last one you might need. For 187, 13 × 13 = 169 and 14 × 14 = 196, so the last prime to try is 13.",more:"The trick: Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",cta:"See why",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|learn"},"moment-sieve-root-beat3":{id:"moment-sieve-root-beat3",kind:"moment",src:"story:sieve-root#beat3",badge:{id:"story",label:"A story"},title:"The library puzzle — on the notepad",body:"Suki: 14 × 14 is 196, past 187. So if it splits, one factor is 13 or smaller. 14 × 14 = 196",more:"The trick in the story: Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",cta:"Read the story",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|story|3"},"moral-sieve-root-beat5":{id:"moral-sieve-root-beat5",kind:"moral",src:"story:sieve-root#beat5",badge:{id:"story",label:"A story"},title:"Suki, in “The library puzzle”",body:"Not prime. And the biggest prime we could ever have needed was 13.",more:"The trick in the story: Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",cta:"Read the story",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|story|5"},"algebra-sieve-root-alg":{id:"algebra-sieve-root-alg",kind:"algebra",src:"stop:sieve-root#alg",title:"The algebra behind “How far to test a prime”",body:"n not prime ⇒ n has a prime factor p with p × p ≤ n",more:"In words: Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",cta:"See why",where:"The Prime Quarry · Level 7",level:7,route:"#/stop/sieve-root|learn"},"try-sieve-root-L7":{id:"try-sieve-root-L7",kind:"try",level:7,src:"try:sieve-root@7/2#0",title:"How far to test a prime — your turn",where:"The Prime Quarry · Level 7",route:"#/stop/sieve-root|drill",cta:"Practise this stop",play:{q:"To test whether 389 is prime, what is the biggest prime you might have to try dividing by?",opts:["19","9","13"],after:"Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one.",show:[0,1,2]}},"trick-cube-and-root-idea":{id:"trick-cube-and-root-idea",kind:"trick",src:"stop:cube-and-root#idea",title:"Cubes and cube roots",body:`A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens. Stack 4 layers of a 4-by-4 square and you get a cube of blocks: 4 × 4 × 4 = 64. That is 4³, "four cubed" — a length, a width and a height all the same.`,more:"In algebra: n³ = n × n × n   ·   ∛(n³) = n",cta:"Learn the trick",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn"},"story-cube-and-root-open":{id:"story-cube-and-root-open",kind:"story",src:"story:cube-and-root#open",badge:{id:"story",label:"A story"},title:"The sugar-cube tower",body:"In the palace kitchen, Dax builds a giant cube from sugar cubes: 4 long, 4 wide and 4 high. — with Mira and Dax.",more:"The trick inside: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",art:"art/s-kitchen.webp",cta:"Read the story",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|story|0"},"hook-cube-and-root-hook":{id:"hook-cube-and-root-hook",kind:"hook",src:"stop:cube-and-root#hook",title:"Can you? — Cubes and cube roots",body:"4³ — and then: which number, cubed, makes 42,875?",more:"The way in: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",cta:"Find out how",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn"},"idea-cube-and-root-case0":{id:"idea-cube-and-root-case0",kind:"idea",src:"stop:cube-and-root#case0",title:"Cubes and cube roots: Cubing a number",body:"Three of the same number multiplied: a length, a width and a height all the same.",more:"The method: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",cta:"See it worked",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn|0"},"worked-cube-and-root-worked0":{id:"worked-cube-and-root-worked0",kind:"worked",src:"stop:cube-and-root#worked0",title:"Worked out — Cubes and cube roots: Cubing a number",body:"4³: 4 × 4 → 16 · 16 × 4 → 64",more:"What is special here: Three of the same number multiplied: a length, a width and a height all the same.",cta:"Watch it step by step",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn|0"},"idea-cube-and-root-case1":{id:"idea-cube-and-root-case1",kind:"idea",src:"stop:cube-and-root#case1",title:"Cubes and cube roots: A small cube root",body:"The last digit of a cube tells you exactly the last digit of its root — 2 and 8 swap, 3 and 7 swap.",more:"The method: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",cta:"See it worked",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn|1"},"worked-cube-and-root-worked1":{id:"worked-cube-and-root-worked1",kind:"worked",src:"stop:cube-and-root#worked1",title:"Worked out — Cubes and cube roots: A small cube root",body:"∛343: The last digit of 343 → 3 · So the root ends in → 7 · ∛343 → 7",more:"What is special here: The last digit of a cube tells you exactly the last digit of its root — 2 and 8 swap, 3 and 7 swap.",cta:"Watch it step by step",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn|1"},"idea-cube-and-root-case2":{id:"idea-cube-and-root-case2",kind:"idea",src:"stop:cube-and-root#case2",title:"Cubes and cube roots: A big cube root",body:"Two digits to find: drop the last three digits for the tens, and use the last digit for the ones.",more:"The method: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",cta:"See it worked",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn|2"},"worked-cube-and-root-worked2":{id:"worked-cube-and-root-worked2",kind:"worked",src:"stop:cube-and-root#worked2",title:"Worked out — Cubes and cube roots: A big cube root",body:"∛42,875: Drop the last three digits of 42,875 → 42 · Tens digit: the biggest cube not over that — its root → 3 · The last digit of 42,875 → 5 · So the root ends in → 5 · ∛42,875 → 35",more:"What is special here: Two digits to find: drop the last three digits for the tens, and use the last digit for the ones.",cta:"Watch it step by step",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn|2"},"why-cube-and-root-why1":{id:"why-cube-and-root-why1",kind:"why",src:"stop:cube-and-root#why1",title:"Why “Cubes and cube roots” works",body:"Cubes have a lovely secret. The last digits of 0³ to 9³ are 0, 1, 8, 7, 4, 5, 6, 3, 2, 9 — all ten different! So the last digit of a cube tells you EXACTLY the last digit of its root. 2 and 8 swap, 3 and 7 swap, the rest stay the same.",more:"The trick: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",cta:"See why",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn"},"why-cube-and-root-why2":{id:"why-cube-and-root-why2",kind:"why",src:"stop:cube-and-root#why2",title:"Why “Cubes and cube roots” works",body:"For the tens digit, drop the last three digits: 42,875 → 42. The biggest cube not over 42 is 27 = 3³, so the tens digit is 3. The cube ends in 5, so the root ends in 5. ∛42,875 = 35. This works because the ones digits only ever affect the last three places… plus a little carrying, which never reaches past the next cube up.",more:"The trick: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",cta:"See why",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn"},"moment-cube-and-root-beat2":{id:"moment-cube-and-root-beat2",kind:"moment",src:"story:cube-and-root#beat2",badge:{id:"story",label:"A story"},title:"The sugar-cube tower — on the notepad",body:"Mira: And there are four layers. That is 4 cubed — four, three times over. 16 × 4 = 64",more:"The trick in the story: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",cta:"Read the story",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|story|2"},"moral-cube-and-root-beat5":{id:"moral-cube-and-root-beat5",kind:"moral",src:"story:cube-and-root#beat5",badge:{id:"story",label:"A story"},title:"Dax, in “The sugar-cube tower”",body:"Thirty-five! But mine is smaller: sixty-four cubes, four on a side.",more:"The trick in the story: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",cta:"Read the story",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|story|5"},"algebra-cube-and-root-alg":{id:"algebra-cube-and-root-alg",kind:"algebra",src:"stop:cube-and-root#alg",title:"The algebra behind “Cubes and cube roots”",body:"n³ = n × n × n   ·   ∛(n³) = n",more:"In words: A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",cta:"See why",where:"The Square Palace · Level 7",level:7,route:"#/stop/cube-and-root|learn"},"try-cube-and-root-L7":{id:"try-cube-and-root-L7",kind:"try",level:7,src:"try:cube-and-root@7/1#0",title:"Cubes and cube roots — your turn",where:"The Square Palace · Level 7",route:"#/stop/cube-and-root|drill",cta:"Practise this stop",play:{q:"2³ = ?",opts:["8","4","14"],after:"A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens.",show:[2,1,0]}},"hook-percent-of-amount-hook":{id:"hook-percent-of-amount-hook",kind:"hook",src:"stop:percent-of-amount#hook",title:"Can you? — Percentages of an amount",body:"35% of 60 — no calculator on the dock.",more:"The way in: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.",cta:"Find out how",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-of-amount|learn"},"worked-percent-of-amount-worked0":{id:"worked-percent-of-amount-worked0",kind:"worked",src:"stop:percent-of-amount#worked0",title:"Worked out — Percentages of an amount: Just 10%",body:"10% of 60: How many tenths make the whole? → 10 · 10% of 60: 60 ÷ 10 → 6",more:"What is special here: 10% is one tenth, so divide by 10. Every other percentage here is built from this one.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-of-amount|learn|0"},"worked-percent-of-amount-worked1":{id:"worked-percent-of-amount-worked1",kind:"worked",src:"stop:percent-of-amount#worked1",title:"Worked out — Percentages of an amount: Lots of 10%",body:"30% of 60: 10% of 60: 60 ÷ 10 → 6 · 30%: 3 lots of 10% → 18",more:"What is special here: 30% is three lots of 10%: find 10% first, then multiply by how many tens.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-of-amount|learn|1"},"worked-percent-of-amount-worked2":{id:"worked-percent-of-amount-worked2",kind:"worked",src:"stop:percent-of-amount#worked2",title:"Worked out — Percentages of an amount: Just 5%",body:"5% of 60: 10% of 60: 60 ÷ 10 → 6 · 5%: half of 10% → 3",more:"What is special here: 5% is half of 10%, so find 10% and halve it.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-of-amount|learn|2"},"worked-percent-of-amount-worked3":{id:"worked-percent-of-amount-worked3",kind:"worked",src:"stop:percent-of-amount#worked3",title:"Worked out — Percentages of an amount: Tens and a 5",body:"35% of 60: 10% of 60: 60 ÷ 10 → 6 · 30%: 3 lots of 10% → 18 · 5%: half of 10% → 3 · Add them → 21",more:"What is special here: Split it into tens and a five: 35% is 30% and 5%. Find both, then add.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-of-amount|learn|3"},"why-percent-of-amount-why2":{id:"why-percent-of-amount-why2",kind:"why",src:"stop:percent-of-amount#why2",title:"Why “Percentages of an amount” works",body:"The hundred square shows it: each column is 10%, so you can see 35% as three columns and half a column. You never need to know a rule for 35% — only for 10%, and how to double, halve and add.",more:"The trick: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-of-amount|learn"},"moral-percent-of-amount-beat5":{id:"moral-percent-of-amount-beat5",kind:"moral",src:"story:percent-of-amount#beat5",badge:{id:"story",label:"A story"},title:"Rafi, in “The harbour tax”",body:"Add them up: 21 kg to the market.",more:"The trick in the story: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-of-amount|story|5"},"algebra-percent-of-amount-alg":{id:"algebra-percent-of-amount-alg",kind:"algebra",src:"stop:percent-of-amount#alg",title:"The algebra behind “Percentages of an amount”",body:"p% of n = (n ÷ 10) × (p ÷ 10)",more:"In words: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-of-amount|learn"},"try-percent-of-amount-L7":{id:"try-percent-of-amount-L7",kind:"try",level:7,src:"try:percent-of-amount@7/2#0",title:"Percentages of an amount — your turn",where:"The Decimal Dock · Level 7",route:"#/stop/percent-of-amount|drill",cta:"Practise this stop",play:{q:"80% of 220 = ?",opts:["176","22","76"],after:"Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.",show:[1,0,2]}},"trick-unitary-method-idea":{id:"trick-unitary-method-idea",kind:"trick",src:"stop:unitary-method#idea",title:"Find one, then scale",body:"Work out the amount for ONE, then multiply up to as many as you need. A recipe is a ratio: the flour grows exactly as the number of pancakes grows. But 4 and 6 are awkward to jump between — 6 is not a whole number of 4s.",more:"In algebra: amount for m = (amount for n ÷ n) × m",cta:"Learn the trick",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/unitary-method|learn"},"story-unitary-method-open":{id:"story-unitary-method-open",kind:"story",src:"story:unitary-method#open",badge:{id:"story",label:"A story"},title:"Pancakes for six",body:"The recipe makes 4 pancakes with 200 g of flour. Six people are coming for breakfast. — with Nova and Suki.",more:"The trick inside: Work out the amount for ONE, then multiply up to as many as you need.",art:"art/s-kitchen.webp",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/unitary-method|story|0"},"hook-unitary-method-hook":{id:"hook-unitary-method-hook",kind:"hook",src:"stop:unitary-method#hook",title:"Can you? — Find one, then scale",body:"4 pancakes need 200 g of flour. How much for 6?",more:"The way in: Work out the amount for ONE, then multiply up to as many as you need.",cta:"Find out how",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/unitary-method|learn"},"worked-unitary-method-worked0":{id:"worked-unitary-method-worked0",kind:"worked",src:"stop:unitary-method#worked0",title:"Worked out — Find one, then scale",body:"4 pancakes need 200 g of flour. How much for 6?: For 1: 200 ÷ 4 → 50 · For 6: × 6 → 300",more:"The method: Work out the amount for ONE, then multiply up to as many as you need.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/unitary-method|learn|0"},"why-unitary-method-why1":{id:"why-unitary-method-why1",kind:"why",src:"stop:unitary-method#why1",title:"Why “Find one, then scale” works",body:"One is the easy stop in the middle. 200 g for 4 pancakes means 200 ÷ 4 = 50 g for one pancake. Then 6 pancakes need 6 × 50 = 300 g.",more:"The trick: Work out the amount for ONE, then multiply up to as many as you need.",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/unitary-method|learn"},"why-unitary-method-why2":{id:"why-unitary-method-why2",kind:"why",src:"stop:unitary-method#why2",title:"Why “Find one, then scale” works",body:"It works for anything that goes up in step — prices, paint, petrol — which is why it is called the unitary method: go to one unit, then out again. Sometimes one unit is a decimal, like 2.5 g, and the method still holds.",more:"The trick: Work out the amount for ONE, then multiply up to as many as you need.",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/unitary-method|learn"},"moment-unitary-method-beat3":{id:"moment-unitary-method-beat3",kind:"moment",src:"story:unitary-method#beat3",badge:{id:"story",label:"A story"},title:"Pancakes for six — on the notepad",body:"Nova: 50 g for each pancake. Then six of them… 50 × 6 = 300",more:"The trick in the story: Work out the amount for ONE, then multiply up to as many as you need.",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/unitary-method|story|3"},"moral-unitary-method-beat5":{id:"moral-unitary-method-beat5",kind:"moral",src:"story:unitary-method#beat5",badge:{id:"story",label:"A story"},title:"Nova, in “Pancakes for six”",body:"300 g of flour for six pancakes.",more:"The trick in the story: Work out the amount for ONE, then multiply up to as many as you need.",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/unitary-method|story|5"},"algebra-unitary-method-alg":{id:"algebra-unitary-method-alg",kind:"algebra",src:"stop:unitary-method#alg",title:"The algebra behind “Find one, then scale”",body:"amount for m = (amount for n ÷ n) × m",more:"In words: Work out the amount for ONE, then multiply up to as many as you need.",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/unitary-method|learn"},"try-unitary-method-L7":{id:"try-unitary-method-L7",kind:"try",level:7,src:"try:unitary-method@7/1#0",title:"Find one, then scale — your turn",where:"The Decimal Dock · Level 7",route:"#/stop/unitary-method|drill",cta:"Practise this stop",play:{q:"4 bowls of soup need 40 ml of stock. How much for 6?",opts:["60","10","16"],after:"Work out the amount for ONE, then multiply up to as many as you need.",show:[1,0,2]}},"trick-percent-change-idea":{id:"trick-percent-change-idea",kind:"trick",src:"stop:percent-change#idea",title:"Sales and rises",body:"Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price). 20% off means you do not pay 20 of every 100. So work out 20% of 60 — 12 — and take it away: 48.",more:"In algebra: n with p% off = n × (100 − p)/100; n with p% added = n × (100 + p)/100",cta:"Learn the trick",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-change|learn"},"story-percent-change-open":{id:"story-percent-change-open",kind:"story",src:"story:percent-change#open",badge:{id:"story",label:"A story"},title:"The jacket sale",body:"A jacket costs 60 coins. The sign says 20% off. — with Ines and Dax.",more:"The trick inside: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).",art:"art/s-shop.webp",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-change|story|0"},"idea-percent-change-case0":{id:"idea-percent-change-case0",kind:"idea",src:"stop:percent-change#case0",title:"Sales and rises: Money off",body:"Find the percentage of the price, then take it away.",more:"The method: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).",cta:"See it worked",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-change|learn|0"},"idea-percent-change-case1":{id:"idea-percent-change-case1",kind:"idea",src:"stop:percent-change#case1",title:"Sales and rises: Money added",body:"The same two steps upwards: find the percentage, then add it on.",more:"The method: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).",cta:"See it worked",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-change|learn|1"},"idea-percent-change-case2":{id:"idea-percent-change-case2",kind:"idea",src:"stop:percent-change#case2",title:"Sales and rises: Off, in one step",body:"Think about what you DO pay: 35% off leaves 65%, so find 65% of the price straight away.",more:"The method: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).",cta:"See it worked",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-change|learn|2"},"idea-percent-change-case3":{id:"idea-percent-change-case3",kind:"idea",src:"stop:percent-change#case3",title:"Sales and rises: Added, in one step",body:"A rise of 15% makes 115% of the old amount — find that directly.",more:"The method: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).",cta:"See it worked",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-change|learn|3"},"why-percent-change-why1":{id:"why-percent-change-why1",kind:"why",src:"stop:percent-change#why1",title:"Why “Sales and rises” works",body:"Or think about what you DO pay. If 20% is taken off, 80% is left, and 80% of 60 is 48. One step instead of two, and the same answer, because 60 − 20% of 60 is 80% of 60.",more:"The trick: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-change|learn"},"moment-percent-change-beat3":{id:"moment-percent-change-beat3",kind:"moment",src:"story:percent-change#beat3",badge:{id:"story",label:"A story"},title:"The jacket sale — on the notepad",body:"Dax: Twelve off. So I pay… 60 − 12 = 48",more:"The trick in the story: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/percent-change|story|3"},"try-percent-change-L7":{id:"try-percent-change-L7",kind:"try",level:7,src:"try:percent-change@7/1#0",title:"Sales and rises — your turn",where:"The Decimal Dock · Level 7",route:"#/stop/percent-change|drill",cta:"Practise this stop",play:{q:"200 with 10% off = ?",opts:["180","20","810"],after:"Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).",show:[0,2,1]}},"trick-ratio-share-idea":{id:"trick-ratio-share-idea",kind:"trick",src:"stop:ratio-share#idea",title:"Ratio: simplify and share",body:"Add the parts to find how many equal shares there are. Find one share, then multiply. A ratio 2 : 5 says: for every 2 the first person gets, the second gets 5. Picture handing them out in rounds — each round uses 2 + 5 = 7 mangoes.",more:"In algebra: n shared in a : b → n ÷ (a + b) × a and n ÷ (a + b) × b",cta:"Learn the trick",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/ratio-share|learn"},"story-ratio-share-open":{id:"story-ratio-share-open",kind:"story",src:"story:ratio-share#open",badge:{id:"story",label:"A story"},title:"The mango crate",body:"Suki and Rafi fill a crate with 35 mangoes. Rafi picked 2 for every 5 Suki picked, so they share it 2 : 5. — with Rafi and Suki.",more:"The trick inside: Add the parts to find how many equal shares there are. Find one share, then multiply.",art:"art/s-market.webp",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/ratio-share|story|0"},"worked-ratio-share-worked0":{id:"worked-ratio-share-worked0",kind:"worked",src:"stop:ratio-share#worked0",title:"Worked out — Ratio: simplify and share: Share in a ratio",body:"Share 35 in the ratio 2 : 5. How much is the larger share?: Parts in one round: 2 + 5 → 7 · One part: 35 ÷ 7 → 5 · The larger share: × 5 → 25",more:"What is special here: Add the parts to get one round of sharing. Find one part, then multiply by the share you want.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/ratio-share|learn|0"},"why-ratio-share-why1":{id:"why-ratio-share-why1",kind:"why",src:"stop:ratio-share#why1",title:"Why “Ratio: simplify and share” works",body:"35 mangoes is 35 ÷ 7 = 5 rounds. So the first person gets 2 × 5 = 10 and the second gets 5 × 5 = 25. Check: 10 + 25 = 35, none left over.",more:"The trick: Add the parts to find how many equal shares there are. Find one share, then multiply.",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/ratio-share|learn"},"moral-ratio-share-beat5":{id:"moral-ratio-share-beat5",kind:"moral",src:"story:ratio-share#beat5",badge:{id:"story",label:"A story"},title:"Rafi, in “The mango crate”",body:"And 10 + 25 is all 35. Nothing left in the crate.",more:"The trick in the story: Add the parts to find how many equal shares there are. Find one share, then multiply.",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/ratio-share|story|5"},"try-ratio-share-L7":{id:"try-ratio-share-L7",kind:"try",level:7,src:"try:ratio-share@7/1#0",title:"Ratio: simplify and share — your turn",where:"The Decimal Dock · Level 7",route:"#/stop/ratio-share|drill",cta:"Practise this stop",play:{q:"Share 15 in the ratio 1 : 4. How much is the larger share?",opts:["12","5","21"],after:"Add the parts to find how many equal shares there are. Find one share, then multiply.",show:[0,2,1]}},"trick-speed-distance-time-idea":{id:"trick-speed-distance-time-idea",kind:"trick",src:"stop:speed-distance-time#idea",title:"Speed, distance and time",body:"Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide. 80 km/h means 80 kilometres in every hour. After 2 hours, 160 km; after 3 hours, 240 km. Distance is just the one-hour distance, taken as many times as there are hours.",more:"In algebra: d = s × t,  s = d ÷ t,  t = d ÷ s",cta:"Learn the trick",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn"},"story-speed-distance-time-open":{id:"story-speed-distance-time-open",kind:"story",src:"story:speed-distance-time#open",badge:{id:"story",label:"A story"},title:"The coast train",body:"Mira and Theo take the train to the coast: 240 km, and the train runs at 80 km/h. — with Mira and Theo.",more:"The trick inside: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",art:"art/s-train.webp",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|story|0"},"hook-speed-distance-time-hook":{id:"hook-speed-distance-time-hook",kind:"hook",src:"stop:speed-distance-time#hook",title:"Can you? — Speed, distance and time",body:"The ferry goes 240 km at 80 km/h. How long does the trip take?",more:"The way in: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"Find out how",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn"},"idea-speed-distance-time-case0":{id:"idea-speed-distance-time-case0",kind:"idea",src:"stop:speed-distance-time#case0",title:"Speed, distance and time: How far?",body:"Speed is the distance in one hour, so multiply it by the number of hours.",more:"The method: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"See it worked",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn|0"},"worked-speed-distance-time-worked0":{id:"worked-speed-distance-time-worked0",kind:"worked",src:"stop:speed-distance-time#worked0",title:"Worked out — Speed, distance and time: How far?",body:"80 km/h for 3 hours. How far, in km?: Km in one hour → 80 · In 3 hours: × 3 → 240",more:"What is special here: Speed is the distance in one hour, so multiply it by the number of hours.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn|0"},"idea-speed-distance-time-case1":{id:"idea-speed-distance-time-case1",kind:"idea",src:"stop:speed-distance-time#case1",title:"Speed, distance and time: How fast?",body:"Share the distance equally between the hours: that is the distance in one hour, the speed.",more:"The method: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"See it worked",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn|1"},"worked-speed-distance-time-worked1":{id:"worked-speed-distance-time-worked1",kind:"worked",src:"stop:speed-distance-time#worked1",title:"Worked out — Speed, distance and time: How fast?",body:"240 km in 3 hours. What speed, in km/h?: Hours taken → 3 · Km in one hour: 240 ÷ 3 → 80",more:"What is special here: Share the distance equally between the hours: that is the distance in one hour, the speed.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn|1"},"idea-speed-distance-time-case2":{id:"idea-speed-distance-time-case2",kind:"idea",src:"stop:speed-distance-time#case2",title:"Speed, distance and time: How long?",body:"Ask how many one-hour distances fit into the whole trip.",more:"The method: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"See it worked",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn|2"},"worked-speed-distance-time-worked2":{id:"worked-speed-distance-time-worked2",kind:"worked",src:"stop:speed-distance-time#worked2",title:"Worked out — Speed, distance and time: How long?",body:"240 km at 80 km/h. How many hours?: Km in one hour → 80 · How many 80s make 240? → 3",more:"What is special here: Ask how many one-hour distances fit into the whole trip.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn|2"},"idea-speed-distance-time-case3":{id:"idea-speed-distance-time-case3",kind:"idea",src:"stop:speed-distance-time#case3",title:"Speed, distance and time: Minutes, not hours",body:"Turn the minutes into a piece of an hour first: 20 minutes is a third, so you go a third of the speed.",more:"The method: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"See it worked",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn|3"},"worked-speed-distance-time-worked3":{id:"worked-speed-distance-time-worked3",kind:"worked",src:"stop:speed-distance-time#worked3",title:"Worked out — Speed, distance and time: Minutes, not hours",body:"30 km/h for 20 minutes. How far, in km?: How many 20-minute pieces make an hour? → 3 · Km in 20 minutes: 30 ÷ 3 → 10",more:"What is special here: Turn the minutes into a piece of an hour first: 20 minutes is a third, so you go a third of the speed.",cta:"Watch it step by step",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn|3"},"why-speed-distance-time-why1":{id:"why-speed-distance-time-why1",kind:"why",src:"stop:speed-distance-time#why1",title:"Why “Speed, distance and time” works",body:"So the other two questions are division. How long for 240 km? How many 80s make 240 — 3 hours. How fast, if 240 km took 3 hours? Share 240 between 3 hours — 80 each hour.",more:"The trick: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn"},"why-speed-distance-time-why2":{id:"why-speed-distance-time-why2",kind:"why",src:"stop:speed-distance-time#why2",title:"Why “Speed, distance and time” works",body:"Minutes are pieces of an hour. 20 minutes is a third of an hour, so at 30 km/h you go a third of 30: 10 km. Change the time into hours (or pieces of one) before you multiply.",more:"The trick: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn"},"moment-speed-distance-time-beat3":{id:"moment-speed-distance-time-beat3",kind:"moment",src:"story:speed-distance-time#beat3",badge:{id:"story",label:"A story"},title:"The coast train — on the notepad",body:"Mira: Three hours gets us all the way. 80 × 3 = 240",more:"The trick in the story: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|story|3"},"moral-speed-distance-time-beat5":{id:"moral-speed-distance-time-beat5",kind:"moral",src:"story:speed-distance-time#beat5",badge:{id:"story",label:"A story"},title:"Mira, in “The coast train”",body:"Three hours. Time for a sandwich.",more:"The trick in the story: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"Read the story",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|story|5"},"algebra-speed-distance-time-alg":{id:"algebra-speed-distance-time-alg",kind:"algebra",src:"stop:speed-distance-time#alg",title:"The algebra behind “Speed, distance and time”",body:"d = s × t,  s = d ÷ t,  t = d ÷ s",more:"In words: Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",cta:"See why",where:"The Decimal Dock · Level 7",level:7,route:"#/stop/speed-distance-time|learn"},"try-speed-distance-time-L7":{id:"try-speed-distance-time-L7",kind:"try",level:7,src:"try:speed-distance-time@7/1#0",title:"Speed, distance and time — your turn",where:"The Decimal Dock · Level 7",route:"#/stop/speed-distance-time|drill",cta:"Practise this stop",play:{q:"150 km in 3 hours. What speed, in km/h?",opts:["50","5","500"],after:"Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide.",show:[0,2,1]}},"trick-substitute-idea":{id:"trick-substitute-idea",kind:"trick",src:"stop:substitute#idea",title:"Letters for numbers",body:"A letter is a box holding a number. Put the number in the box, then do the sum — times before plus. 3n means 3 × n — in algebra we leave the × out so it does not get mixed up with the letter x. So when n = 4, 3n + 2 is 3 × 4 + 2 = 12 + 2 = 14.",more:"In algebra: an + b with n = k  →  a × k + b",cta:"Learn the trick",where:"Set Island · Level 7",level:7,route:"#/stop/substitute|learn"},"story-substitute-open":{id:"story-substitute-open",kind:"story",src:"story:substitute#open",badge:{id:"story",label:"A story"},title:"The matchstick pattern",body:"Pip builds a row of triangles out of matchsticks. Kwame writes on the board: matches = 3n + 2, for n triangles. — with Kwame and Pip.",more:"The trick inside: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.",art:"art/s-room.webp",cta:"Read the story",where:"Set Island · Level 7",level:7,route:"#/stop/substitute|story|0"},"idea-substitute-case0":{id:"idea-substitute-case0",kind:"idea",src:"stop:substitute#case0",title:"Letters for numbers: Times, then add",body:"3n is 3 × n — the × is hidden. Do the multiplying first, then the adding or taking away.",more:"The method: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/substitute|learn|0"},"idea-substitute-case1":{id:"idea-substitute-case1",kind:"idea",src:"stop:substitute#case1",title:"Letters for numbers: Brackets first",body:"A number outside brackets multiplies the whole bracket, so work out the inside first.",more:"The method: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/substitute|learn|1"},"idea-substitute-case2":{id:"idea-substitute-case2",kind:"idea",src:"stop:substitute#case2",title:"Letters for numbers: Squaring a negative",body:"n² is n × n. With a negative in the box, negative times negative is positive — so the square is never below zero.",more:"The method: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/substitute|learn|2"},"idea-substitute-case3":{id:"idea-substitute-case3",kind:"idea",src:"stop:substitute#case3",title:"Letters for numbers: Two letters",body:"Each letter has its own number. Fill both boxes, work out each term, then add — a negative term takes away.",more:"The method: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/substitute|learn|3"},"why-substitute-why1":{id:"why-substitute-why1",kind:"why",src:"stop:substitute#why1",title:"Why “Letters for numbers” works",body:'Why use a letter at all? Because one expression can describe a whole pattern. "Triangles in a row of n tiles use 3n + 2 matches" works for 4 tiles, for 40, for 400 — you only swap the number in the box.',more:"The trick: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.",cta:"See why",where:"Set Island · Level 7",level:7,route:"#/stop/substitute|learn"},"moment-substitute-beat4":{id:"moment-substitute-beat4",kind:"moment",src:"story:substitute#beat4",badge:{id:"story",label:"A story"},title:"The matchstick pattern — on the notepad",body:"Kwame: Then the plus 2. 12 + 2 = 14",more:"The trick in the story: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.",cta:"Read the story",where:"Set Island · Level 7",level:7,route:"#/stop/substitute|story|4"},"try-substitute-L7":{id:"try-substitute-L7",kind:"try",level:7,src:"try:substitute@7/1#0",title:"Letters for numbers — your turn",where:"Set Island · Level 7",route:"#/stop/substitute|drill",cta:"Practise this stop",play:{q:"If n = 8, what is 9n + 10?",opts:["82","820","92"],after:"A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.",show:[2,1,0]}},"trick-like-terms-idea":{id:"trick-like-terms-idea",kind:"trick",src:"stop:like-terms#idea",title:"Collecting like terms",body:'Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart. Think of x as an apple and y as a banana. 3 apples, 2 bananas, 4 more apples and 1 more banana: that is 7 apples and 3 bananas, 7x + 3y. You cannot add apples to bananas and call them 10 "applebananas" — so 10xy is wrong.',more:"In algebra: ax + bx = (a + b)x",cta:"Learn the trick",where:"Set Island · Level 7",level:7,route:"#/stop/like-terms|learn"},"story-like-terms-open":{id:"story-like-terms-open",kind:"story",src:"story:like-terms#open",badge:{id:"story",label:"A story"},title:"The fruit basket",body:"Ines writes the market order in algebra: x for a crate of apples, y for bananas. 3x + 2y + 4x + y. — with Ines and Nova.",more:"The trick inside: Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart.",art:"art/s-market.webp",cta:"Read the story",where:"Set Island · Level 7",level:7,route:"#/stop/like-terms|story|0"},"idea-like-terms-case0":{id:"idea-like-terms-case0",kind:"idea",src:"stop:like-terms#case0",title:"Collecting like terms: One letter",body:"Every term is the same kind of thing, so just add the numbers in front. A letter on its own means 1 of it.",more:"The method: Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/like-terms|learn|0"},"idea-like-terms-case1":{id:"idea-like-terms-case1",kind:"idea",src:"stop:like-terms#case1",title:"Collecting like terms: Two letters",body:"Keep x's with x's and y's with y's. The answer has two terms — you cannot add apples to bananas.",more:"The method: Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/like-terms|learn|1"},"idea-like-terms-case2":{id:"idea-like-terms-case2",kind:"idea",src:"stop:like-terms#case2",title:"Collecting like terms: Taking away x's",body:"The minus sign belongs to the term after it. More x's taken than you had leaves a negative number in front.",more:"The method: Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/like-terms|learn|2"},"why-like-terms-why1":{id:"why-like-terms-why1",kind:"why",src:"stop:like-terms#why1",title:"Why “Collecting like terms” works",body:"This works because x is the same number every time it appears. 3x + 4x means 3 lots of that number and 4 more lots of it: 7 lots, whatever it is.",more:"The trick: Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart.",cta:"See why",where:"Set Island · Level 7",level:7,route:"#/stop/like-terms|learn"},"moment-like-terms-beat3":{id:"moment-like-terms-beat3",kind:"moment",src:"story:like-terms#beat3",badge:{id:"story",label:"A story"},title:"The fruit basket — on the notepad",body:"Nova: And bananas with bananas. The lone y means one crate. 2 + 1 = 3",more:"The trick in the story: Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart.",cta:"Read the story",where:"Set Island · Level 7",level:7,route:"#/stop/like-terms|story|3"},"try-like-terms-L7":{id:"try-like-terms-L7",kind:"try",level:7,src:"try:like-terms@7/1#0",title:"Collecting like terms — your turn",where:"Set Island · Level 7",route:"#/stop/like-terms|drill",cta:"Practise this stop",play:{q:"6x + 4x + x = □x. What goes in the box?",opts:["11","10","7"],after:"Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart.",show:[2,0,1]}},"trick-solve-balance-idea":{id:"trick-solve-balance-idea",kind:"trick",src:"stop:solve-balance#idea",title:"Solving equations on a balance",body:"An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone. Picture a balance: three bags of x sweets and 4 loose sweets on one side, 19 sweets on the other, perfectly level. Take 4 loose sweets off BOTH sides and it is still level: 3 bags balance 15 sweets.",more:"In algebra: ax + b = c  ⇒  x = (c − b) ÷ a",cta:"Learn the trick",where:"Set Island · Level 7",level:7,route:"#/stop/solve-balance|learn"},"story-solve-balance-open":{id:"story-solve-balance-open",kind:"story",src:"story:solve-balance#open",badge:{id:"story",label:"A story"},title:"The weighing scale",body:"On the shop scale: 3 bags of marbles and 4 loose marbles balance 19 loose marbles. Every bag holds the same. — with Kwame and Suki.",more:"The trick inside: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.",art:"art/s-shop.webp",cta:"Read the story",where:"Set Island · Level 7",level:7,route:"#/stop/solve-balance|story|0"},"idea-solve-balance-case0":{id:"idea-solve-balance-case0",kind:"idea",src:"stop:solve-balance#case0",title:"Solving equations on a balance: Undo an add",body:"Something was added to x. Take the same amount off both sides and x stands alone.",more:"The method: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/solve-balance|learn|0"},"idea-solve-balance-case1":{id:"idea-solve-balance-case1",kind:"idea",src:"stop:solve-balance#case1",title:"Solving equations on a balance: Undo a times",body:"4x means four x's. Share both sides into four equal parts to find one x.",more:"The method: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/solve-balance|learn|1"},"idea-solve-balance-case2":{id:"idea-solve-balance-case2",kind:"idea",src:"stop:solve-balance#case2",title:"Solving equations on a balance: Two steps",body:"Undo the last thing first: take away the plain number, THEN share. Doing it the other way round breaks the balance sum.",more:"The method: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/solve-balance|learn|2"},"idea-solve-balance-case3":{id:"idea-solve-balance-case3",kind:"idea",src:"stop:solve-balance#case3",title:"Solving equations on a balance: Words into an equation",body:"Write the words as an equation first. Here a number was taken away, so undo it by adding to both sides.",more:"The method: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.",cta:"See it worked",where:"Set Island · Level 7",level:7,route:"#/stop/solve-balance|learn|3"},"why-solve-balance-why1":{id:"why-solve-balance-why1",kind:"why",src:"stop:solve-balance#why1",title:"Why “Solving equations on a balance” works",body:"Now split both sides into three equal shares: one bag balances 5 sweets. So x = 5. Whatever you do to one side, you do to the other — that is the one rule, and it is why the answer is guaranteed to be right.",more:"The trick: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.",cta:"See why",where:"Set Island · Level 7",level:7,route:"#/stop/solve-balance|learn"},"moment-solve-balance-beat3":{id:"moment-solve-balance-beat3",kind:"moment",src:"story:solve-balance#beat3",badge:{id:"story",label:"A story"},title:"The weighing scale — on the notepad",body:"Suki: Three bags balance fifteen. So share both sides into three. 15 ÷ 3 = 5",more:"The trick in the story: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.",cta:"Read the story",where:"Set Island · Level 7",level:7,route:"#/stop/solve-balance|story|3"},"try-solve-balance-L7":{id:"try-solve-balance-L7",kind:"try",level:7,src:"try:solve-balance@7/1#0",title:"Solving equations on a balance — your turn",where:"Set Island · Level 7",route:"#/stop/solve-balance|drill",cta:"Practise this stop",play:{q:"x + 17 = 23. What is x?",opts:["6","5","17"],after:"An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.",show:[0,1,2]}},"hook-flag-division-hook":{id:"hook-flag-division-hook",kind:"hook",src:"stop:flag-division#hook",title:"Can you? — Straight division: the flag",body:"1748 ÷ 23 — any two-digit divisor, in one line.",more:'The way in: Divide by the first digit only. The other digit is a "flag": before each step, take flag × the last answer digit away.',cta:"Find out how",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/flag-division|learn"},"idea-flag-division-case1":{id:"idea-flag-division-case1",kind:"idea",src:"stop:flag-division#case1",title:"Straight division: the flag: One flag, one less",body:"A column would go below zero, so the answer digit before it is taken one less — and the remainder grows to pay for it.",more:'The method: Divide by the first digit only. The other digit is a "flag": before each step, take flag × the last answer digit away.',cta:"See it worked",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/flag-division|learn|1"},"worked-flag-division-worked2":{id:"worked-flag-division-worked2",kind:"worked",src:"stop:flag-division#worked2",title:"Worked out — Straight division: the flag: Two flags",body:"26838 ÷ 213: how many whole 213s?: Divide by 2 (flag 1 and 3): 2 ÷ 2 → 1 · Next column: 6 − 1 × 1 = 5. 5 ÷ 2 → 2 · Next column: 18 − 1 × 2 − 3 × 1 = 13. 13 ÷ 2 → 6 · What is left in the last column: the remainder → 0 · Read the answer digits 1 2 6 → 126",more:"What is special here: A three-digit divisor flies two flag digits. Each column pays for the last TWO answer digits: first flag × the newer one, second flag × the one before.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/flag-division|learn|2"},"sutra-flag-division-sutra":{id:"sutra-flag-division-sutra",kind:"sutra",src:"stop:flag-division#sutra",title:"Ūrdhva-tiryagbhyām",body:"“vertically and crosswise” — the sutra behind Straight division: the flag.",more:'What it does: Divide by the first digit only. The other digit is a "flag": before each step, take flag × the last answer digit away.',cta:"Open the stop",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/flag-division|learn"},"algebra-flag-division-alg":{id:"algebra-flag-division-alg",kind:"algebra",src:"stop:flag-division#alg",title:"The algebra behind “Straight division: the flag”",body:"N = (10m + f)·Q + R: each column = (carried remainder)·10 + next digit − f × previous answer digit; answer digit = column ÷ m",more:'In words: Divide by the first digit only. The other digit is a "flag": before each step, take flag × the last answer digit away.',cta:"See why",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/flag-division|learn"},"try-flag-division-L7":{id:"try-flag-division-L7",kind:"try",level:7,src:"try:flag-division@7/2#0",title:"Straight division: the flag — your turn",where:"The Sutra Ladder · Level 7",route:"#/stop/flag-division|drill",cta:"Practise this stop",play:{q:"6573 ÷ 36: how many whole 36s?",opts:["182","21","192"],after:'Divide by the first digit only. The other digit is a "flag": before each step, take flag × the last answer digit away.',show:[2,1,0]}},"hook-duplex-hook":{id:"hook-duplex-hook",kind:"hook",src:"stop:duplex#hook",title:"Can you? — The duplex, and any square",body:"473² — a three-digit square, written down left to right.",more:"The way in: The duplex of a row of digits is twice each outer-and-inner pair, plus the middle digit squared. A square is its duplexes, column by column.",cta:"Find out how",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/duplex|learn"},"worked-duplex-worked0":{id:"worked-duplex-worked0",kind:"worked",src:"stop:duplex#worked0",title:"Worked out — The duplex, and any square: Duplex of two digits",body:"The duplex of 47: 4 × 7 → 28 · Double it → 56",more:"What is special here: Two digits: multiply them, and double it.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/duplex|learn|0"},"worked-duplex-worked1":{id:"worked-duplex-worked1",kind:"worked",src:"stop:duplex#worked1",title:"Worked out — The duplex, and any square: Duplex of three digits",body:"The duplex of 473: Twice the outer pair: 2 × 4 × 3 → 24 · The middle, squared: 7² → 49 · Add them → 73",more:"What is special here: Three digits: twice the outer pair, plus the middle digit squared.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/duplex|learn|1"},"worked-duplex-worked2":{id:"worked-duplex-worked2",kind:"worked",src:"stop:duplex#worked2",title:"Worked out — The duplex, and any square: Duplex of four digits",body:"The duplex of 2315: Twice the outer pair: 2 × 2 × 5 → 20 · Twice the inner pair: 2 × 3 × 1 → 6 · Add them → 26",more:"What is special here: Four digits: no middle digit, so twice the outer pair plus twice the inner pair.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/duplex|learn|2"},"worked-duplex-worked3":{id:"worked-duplex-worked3",kind:"worked",src:"stop:duplex#worked3",title:"Worked out — The duplex, and any square: A whole square",body:"473²: Duplex of 47 → 56 · Duplex of 473 → 73 · Duplex of 73 → 42 · Columns 16 | 56 | 73 | 42 | 9: carry from the right → 223729",more:"What is special here: Write the duplex of each column, left to right, then carry from the right.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/duplex|learn|3"},"why-duplex-why2":{id:"why-duplex-why2",kind:"why",src:"stop:duplex#why2",title:"Why “The duplex, and any square” works",body:"So 473² is the duplexes of 4, 47, 473, 73 and 3: 16 | 56 | 73 | 42 | 9. Carry from the right: 9; 42 → 2 carry 4; 73 + 4 = 77 → 7 carry 7; 56 + 7 = 63 → 3 carry 6; 16 + 6 = 22. Answer 223729.",more:"The trick: The duplex of a row of digits is twice each outer-and-inner pair, plus the middle digit squared. A square is its duplexes, column by column.",cta:"See why",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/duplex|learn"},"moment-duplex-beat2":{id:"moment-duplex-beat2",kind:"moment",src:"story:duplex#beat2",badge:{id:"story",label:"A story"},title:"The giant mosaic — on the notepad",body:"Rafi: The duplex of 473: twice the outer pair, plus the middle squared. 2 × 4 × 3 + 7 × 7 = 73",more:"The trick in the story: The duplex of a row of digits is twice each outer-and-inner pair, plus the middle digit squared. A square is its duplexes, column by column.",cta:"Read the story",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/duplex|story|2"},"algebra-duplex-alg":{id:"algebra-duplex-alg",kind:"algebra",src:"stop:duplex#alg",title:"The algebra behind “The duplex, and any square”",body:"(100a + 10b + c)² = a²·10⁴ + 2ab·10³ + (2ac + b²)·10² + 2bc·10 + c²",more:"In words: The duplex of a row of digits is twice each outer-and-inner pair, plus the middle digit squared. A square is its duplexes, column by column.",cta:"See why",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/duplex|learn"},"try-duplex-L7":{id:"try-duplex-L7",kind:"try",level:7,src:"try:duplex@7/2#0",title:"The duplex, and any square — your turn",where:"The Sutra Ladder · Level 7",route:"#/stop/duplex|drill",cta:"Practise this stop",play:{q:"The duplex of 7346 = ?",opts:["108","24","208"],after:"The duplex of a row of digits is twice each outer-and-inner pair, plus the middle digit squared. A square is its duplexes, column by column.",show:[0,1,2]}},"hook-root-by-sight-hook":{id:"hook-root-by-sight-hook",kind:"hook",src:"stop:root-by-sight#hook",title:"Can you? — Square roots by sight",body:"√5776 — in your head, in two looks.",more:"The way in: The last digit gives two possible endings; the first group gives the tens and decides which ending it is.",cta:"Find out how",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/root-by-sight|learn"},"worked-root-by-sight-worked0":{id:"worked-root-by-sight-worked0",kind:"worked",src:"stop:root-by-sight#worked0",title:"Worked out — Square roots by sight: Only one ending",body:"√4225: 4225 ends in 5, so the root ends in 5. Cover the last two digits: 42. The biggest square not over it is ?² → 6 · Tens 6, ending 5: the root → 65",more:"What is special here: The square ends in 5 or 0, so the root has only one possible last digit.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/root-by-sight|learn|0"},"worked-root-by-sight-worked1":{id:"worked-root-by-sight-worked1",kind:"worked",src:"stop:root-by-sight#worked1",title:"Worked out — Square roots by sight: The lower ending",body:"√2809: 2809 ends in 9, so the root ends in 3 or 7. Cover the last two digits: 28. The biggest square not over it is ?² → 5 · 5 × 6 → 30 · Is 28 at least 30? Yes: the higher ending (57); no: the lower (53). The root → 53",more:"What is special here: The first group is less than t × (t + 1), so the root is below t5: take the lower ending.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/root-by-sight|learn|1"},"worked-root-by-sight-worked2":{id:"worked-root-by-sight-worked2",kind:"worked",src:"stop:root-by-sight#worked2",title:"Worked out — Square roots by sight: The higher ending",body:"√5776: 5776 ends in 6, so the root ends in 4 or 6. Cover the last two digits: 57. The biggest square not over it is ?² → 7 · 7 × 8 → 56 · Is 57 at least 56? Yes: the higher ending (76); no: the lower (74). The root → 76",more:"What is special here: The first group is at least t × (t + 1), so the root is above t5: take the higher ending.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/root-by-sight|learn|2"},"why-root-by-sight-why2":{id:"why-root-by-sight-why2",kind:"why",src:"stop:root-by-sight#why2",title:"Why “Square roots by sight” works",body:"You never need 75² itself: 7 × 8 = 56, and 57 is at least 56, so take the higher ending. If the first group were below 56, the lower one. A root ending in 5 or 0 has only one choice.",more:"The trick: The last digit gives two possible endings; the first group gives the tens and decides which ending it is.",cta:"See why",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/root-by-sight|learn"},"moment-root-by-sight-beat4":{id:"moment-root-by-sight-beat4",kind:"moment",src:"story:root-by-sight#beat4",badge:{id:"story",label:"A story"},title:"The paving square — on the notepad",body:"Mira: 7 × 8 is 56, and 57 is at least 56. So the side is above 75. 7 × 8 = 56",more:"The trick in the story: The last digit gives two possible endings; the first group gives the tens and decides which ending it is.",cta:"Read the story",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/root-by-sight|story|4"},"algebra-root-by-sight-alg":{id:"algebra-root-by-sight-alg",kind:"algebra",src:"stop:root-by-sight#alg",title:"The algebra behind “Square roots by sight”",body:"(10t + 5)² = 100·t(t + 1) + 25, so the root is above 10t + 5 exactly when the first group is at least t(t + 1)",more:"In words: The last digit gives two possible endings; the first group gives the tens and decides which ending it is.",cta:"See why",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/root-by-sight|learn"},"try-root-by-sight-L7":{id:"try-root-by-sight-L7",kind:"try",level:7,src:"try:root-by-sight@7/2#0",title:"Square roots by sight — your turn",where:"The Sutra Ladder · Level 7",route:"#/stop/root-by-sight|drill",cta:"Practise this stop",play:{q:"√3136 = ?",opts:["56","30","46"],after:"The last digit gives two possible endings; the first group gives the tens and decides which ending it is.",show:[2,0,1]}},"trick-cube-root-sight-idea":{id:"trick-cube-root-sight-idea",kind:"trick",src:"stop:cube-root-sight#idea",title:"Cube roots by sight",body:"The last digit of a cube names the last digit of its root; the digits before the last three give the tens. Cube the digits 0 to 9 and look only at the last digit: 1, 8, 27, 64, 125, 216, 343, 512, 729 end in 1, 8, 7, 4, 5, 6, 3, 2, 9. Every ending is different — so the last digit of a cube tells you the last digit of its root. Most stay the same; 2 and 8 swap, and 3 and 7 swap.",more:"In algebra: (10t + u)³ = 1000t³ + 300t²u + 30tu² + u³, so the last digit is the last digit of u³ and the thousands lie between t³ and (t + 1)³",cta:"Learn the trick",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/cube-root-sight|learn"},"story-cube-root-sight-open":{id:"story-cube-root-sight-open",kind:"story",src:"story:cube-root-sight#open",badge:{id:"story",label:"A story"},title:"The sugar-cube cube",body:"For the school fair, Nova’s family stacks 54872 sugar cubes into one giant cube. How many cubes along each edge? — with Nova and Theo.",more:"The trick inside: The last digit of a cube names the last digit of its root; the digits before the last three give the tens.",art:"art/s-kitchen.webp",cta:"Read the story",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/cube-root-sight|story|0"},"worked-cube-root-sight-worked0":{id:"worked-cube-root-sight-worked0",kind:"worked",src:"stop:cube-root-sight#worked0",title:"Worked out — Cube roots by sight: The ending stays",body:"The cube root of 39304: 39304 ends in 4. The root ends in → 4 · Cover the last three digits: 39. The biggest cube not over it is ?³ → 3 · Tens 3, ending 4: the root → 34",more:"What is special here: Endings 0, 1, 4, 5, 6 and 9 come back as themselves.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/cube-root-sight|learn|0"},"why-cube-root-sight-why1":{id:"why-cube-root-sight-why1",kind:"why",src:"stop:cube-root-sight#why1",title:"Why “Cube roots by sight” works",body:"Now cover the last three digits of 54872: 54 is left. 3³ = 27 and 4³ = 64, so 54 sits between them and the root is in the thirties. With the ending 8 (from the 2), the root is 38.",more:"The trick: The last digit of a cube names the last digit of its root; the digits before the last three give the tens.",cta:"See why",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/cube-root-sight|learn"},"moment-cube-root-sight-beat2":{id:"moment-cube-root-sight-beat2",kind:"moment",src:"story:cube-root-sight#beat2",badge:{id:"story",label:"A story"},title:"The sugar-cube cube — on the notepad",body:"Theo: Cover the last three digits: 54. 3 cubed is 27 and 4 cubed is 64. 3 × 3 × 3 = 27",more:"The trick in the story: The last digit of a cube names the last digit of its root; the digits before the last three give the tens.",cta:"Read the story",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/cube-root-sight|story|2"},"try-cube-root-sight-L7":{id:"try-cube-root-sight-L7",kind:"try",level:7,src:"try:cube-root-sight@7/1#0",title:"Cube roots by sight — your turn",where:"The Sutra Ladder · Level 7",route:"#/stop/cube-root-sight|drill",cta:"Practise this stop",play:{q:"The cube root of 6859 = ?",opts:["19","9","91"],after:"The last digit of a cube names the last digit of its root; the digits before the last three give the tens.",show:[1,2,0]}},"trick-osculator-idea":{id:"trick-osculator-idea",kind:"trick",src:"stop:osculator#idea",title:"Divisibility by osculators",body:"Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small. For 19, the osculator is one more than the digit before the 9: 1 + 1 = 2. To test 4807: chop the 7, double it, add it to 480: 494. Again: 49 + 2 × 4 = 57. And 57 = 3 × 19, so 4807 is in the 19 times table too.",more:"In algebra: If p × k = 10m − 1, then 10a + b and a + m·b are both in the p times table or both not: 10(a + mb) − (10a + b) = b(10m − 1)",cta:"Learn the trick",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/osculator|learn"},"story-osculator-open":{id:"story-osculator-open",kind:"story",src:"story:osculator#open",badge:{id:"story",label:"A story"},title:"Shelves of nineteen",body:"The library has 4807 new books for shelves that hold 19 each. Will every shelf be exactly full? — with Ines and Theo.",more:"The trick inside: Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small.",art:"art/s-library.webp",cta:"Read the story",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/osculator|story|0"},"worked-osculator-worked0":{id:"worked-osculator-worked0",kind:"worked",src:"stop:osculator#worked0",title:"Worked out — Divisibility by osculators: The osculator: ends in 9",body:"The osculator for 29?: 29 ends in 9. The digits before the 9 → 2 · One more than that → 3",more:"What is special here: A divisor ending in 9: one more than the digits before the 9.",cta:"Watch it step by step",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/osculator|learn|0"},"idea-osculator-case2":{id:"idea-osculator-case2",kind:"idea",src:"stop:osculator#case2",title:"Divisibility by osculators: Testing a number",body:"Chop, multiply by the osculator, add — and repeat — until the number is small enough to know.",more:"The method: Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small.",cta:"See it worked",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/osculator|learn|2"},"why-osculator-why2":{id:"why-osculator-why2",kind:"why",src:"stop:osculator#why2",title:"Why “Divisibility by osculators” works",body:'A divisor that does not end in 9 is first multiplied until it does: 7 × 7 = 49, so the osculator for 7 is 5; 13 × 3 = 39 gives 4; 17 × 7 = 119 gives 12. The book uses this "one more than the one before" for 19, 29, 39 and on to any divisor that ends in 1, 3, 7 or 9.',more:"The trick: Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small.",cta:"See why",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/osculator|learn"},"moral-osculator-beat5":{id:"moral-osculator-beat5",kind:"moral",src:"story:osculator#beat5",badge:{id:"story",label:"A story"},title:"Ines, in “Shelves of nineteen”",body:"Every shelf full: 253 of them.",more:"The trick in the story: Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small.",cta:"Read the story",where:"The Sutra Ladder · Level 7",level:7,route:"#/stop/osculator|story|5"},"try-osculator-L7":{id:"try-osculator-L7",kind:"try",level:7,src:"try:osculator@7/1#0",title:"Divisibility by osculators — your turn",where:"The Sutra Ladder · Level 7",route:"#/stop/osculator|drill",cta:"Practise this stop",play:{q:"Is 878 divisible by 19?",opts:["No","Yes"],after:"Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small.",show:[0,1]}},"hook-excess-deficit-hook":{id:"hook-excess-deficit-hook",kind:"hook",src:"stop:excess-deficit#hook",title:"Can you? — Too many, too few",body:"Pay 8 each and there are 3 coins too many; pay 7 each and you are 4 short. How many friends?",more:"The way in: The gap between the two ways of paying, divided by the difference in what each person pays, is the number of people.",cta:"Find out how",where:"The Counting Court · Level 7",level:7,route:"#/stop/excess-deficit|learn"},"worked-excess-deficit-worked0":{id:"worked-excess-deficit-worked0",kind:"worked",src:"stop:excess-deficit#worked0",title:"Worked out — Too many, too few: How many people?",body:"Some friends club together to buy a present. If each pays 8 coins, there are 3 coins too many; if each pays 7 coins, they are 4 coins short. How many friends are there?: Too many plus too few: how far apart are the two collections? → 7 · Each friend pays 8 − 7 more the first way → 1 · Divide: the number of friends → 7",more:"What is special here: Over plus short is the gap; divide by how much more each pays.",cta:"Watch it step by step",where:"The Counting Court · Level 7",level:7,route:"#/stop/excess-deficit|learn|0"},"worked-excess-deficit-worked1":{id:"worked-excess-deficit-worked1",kind:"worked",src:"stop:excess-deficit#worked1",title:"Worked out — Too many, too few: What does it cost?",body:"Some friends club together to buy a football. If each pays 9 coins, there are 4 coins too many; if each pays 7 coins, they are 8 coins short. What does the football cost, in coins?: Too many plus too few: how far apart are the two collections? → 12 · Each friend pays 9 − 7 more the first way → 2 · Divide: the number of friends → 6 · Everyone pays 9; give back the 4 too many → 50",more:"What is special here: Find the people first, then everyone pays and you give back the extra.",cta:"Watch it step by step",where:"The Counting Court · Level 7",level:7,route:"#/stop/excess-deficit|learn|1"},"worked-excess-deficit-worked2":{id:"worked-excess-deficit-worked2",kind:"worked",src:"stop:excess-deficit#worked2",title:"Worked out — Too many, too few: Over both times",body:"Some friends club together to buy a kite. If each pays 9 coins, there are 14 coins too many; if each pays 7 coins, there are still 4 coins too many. How many friends are there?: Over both times: the two collections differ by 14 − 4 → 10 · Each friend pays 9 − 7 more the first way → 2 · Divide: the number of friends → 5",more:"What is special here: Both collections overshoot (or both fall short): the gap is the difference.",cta:"Watch it step by step",where:"The Counting Court · Level 7",level:7,route:"#/stop/excess-deficit|learn|2"},"why-excess-deficit-why2":{id:"why-excess-deficit-why2",kind:"why",src:"stop:excess-deficit#why2",title:"Why “Too many, too few” works",body:"If both ways leave coins over (or both leave you short), the two collections are the DIFFERENCE of the two gaps apart, not the sum — so subtract instead of adding. Once you know how many people, the price is easy: everyone pays the first amount, less what was over.",more:"The trick: The gap between the two ways of paying, divided by the difference in what each person pays, is the number of people.",cta:"See why",where:"The Counting Court · Level 7",level:7,route:"#/stop/excess-deficit|learn"},"moral-excess-deficit-beat5":{id:"moral-excess-deficit-beat5",kind:"moral",src:"story:excess-deficit#beat5",badge:{id:"story",label:"A story"},title:"Vesper, in “Clubbing together”",body:"Seven friends pay 8 each, less the 3 too many: that is the price.",more:"The trick in the story: The gap between the two ways of paying, divided by the difference in what each person pays, is the number of people.",cta:"Read the story",where:"The Counting Court · Level 7",level:7,route:"#/stop/excess-deficit|story|5"},"algebra-excess-deficit-alg":{id:"algebra-excess-deficit-alg",kind:"algebra",src:"stop:excess-deficit#alg",title:"The algebra behind “Too many, too few”",body:"people = (excess + deficit) ÷ (x − y)  ·  price = x × people − excess",more:"In words: The gap between the two ways of paying, divided by the difference in what each person pays, is the number of people.",cta:"See why",where:"The Counting Court · Level 7",level:7,route:"#/stop/excess-deficit|learn"},"try-excess-deficit-L7":{id:"try-excess-deficit-L7",kind:"try",level:7,src:"try:excess-deficit@7/2#0",title:"Too many, too few — your turn",where:"The Counting Court · Level 7",route:"#/stop/excess-deficit|drill",cta:"Practise this stop",play:{q:"Some friends club together to buy a plant. If each pays 8 coins, there are 3 coins too many; if each pays 5 coins, they are 6 coins short. What does the plant cost, in coins?",opts:["21","3","31"],after:"The gap between the two ways of paying, divided by the difference in what each person pays, is the number of people.",show:[2,0,1]}},"trick-fangcheng-idea":{id:"trick-fangcheng-idea",kind:"trick",src:"stop:fangcheng#idea",title:"Fangcheng: clearing the columns",body:"Write each fact as a column; multiply one column and take another away from it again and again until a place is empty — then one unknown is left alone. The eighth chapter of the Nine Chapters, Fangcheng, sets out each fact as a column of rods on the board — the first fact on the right — and solves for several unknowns at once by working on whole columns.",more:"In algebra: a₁x + b₁y = c₁, a₂x + b₂y = c₂  ⇒  (a₁b₂ − a₂b₁)·y = a₁c₂ − a₂c₁",cta:"Learn the trick",where:"The Counting Court · Level 7",level:7,route:"#/stop/fangcheng|learn"},"story-fangcheng-open":{id:"story-fangcheng-open",kind:"story",src:"story:fangcheng#open",badge:{id:"story",label:"A story"},title:"Two heavy bags",body:"In the kitchen, 3 bags of rice and 2 of lentils weigh 29 kg. Another shelf has 2 of rice and 3 of lentils, 26 kg. — with Kwame and Nova.",more:"The trick inside: Write each fact as a column; multiply one column and take another away from it again and again until a place is empty — then one unknown is left alone.",art:"art/s-kitchen.webp",cta:"Read the story",where:"The Counting Court · Level 7",level:7,route:"#/stop/fangcheng|story|0"},"worked-fangcheng-worked0":{id:"worked-fangcheng-worked0",kind:"worked",src:"stop:fangcheng#worked0",title:"Worked out — Fangcheng: clearing the columns: Two columns: the low row",body:"On the counting board, the right column says 3 bags of rice and 2 bags of lentils weigh 29 kg. The left column says 2 bags of rice and 3 bags of lentils weigh 26 kg. How many kg is one bag of lentils?: Multiply the whole left column by 3, the right column's top number. Its kg become → 78 · Take the right column away twice: the top place empties. How many bags of lentils are left? → 5 · …and how many kg? → 20 · Divide: one bag of lentils → 4",more:"What is special here: Clear the top place of the left column; lentils are left alone.",cta:"Watch it step by step",where:"The Counting Court · Level 7",level:7,route:"#/stop/fangcheng|learn|0"},"idea-fangcheng-case2":{id:"idea-fangcheng-case2",kind:"idea",src:"stop:fangcheng#case2",title:"Fangcheng: clearing the columns: Three columns",body:"Clear the top places with the right column, then the middle place with the middle column.",more:"The method: Write each fact as a column; multiply one column and take another away from it again and again until a place is empty — then one unknown is left alone.",cta:"See it worked",where:"The Counting Court · Level 7",level:7,route:"#/stop/fangcheng|learn|2"},"why-fangcheng-why2":{id:"why-fangcheng-why2",kind:"why",src:"stop:fangcheng#why2",title:"Why “Fangcheng: clearing the columns” works",body:"With three unknowns you do it twice: clear the top place of the middle and left columns using the right column, then clear the middle place of the left column using the middle column. What is left is one kind of bag and a number of kilograms — divide. The same column moves, done with letters, are how equations are solved today.",more:"The trick: Write each fact as a column; multiply one column and take another away from it again and again until a place is empty — then one unknown is left alone.",cta:"See why",where:"The Counting Court · Level 7",level:7,route:"#/stop/fangcheng|learn"},"try-fangcheng-L7":{id:"try-fangcheng-L7",kind:"try",level:7,src:"try:fangcheng@7/1#0",title:"Fangcheng: clearing the columns — your turn",where:"The Counting Court · Level 7",route:"#/stop/fangcheng|drill",cta:"Practise this stop",play:{q:"On the counting board, the right column says 1 bag of rice and 2 bags of lentils weigh 21 kg. The left column says 1 bag of rice and 1 bag of lentils weigh 13 kg. How many kg is one bag of rice?",opts:["5","26","7"],after:"Write each fact as a column; multiply one column and take another away from it again and again until a place is empty — then one unknown is left alone.",show:[0,1,2]}},"trick-sunzi-multipliers-idea":{id:"trick-sunzi-multipliers-idea",kind:"trick",src:"stop:sunzi-multipliers#idea",title:"Remainders by multipliers",body:"Build one multiplier for each divisor — a number that leaves 1 by that divisor and nothing by the other — then take each remainder lots of its multiplier, add, and take away the product as often as you can. The Sunzi suanjing asks for a number that leaves 2 by threes, 3 by fives and 2 by sevens, and its rule uses 70 for threes, 21 for fives and 15 for sevens. Look at 70: it is a multiple of 5 and of 7, and it leaves exactly 1 when divided by 3. That is the whole secret, and it works for any divisors that share no factor.",more:"In algebra: x ≡ a (mod m), x ≡ b (mod n): x = a·M₁ + b·M₂ − k·mn, where M₁ ≡ 1 (mod m), n | M₁ and M₂ ≡ 1 (mod n), m | M₂",cta:"Learn the trick",where:"The Counting Court · Level 7",level:7,route:"#/stop/sunzi-multipliers|learn"},"story-sunzi-multipliers-open":{id:"story-sunzi-multipliers-open",kind:"story",src:"story:sunzi-multipliers#open",badge:{id:"story",label:"A story"},title:"The cupcake boxes",body:"At a bake sale, cupcakes packed in threes leave 2 over, and packed in sevens leave 4 over. Rafi wants the smallest number there could be. — with Rafi and Mira.",more:"The trick inside: Build one multiplier for each divisor — a number that leaves 1 by that divisor and nothing by the other — then take each remainder lots of its multiplier, add, and take away the product as often as you can.",art:"art/s-bakery.webp",cta:"Read the story",where:"The Counting Court · Level 7",level:7,route:"#/stop/sunzi-multipliers|story|0"},"why-sunzi-multipliers-why1":{id:"why-sunzi-multipliers-why1",kind:"why",src:"stop:sunzi-multipliers#why1",title:"Why “Remainders by multipliers” works",body:"Take divisors 3 and 7. Find a multiple of 7 that leaves 1 by 3: 7 leaves 1, so the first multiplier is 7. Find a multiple of 3 that leaves 1 by 7: 3, 6, 9, 12, 15 — 15 leaves 1, so the second is 15. Now 2 × 7 leaves 2 by threes and nothing by sevens; 4 × 15 leaves 4 by sevens and nothing by threes. Their sum, 14 + 60 = 74, leaves both remainders at once.",more:"The trick: Build one multiplier for each divisor — a number that leaves 1 by that divisor and nothing by the other — then take each remainder lots of its multiplier, add, and take away the product as often as you can.",cta:"See why",where:"The Counting Court · Level 7",level:7,route:"#/stop/sunzi-multipliers|learn"},"moral-sunzi-multipliers-beat5":{id:"moral-sunzi-multipliers-beat5",kind:"moral",src:"story:sunzi-multipliers#beat5",badge:{id:"story",label:"A story"},title:"Rafi, in “The cupcake boxes”",body:"Eleven cupcakes: 3 threes and 2 over, 1 seven and 4 over.",more:"The trick in the story: Build one multiplier for each divisor — a number that leaves 1 by that divisor and nothing by the other — then take each remainder lots of its multiplier, add, and take away the product as often as you can.",cta:"Read the story",where:"The Counting Court · Level 7",level:7,route:"#/stop/sunzi-multipliers|story|5"},"try-sunzi-multipliers-L7":{id:"try-sunzi-multipliers-L7",kind:"try",level:7,src:"try:sunzi-multipliers@7/1#0",title:"Remainders by multipliers — your turn",where:"The Counting Court · Level 7",route:"#/stop/sunzi-multipliers|drill",cta:"Practise this stop",play:{q:"A number leaves 1 when divided by 3, and 2 when divided by 5. What is the smallest such number?",opts:["7","6","22"],after:"Build one multiplier for each divisor — a number that leaves 1 by that divisor and nothing by the other — then take each remainder lots of its multiplier, add, and take away the product as often as you can.",show:[0,1,2]}},"trick-sea-island-idea":{id:"trick-sea-island-idea",kind:"trick",src:"stop:sea-island#idea",title:"The sea island survey",body:"Set up two equal poles in line with the peak; the difference between how far back you must lie to sight the peak over each pole gives the height and the distance by similar triangles. The Sea Island Mathematical Manual, which the sources attribute to Liu Hui, is named after its first problem: measuring an island peak from the shore with two poles. Here is the idea in plain numbers.",more:"In algebra: H = h·d ÷ (s₂ − s₁) + h  ·  D = s₁·d ÷ (s₂ − s₁)",cta:"Learn the trick",where:"The Counting Court · Level 7",level:7,route:"#/stop/sea-island|learn"},"story-sea-island-open":{id:"story-sea-island-open",kind:"story",src:"story:sea-island#open",badge:{id:"story",label:"A story"},title:"The rock in the lake",body:"There is a tall rock on an island in the park lake. Theo and Mira set up two 5 m poles 60 m apart, in line with the rock. — with Theo and Mira.",more:"The trick inside: Set up two equal poles in line with the peak; the difference between how far back you must lie to sight the peak over each pole gives the height and the distance by similar triangles.",art:"art/s-pond.webp",cta:"Read the story",where:"The Counting Court · Level 7",level:7,route:"#/stop/sea-island|story|0"},"worked-sea-island-worked0":{id:"worked-sea-island-worked0",kind:"worked",src:"stop:sea-island#worked0",title:"Worked out — The sea island survey: How tall is the peak?",body:"Two poles, each 5 m tall, stand 60 m apart in a straight line with an island peak. Lying 6 m behind the nearer pole, you see the peak just over its top; behind the further pole you must lie 9 m back. How tall is the peak, in m?: How much further back did you lie the second time? → 3 · How many times does that fit into the 60 m between the poles? → 20 · Times the pole height: the peak above the pole tops → 100 · Add the pole itself → 105",more:"What is special here: The gap fits into the pole distance some number of times: that many poles, plus one.",cta:"Watch it step by step",where:"The Counting Court · Level 7",level:7,route:"#/stop/sea-island|learn|0"},"why-sea-island-why1":{id:"why-sea-island-why1",kind:"why",src:"stop:sea-island#why1",title:"Why “The sea island survey” works",body:"Lie on the ground behind a pole so the pole's top just lines up with the peak. The little triangle — pole height up, your distance back along the ground — has the same shape as the big triangle from your eye to the peak. So the peak is as many times taller than the pole as its distance from your eye is longer than your distance from the pole.",more:"The trick: Set up two equal poles in line with the peak; the difference between how far back you must lie to sight the peak over each pole gives the height and the distance by similar triangles.",cta:"See why",where:"The Counting Court · Level 7",level:7,route:"#/stop/sea-island|learn"},"moral-sea-island-beat5":{id:"moral-sea-island-beat5",kind:"moral",src:"story:sea-island#beat5",badge:{id:"story",label:"A story"},title:"Mira, in “The rock in the lake”",body:"Add the pole itself. Similar triangles, and nobody got wet.",more:"The trick in the story: Set up two equal poles in line with the peak; the difference between how far back you must lie to sight the peak over each pole gives the height and the distance by similar triangles.",cta:"Read the story",where:"The Counting Court · Level 7",level:7,route:"#/stop/sea-island|story|5"},"try-sea-island-L7":{id:"try-sea-island-L7",kind:"try",level:7,src:"try:sea-island@7/1#0",title:"The sea island survey — your turn",where:"The Counting Court · Level 7",route:"#/stop/sea-island|drill",cta:"Practise this stop",play:{q:"Two poles, each 5 m tall, stand 12 m apart in a straight line with an island peak. Lying 9 m behind the nearer pole, you see the peak just over its top; behind the further pole you must lie 10 m back. How tall is the peak, in m?",opts:["65","75","650"],after:"Set up two equal poles in line with the peak; the difference between how far back you must lie to sight the peak over each pole gives the height and the distance by similar triangles.",show:[0,1,2]}},"trick-chance-fraction-idea":{id:"trick-chance-fraction-idea",kind:"trick",src:"stop:chance-fraction#idea",title:"Chance as a fraction",body:"Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction. If every part of the spinner is the same size, every part is equally likely to be where the arrow stops. So each of the 8 parts gets exactly one eighth of the chance.",more:"In algebra: P(event) = ways it can happen ÷ all equally likely ways",cta:"Learn the trick",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|learn"},"story-chance-fraction-open":{id:"story-chance-fraction-open",kind:"story",src:"story:chance-fraction#open",badge:{id:"story",label:"A story"},title:"The spinner stall",body:"The spinner has 8 equal parts. 3 are blue, and blue wins a goldfish balloon. — with Ines and Dax.",more:"The trick inside: Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",art:"art/s-carnival.webp",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|story|0"},"hook-chance-fraction-hook":{id:"hook-chance-fraction-hook",kind:"hook",src:"stop:chance-fraction#hook",title:"Can you? — Chance as a fraction",body:"A spinner with 8 equal parts, 3 of them blue. What is the chance of blue — as a number?",more:"The way in: Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",cta:"Find out how",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|learn"},"idea-chance-fraction-case0":{id:"idea-chance-fraction-case0",kind:"idea",src:"stop:chance-fraction#case0",title:"Chance as a fraction: The chance of it",body:"The bottom of the fraction counts every equal part; the top counts the parts you want.",more:"The method: Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|learn|0"},"worked-chance-fraction-worked0":{id:"worked-chance-fraction-worked0",kind:"worked",src:"stop:chance-fraction#worked0",title:"Worked out — Chance as a fraction: The chance of it",body:"A spinner has 8 equal parts: 3 blue and 5 yellow. What is the chance of blue?: How many are blue? → 3 · How many equal parts altogether? → 8 · The chance, as a fraction → 3/8",more:"What is special here: The bottom of the fraction counts every equal part; the top counts the parts you want.",cta:"Watch it step by step",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|learn|0"},"idea-chance-fraction-case1":{id:"idea-chance-fraction-case1",kind:"idea",src:"stop:chance-fraction#case1",title:"Chance as a fraction: The chance of NOT",body:"Count the parts that are anything else. The two chances always add up to a whole: 3/8 blue leaves 5/8 not blue.",more:"The method: Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|learn|1"},"why-chance-fraction-why1":{id:"why-chance-fraction-why1",kind:"why",src:"stop:chance-fraction#why1",title:"Why “Chance as a fraction” works",body:"Three of those eighths are blue, so the chance of blue is 3/8. The bottom of the fraction counts everything that could happen; the top counts the ones you want.",more:"The trick: Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|learn"},"why-chance-fraction-why2":{id:"why-chance-fraction-why2",kind:"why",src:"stop:chance-fraction#why2",title:"Why “Chance as a fraction” works",body:"That is why chance is always between 0 and 1: 0/8 is impossible, 8/8 is certain, and 4/8 — a half — is the even chance in the middle. The chance of NOT blue is whatever is left: 5/8.",more:"The trick: Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|learn"},"moment-chance-fraction-beat3":{id:"moment-chance-fraction-beat3",kind:"moment",src:"story:chance-fraction#beat3",badge:{id:"story",label:"A story"},title:"The spinner stall — on the notepad",body:"Ines: Three of the parts are blue — three eighths. 3 × 0.125 = 0.375",more:"The trick in the story: Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|story|3"},"moral-chance-fraction-beat5":{id:"moral-chance-fraction-beat5",kind:"moral",src:"story:chance-fraction#beat5",badge:{id:"story",label:"A story"},title:"Ines, in “The spinner stall”",body:"Five eighths. Your chance of blue is 3 out of 8.",more:"The trick in the story: Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|story|5"},"algebra-chance-fraction-alg":{id:"algebra-chance-fraction-alg",kind:"algebra",src:"stop:chance-fraction#alg",title:"The algebra behind “Chance as a fraction”",body:"P(event) = ways it can happen ÷ all equally likely ways",more:"In words: Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/chance-fraction|learn"},"try-chance-fraction-L7":{id:"try-chance-fraction-L7",kind:"try",level:7,src:"try:chance-fraction@7/1#0",title:"Chance as a fraction — your turn",where:"The Data Carnival · Level 7",route:"#/stop/chance-fraction|drill",cta:"Practise this stop",play:{q:"A spinner has 3 equal parts: 1 blue and 2 yellow. What is the chance of yellow?",opts:["2/3","3","2"],after:"Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction.",show:[1,0,2]}},"trick-list-outcomes-idea":{id:"trick-list-outcomes-idea",kind:"trick",src:"stop:list-outcomes#idea",title:"Counting all the ways",body:"For every choice of the first thing, there are all the choices of the second: multiply. List them in a system so none is missed: take the first top and try it with every skirt — that is 4 outfits. The second top makes 4 more, the third another 4. Three rows of 4 is 3 × 4.",more:"In algebra: a choices then b choices: a × b · handshakes among n people: n(n − 1) ÷ 2",cta:"Learn the trick",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn"},"story-list-outcomes-open":{id:"story-list-outcomes-open",kind:"story",src:"story:list-outcomes#open",badge:{id:"story",label:"A story"},title:"Parade costumes",body:"Before the parade, the costume box holds 3 tops and 4 skirts. Nova wants a different outfit every day. — with Mira and Nova.",more:"The trick inside: For every choice of the first thing, there are all the choices of the second: multiply.",art:"art/s-hall.webp",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|story|0"},"hook-list-outcomes-hook":{id:"hook-list-outcomes-hook",kind:"hook",src:"stop:list-outcomes#hook",title:"Can you? — Counting all the ways",body:"3 tops and 4 skirts for the parade. How many different outfits — without drawing them all?",more:"The way in: For every choice of the first thing, there are all the choices of the second: multiply.",cta:"Find out how",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn"},"idea-list-outcomes-case0":{id:"idea-list-outcomes-case0",kind:"idea",src:"stop:list-outcomes#case0",title:"Counting all the ways: Two choices: multiply",body:"Every top goes with every skirt, so it is rows of the same size: 3 rows of 4.",more:"The method: For every choice of the first thing, there are all the choices of the second: multiply.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn|0"},"worked-list-outcomes-worked0":{id:"worked-list-outcomes-worked0",kind:"worked",src:"stop:list-outcomes#worked0",title:"Worked out — Counting all the ways: Two choices: multiply",body:"3 tops and 4 skirts for the parade. How many different outfits?: How many tops? → 3 · How many skirts go with each? → 4 · 3 × 4 → 12",more:"What is special here: Every top goes with every skirt, so it is rows of the same size: 3 rows of 4.",cta:"Watch it step by step",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn|0"},"idea-list-outcomes-case1":{id:"idea-list-outcomes-case1",kind:"idea",src:"stop:list-outcomes#case1",title:"Counting all the ways: Three choices",body:"Every hat-and-mask pair goes with every cape, so multiply again for the third choice.",more:"The method: For every choice of the first thing, there are all the choices of the second: multiply.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn|1"},"worked-list-outcomes-worked1":{id:"worked-list-outcomes-worked1",kind:"worked",src:"stop:list-outcomes#worked1",title:"Worked out — Counting all the ways: Three choices",body:"2 hats, 3 masks and 4 capes. One of each — how many different costumes?: Hats and masks: 2 × 3 → 6 · With every one of those, 4 capes: 6 × 4 → 24",more:"What is special here: Every hat-and-mask pair goes with every cape, so multiply again for the third choice.",cta:"Watch it step by step",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn|1"},"idea-list-outcomes-case2":{id:"idea-list-outcomes-case2",kind:"idea",src:"stop:list-outcomes#case2",title:"Counting all the ways: Handshakes",body:"A handshake between two people is ONE handshake, but counting from both ends counts it twice — so halve it.",more:"The method: For every choice of the first thing, there are all the choices of the second: multiply.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn|2"},"worked-list-outcomes-worked2":{id:"worked-list-outcomes-worked2",kind:"worked",src:"stop:list-outcomes#worked2",title:"Worked out — Counting all the ways: Handshakes",body:"5 friends meet at the carnival. Everyone shakes hands once with everyone else. How many handshakes?: How many hands does each person shake? → 4 · 5 × 4 → 20 · Each handshake was counted twice — halve it → 10",more:"What is special here: A handshake between two people is ONE handshake, but counting from both ends counts it twice — so halve it.",cta:"Watch it step by step",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn|2"},"why-list-outcomes-why1":{id:"why-list-outcomes-why1",kind:"why",src:"stop:list-outcomes#why1",title:"Why “Counting all the ways” works",body:"The same works for chance. A coin can land 2 ways and a dice 6 ways, and every coin result goes with every dice result: 2 × 6 = 12 outcomes, like a table with 2 rows and 6 columns.",more:"The trick: For every choice of the first thing, there are all the choices of the second: multiply.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn"},"why-list-outcomes-why2":{id:"why-list-outcomes-why2",kind:"why",src:"stop:list-outcomes#why2",title:"Why “Counting all the ways” works",body:"Handshakes are different, because two people shaking hands is ONE handshake, not two. Each of 6 people shakes 5 hands, which counts 6 × 5 = 30 — but every handshake was counted from both ends, so there are only 15.",more:"The trick: For every choice of the first thing, there are all the choices of the second: multiply.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn"},"moment-list-outcomes-beat3":{id:"moment-list-outcomes-beat3",kind:"moment",src:"story:list-outcomes#beat3",badge:{id:"story",label:"A story"},title:"Parade costumes — on the notepad",body:"Nova: Then the second top with all 4, and the third with all 4. 4 + 4 + 4 = 12",more:"The trick in the story: For every choice of the first thing, there are all the choices of the second: multiply.",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|story|3"},"moral-list-outcomes-beat5":{id:"moral-list-outcomes-beat5",kind:"moral",src:"story:list-outcomes#beat5",badge:{id:"story",label:"A story"},title:"Nova, in “Parade costumes”",body:"Twelve outfits — twelve days of parades!",more:"The trick in the story: For every choice of the first thing, there are all the choices of the second: multiply.",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|story|5"},"algebra-list-outcomes-alg":{id:"algebra-list-outcomes-alg",kind:"algebra",src:"stop:list-outcomes#alg",title:"The algebra behind “Counting all the ways”",body:"a choices then b choices: a × b · handshakes among n people: n(n − 1) ÷ 2",more:"In words: For every choice of the first thing, there are all the choices of the second: multiply.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/list-outcomes|learn"},"try-list-outcomes-L7":{id:"try-list-outcomes-L7",kind:"try",level:7,src:"try:list-outcomes@7/1#0",title:"Counting all the ways — your turn",where:"The Data Carnival · Level 7",route:"#/stop/list-outcomes|drill",cta:"Practise this stop",play:{q:"Toss two coins. How many different outcomes are there?",opts:["4","2","7"],after:"For every choice of the first thing, there are all the choices of the second: multiply.",show:[2,0,1]}},"hook-think-of-a-number-hook":{id:"hook-think-of-a-number-hook",kind:"hook",src:"stop:think-of-a-number#hook",title:"Can you? — Working backwards",body:"I think of a number, times it by 3, add 4, and get 19. What was my number?",more:"The way in: Start at the end and undo each step, last one first: undo + with −, and × with ÷.",cta:"Find out how",where:"The Data Carnival · Level 7",level:7,route:"#/stop/think-of-a-number|learn"},"why-think-of-a-number-why1":{id:"why-think-of-a-number-why1",kind:"why",src:"stop:think-of-a-number#why1",title:"Why “Working backwards” works",body:"Every step has an opposite that cancels it. Adding 4 then taking 4 away leaves you where you were; times 3 then divide by 3 does too. So 19 − 4 = 15 undoes the adding, and 15 ÷ 3 = 5 undoes the multiplying.",more:"The trick: Start at the end and undo each step, last one first: undo + with −, and × with ÷.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/think-of-a-number|learn"},"moment-think-of-a-number-beat3":{id:"moment-think-of-a-number-beat3",kind:"moment",src:"story:think-of-a-number#beat3",badge:{id:"story",label:"A story"},title:"The mind-reader — on the notepad",body:"Vesper: Before that you timesed by 3. Undo that too. 15 ÷ 3 = 5",more:"The trick in the story: Start at the end and undo each step, last one first: undo + with −, and × with ÷.",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/think-of-a-number|story|3"},"algebra-think-of-a-number-alg":{id:"algebra-think-of-a-number-alg",kind:"algebra",src:"stop:think-of-a-number#alg",title:"The algebra behind “Working backwards”",body:"((x × a) + b = c) ⇒ x = (c − b) ÷ a",more:"In words: Start at the end and undo each step, last one first: undo + with −, and × with ÷.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/think-of-a-number|learn"},"try-think-of-a-number-L7":{id:"try-think-of-a-number-L7",kind:"try",level:7,src:"try:think-of-a-number@7/2#0",title:"Working backwards — your turn",where:"The Data Carnival · Level 7",route:"#/stop/think-of-a-number|drill",cta:"Practise this stop",play:{q:"? → × 7 → − 9 → 5. What number went in?",opts:["2","1","14"],after:"Start at the end and undo each step, last one first: undo + with −, and × with ÷.",show:[0,1,2]}},"trick-factorials-idea":{id:"trick-factorials-idea",kind:"trick",src:"stop:factorials#idea",title:"Factorials",body:"n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1. Line up 4 friends. Any of the 4 can stand first. Whoever is first, any of the 3 left can stand second, then either of the last 2, and the last friend has no choice at all. So there are 4 × 3 × 2 × 1 = 24 line-ups. That product turns up so often it has a short name: 4 factorial, written 4!.",more:"In algebra: n! = n × (n − 1) × … × 2 × 1 = n × (n − 1)! · 0! = 1",cta:"Learn the trick",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn"},"story-factorials-open":{id:"story-factorials-open",kind:"story",src:"story:factorials#open",badge:{id:"story",label:"A story"},title:"The photo booth",body:"At the fair photo booth, 5 friends want a picture in a row. Dax wants one photo for every different order. — with Rafi and Dax.",more:"The trick inside: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",art:"art/s-fair.webp",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|story|0"},"hook-factorials-hook":{id:"hook-factorials-hook",kind:"hook",src:"stop:factorials#hook",title:"Can you? — Factorials",body:"How many ways can 5 friends line up for a photo? Now try 10 friends — without listing them.",more:"The way in: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",cta:"Find out how",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn"},"idea-factorials-case0":{id:"idea-factorials-case0",kind:"idea",src:"stop:factorials#case0",title:"Factorials: Work out n!",body:"Build it upwards: each factorial is the one before, times the next number. 2! = 2, 3! = 3 × 2!, 4! = 4 × 3!…",more:"The method: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn|0"},"worked-factorials-worked0":{id:"worked-factorials-worked0",kind:"worked",src:"stop:factorials#worked0",title:"Worked out — Factorials: Work out n!",body:"Work out 5!: 2! = 2 × 1 → 2 · 3! = 3 × 2! → 6 · 4! = 4 × 3! → 24 · 5! = 5 × 4! → 120",more:"What is special here: Build it upwards: each factorial is the one before, times the next number. 2! = 2, 3! = 3 × 2!, 4! = 4 × 3!…",cta:"Watch it step by step",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn|0"},"idea-factorials-case1":{id:"idea-factorials-case1",kind:"idea",src:"stop:factorials#case1",title:"Factorials: Divide: cancel first",body:"6! is hiding inside 8!, so it cancels. Only the numbers from 8 down to 7 are left to multiply.",more:"The method: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn|1"},"worked-factorials-worked1":{id:"worked-factorials-worked1",kind:"worked",src:"stop:factorials#worked1",title:"Worked out — Factorials: Divide: cancel first",body:"Work out 8! ÷ 6!: 6! cancels. How many numbers are left, counting down from 8? → 2 · 8 × 7 → 56",more:"What is special here: 6! is hiding inside 8!, so it cancels. Only the numbers from 8 down to 7 are left to multiply.",cta:"Watch it step by step",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn|1"},"idea-factorials-case2":{id:"idea-factorials-case2",kind:"idea",src:"stop:factorials#case2",title:"Factorials: Zero factorial",body:"Walk the pattern down, dividing as you go: 1! ÷ 1 = 0!. So 0! is 1 — one way to line up nobody.",more:"The method: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn|2"},"worked-factorials-worked2":{id:"worked-factorials-worked2",kind:"worked",src:"stop:factorials#worked2",title:"Worked out — Factorials: Zero factorial",body:"Work out 3! + 0!: 2! = 2 × 1 → 2 · 3! = 3 × 2! → 6 · 0! — walk the pattern down to it → 1 · 6 + 1 → 7",more:"What is special here: Walk the pattern down, dividing as you go: 1! ÷ 1 = 0!. So 0! is 1 — one way to line up nobody.",cta:"Watch it step by step",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn|2"},"why-factorials-why1":{id:"why-factorials-why1",kind:"why",src:"stop:factorials#why1",title:"Why “Factorials” works",body:"Every factorial holds the one below it: 5! = 5 × 4 × 3 × 2 × 1 = 5 × 4!. That is why 8! ÷ 6! is easy. 6! sits inside 8!, so it cancels, and only 8 × 7 = 56 is left. Never work out two huge numbers just to divide one by the other.",more:"The trick: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn"},"why-factorials-why2":{id:"why-factorials-why2",kind:"why",src:"stop:factorials#why2",title:"Why “Factorials” works",body:"Walk the pattern down: 4! = 24, and dividing by 4 gives 3! = 6; divide by 3 and 2! = 2; divide by 2 and 1! = 1. One more step, divide by 1, gives 0! = 1. It is not a rule someone made up — it is the only value that keeps the pattern going, and there really is exactly one way to line up nobody.",more:"The trick: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn"},"moment-factorials-beat3":{id:"moment-factorials-beat3",kind:"moment",src:"story:factorials#beat3",badge:{id:"story",label:"A story"},title:"The photo booth — on the notepad",body:"Dax: Twenty already, and that is only two places. Then 3 for the middle, 2, and the last one has no choice. 20 × 3 × 2 × 1 = 120",more:"The trick in the story: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|story|3"},"moral-factorials-beat6":{id:"moral-factorials-beat6",kind:"moral",src:"story:factorials#beat6",badge:{id:"story",label:"A story"},title:"Rafi, in “The photo booth”",body:"Five factorial, written 5 with an exclamation mark. 120 orders.",more:"The trick in the story: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|story|6"},"algebra-factorials-alg":{id:"algebra-factorials-alg",kind:"algebra",src:"stop:factorials#alg",title:"The algebra behind “Factorials”",body:"n! = n × (n − 1) × … × 2 × 1 = n × (n − 1)! · 0! = 1",more:"In words: n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/factorials|learn"},"try-factorials-L7":{id:"try-factorials-L7",kind:"try",level:7,src:"try:factorials@7/1#0",title:"Factorials — your turn",where:"The Data Carnival · Level 7",route:"#/stop/factorials|drill",cta:"Practise this stop",play:{q:"Work out 6! = ?",opts:["720","730","820"],after:"n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1.",show:[2,0,1]}},"trick-arrange-all-idea":{id:"trick-arrange-all-idea",kind:"trick",src:"stop:arrange-all#idea",title:"Putting things in order",body:"Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice. Think of a row of empty places. The first place can take any of the n things. Once it is filled, the second place has n − 1 left — and that is true whichever thing went first, so every first choice brings the same number of second choices. Multiply all the way down: n × (n − 1) × … × 1 = n!.",more:"In algebra: n things in a row: n! · one place fixed: (n − 1)! · first place from k of them: k × (n − 1)!",cta:"Learn the trick",where:"The Data Carnival · Level 7",level:7,route:"#/stop/arrange-all|learn"},"story-arrange-all-open":{id:"story-arrange-all-open",kind:"story",src:"story:arrange-all#open",badge:{id:"story",label:"A story"},title:"The dodgem queue",body:"Pip, Suki, Nova and Rafi queue for the dodgems. Pip says he must be at the front. — with Pip and Suki.",more:"The trick inside: Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice.",art:"art/s-carnival.webp",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/arrange-all|story|0"},"idea-arrange-all-case0":{id:"idea-arrange-all-case0",kind:"idea",src:"stop:arrange-all#case0",title:"Putting things in order: Everyone in a row",body:"n choices for the first place, one fewer for each place after it, down to 1: that is n!.",more:"The method: Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/arrange-all|learn|0"},"idea-arrange-all-case1":{id:"idea-arrange-all-case1",kind:"idea",src:"stop:arrange-all#case1",title:"Putting things in order: One place fixed",body:"Pip is at the front already, so that place has 1 choice. Only the others move: (n − 1)!.",more:"The method: Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/arrange-all|learn|1"},"idea-arrange-all-case2":{id:"idea-arrange-all-case2",kind:"idea",src:"stop:arrange-all#case2",title:"Putting things in order: First from a few",body:"Fill the fussy place first: 2 sprinters could run first. Then the rest go in any order.",more:"The method: Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice.",cta:"See it worked",where:"The Data Carnival · Level 7",level:7,route:"#/stop/arrange-all|learn|2"},"why-arrange-all-why1":{id:"why-arrange-all-why1",kind:"why",src:"stop:arrange-all#why1",title:"Why “Putting things in order” works",body:"If Pip must be at the front, the first place has only 1 choice. Just the other n − 1 are free to move, so there are (n − 1)! orders. Check it with 3 friends: with Pip in front, only the other two can swap — 2 orders, and 2! = 2.",more:"The trick: Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice.",cta:"See why",where:"The Data Carnival · Level 7",level:7,route:"#/stop/arrange-all|learn"},"moment-arrange-all-beat3":{id:"moment-arrange-all-beat3",kind:"moment",src:"story:arrange-all#beat3",badge:{id:"story",label:"A story"},title:"The dodgem queue — on the notepad",body:"Pip: Three for the second place, two for the third, one for the last. 3 × 2 × 1 = 6",more:"The trick in the story: Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice.",cta:"Read the story",where:"The Data Carnival · Level 7",level:7,route:"#/stop/arrange-all|story|3"},"try-arrange-all-L7":{id:"try-arrange-all-L7",kind:"try",level:7,src:"try:arrange-all@7/1#0",title:"Putting things in order — your turn",where:"The Data Carnival · Level 7",route:"#/stop/arrange-all|drill",cta:"Practise this stop",play:{q:"5 different prizes go in a row on the hoopla shelf. In how many different orders can they go?",opts:["120","24","220"],after:"Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice.",show:[2,1,0]}},"hook-work-backwards-hook":{id:"hook-work-backwards-hook",kind:"hook",src:"stop:work-backwards#hook",title:"Can you? — Work backwards",body:"Tara gave away half her stickers and then 3 more, and has 9 left. How many did she start with?",more:"The way in: When you know how a story ENDS, start there and undo each thing that happened, last one first.",cta:"Find out how",where:"The Strategy School · Level 7",level:7,route:"#/stop/work-backwards|learn"},"worked-work-backwards-worked0":{id:"worked-work-backwards-worked0",kind:"worked",src:"stop:work-backwards#worked0",title:"Worked out — Work backwards: Gave some, got some",body:"Kofi had some marbles. Then Kofi gave 7 away and then got 12 more. That left 20. How many marbles did Kofi have at the start?: Undo getting 12: take them off: from 20 → 8 · Undo giving 7 away: add them back: from 8 → 15",more:"What is special here: Only adding and taking away: undo each one with its opposite, from the end.",cta:"Watch it step by step",where:"The Strategy School · Level 7",level:7,route:"#/stop/work-backwards|learn|0"},"worked-work-backwards-worked1":{id:"worked-work-backwards-worked1",kind:"worked",src:"stop:work-backwards#worked1",title:"Worked out — Work backwards: Halves and doubles",body:"Lena had some cards. Then Lena gave 4 away, gave half of them to a friend and then got 5 more. That left 12. How many cards did Lena have at the start?: Undo getting 5: take them off: from 12 → 7 · Undo giving half away: double: from 7 → 14 · Undo giving 4 away: add them back: from 14 → 18",more:"What is special here: A half is undone by doubling, a double by halving — still last thing first.",cta:"Watch it step by step",where:"The Strategy School · Level 7",level:7,route:"#/stop/work-backwards|learn|1"},"worked-work-backwards-worked2":{id:"worked-work-backwards-worked2",kind:"worked",src:"stop:work-backwards#worked2",title:"Worked out — Work backwards: Half, and then some more",body:"Tara had some stickers. Then Tara gave half of them away and then 3 more. That left 9. How many stickers did Tara have at the start?: Undo “half, then 3 more”: add the 3 back, then double: from 9 → 24",more:'What is special here: Two things in one: undo the "more" first, because it happened last, then double.',cta:"Watch it step by step",where:"The Strategy School · Level 7",level:7,route:"#/stop/work-backwards|learn|2"},"why-work-backwards-why2":{id:"why-work-backwards-why2",kind:"why",src:"stop:work-backwards#why2",title:"Why “Work backwards” works",body:"It is like getting dressed: socks on before shoes, so shoes come off first. When you get to the start, check by running the story forwards — you should land exactly on the ending you were given.",more:"The trick: When you know how a story ENDS, start there and undo each thing that happened, last one first.",cta:"See why",where:"The Strategy School · Level 7",level:7,route:"#/stop/work-backwards|learn"},"moral-work-backwards-beat6":{id:"moral-work-backwards-beat6",kind:"moral",src:"story:work-backwards#beat6",badge:{id:"story",label:"A story"},title:"Pip, in “The sticker swap”",body:"We do! I started with 24 — I just undid it backwards, last thing first.",more:"The trick in the story: When you know how a story ENDS, start there and undo each thing that happened, last one first.",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/work-backwards|story|6"},"algebra-work-backwards-alg":{id:"algebra-work-backwards-alg",kind:"algebra",src:"stop:work-backwards#alg",title:"The algebra behind “Work backwards”",body:"if x → f → g → end, then x = f⁻¹(g⁻¹(end))",more:"In words: When you know how a story ENDS, start there and undo each thing that happened, last one first.",cta:"See why",where:"The Strategy School · Level 7",level:7,route:"#/stop/work-backwards|learn"},"try-work-backwards-L7":{id:"try-work-backwards-L7",kind:"try",level:7,src:"try:work-backwards@7/2#0",title:"Work backwards — your turn",where:"The Strategy School · Level 7",route:"#/stop/work-backwards|drill",cta:"Practise this stop",play:{q:"Sami had some shells. Then Sami won a game that doubled them, gave 9 away and then got 13 more. That left 52. How many shells did Sami have at the start?",opts:["24","48","39"],after:"When you know how a story ENDS, start there and undo each thing that happened, last one first.",show:[1,2,0]}},"trick-find-the-rule-idea":{id:"trick-find-the-rule-idea",kind:"trick",src:"stop:find-the-rule#idea",title:"Find the rule",body:'Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step. You could build all 25 shapes — but the pattern tells you a shortcut. Each new square in the row adds 3 more sticks, so the numbers go up by 3 every time: 4, 7, 10, 13…',more:"In algebra: shape n = (shape 1 − d) + n × d",cta:"Learn the trick",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|learn"},"story-find-the-rule-open":{id:"story-find-the-rule-open",kind:"story",src:"story:find-the-rule#open",badge:{id:"story",label:"A story"},title:"The matchstick fence",body:"Pip is building rows of squares from matchsticks: 4 sticks for one square, 7 for two, 10 for three. He wants to know how many for 25 squares. — with Mira and Pip.",more:'The trick inside: Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',art:"art/s-kitchen.webp",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|story|0"},"hook-find-the-rule-hook":{id:"hook-find-the-rule-hook",kind:"hook",src:"stop:find-the-rule#hook",title:"Can you? — Find the rule",body:"Shape 1 uses 4 matchsticks, shape 2 uses 7, shape 3 uses 10. How many does shape 25 use?",more:'The way in: Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',cta:"Find out how",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|learn"},"idea-find-the-rule-case0":{id:"idea-find-the-rule-case0",kind:"idea",src:"stop:find-the-rule#case0",title:"Find the rule: How many in shape n?",body:"Shape 0 plus n lots of the step — no need to build the ones in between.",more:'The method: Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|learn|0"},"worked-find-the-rule-worked0":{id:"worked-find-the-rule-worked0",kind:"worked",src:"stop:find-the-rule#worked0",title:"Worked out — Find the rule: How many in shape n?",body:'A pattern of matchsticks: shape 1 uses 4, shape 2 uses 7 and shape 3 uses 10. If the pattern carries on, how many matchsticks does shape 25 use?: How many more each time? → 3 · Step back one: how many in "shape 0"? → 1 · 25 lots of 3: 25 × 3 → 75 · Add shape 0: 75 + 1 → 76',more:"What is special here: Shape 0 plus n lots of the step — no need to build the ones in between.",cta:"Watch it step by step",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|learn|0"},"idea-find-the-rule-case1":{id:"idea-find-the-rule-case1",kind:"idea",src:"stop:find-the-rule#case1",title:"Find the rule: Which shape uses this many?",body:"Run the rule backwards: take off shape 0, then see how many steps are left.",more:'The method: Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|learn|1"},"worked-find-the-rule-worked1":{id:"worked-find-the-rule-worked1",kind:"worked",src:"stop:find-the-rule#worked1",title:"Worked out — Find the rule: Which shape uses this many?",body:'A pattern of matchsticks: shape 1 uses 4, shape 2 uses 7 and shape 3 uses 10. If the pattern carries on, which shape uses exactly 61?: How many more each time? → 3 · Step back one: how many in "shape 0"? → 1 · Take off shape 0: 61 − 1 → 60 · How many lots of 3? → 20',more:"What is special here: Run the rule backwards: take off shape 0, then see how many steps are left.",cta:"Watch it step by step",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|learn|1"},"why-find-the-rule-why1":{id:"why-find-the-rule-why1",kind:"why",src:"stop:find-the-rule#why1",title:"Why “Find the rule” works",body:'Now step backwards once, to an imaginary "shape 0": 4 − 3 = 1 stick. Every shape is that 1 stick plus some 3s — shape 1 has one 3, shape 2 has two, so shape 25 has twenty-five: 1 + 25 × 3 = 76.',more:'The trick: Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',cta:"See why",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|learn"},"why-find-the-rule-why2":{id:"why-find-the-rule-why2",kind:"why",src:"stop:find-the-rule#why2",title:"Why “Find the rule” works",body:"The same rule runs backwards. Which shape uses 61 sticks? Take off the shape-0 part: 61 − 1 = 60. That is 60 ÷ 3 = 20 lots of 3, so it is shape 20.",more:'The trick: Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',cta:"See why",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|learn"},"moment-find-the-rule-beat3":{id:"moment-find-the-rule-beat3",kind:"moment",src:"story:find-the-rule#beat3",badge:{id:"story",label:"A story"},title:"The matchstick fence — on the notepad",body:"Mira: Step back to shape 0 — no squares, just the first stick on the left. 4 − 3 = 1",more:'The trick in the story: Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|story|3"},"moral-find-the-rule-beat5":{id:"moral-find-the-rule-beat5",kind:"moral",src:"story:find-the-rule#beat5",badge:{id:"story",label:"A story"},title:"Mira, in “The matchstick fence”",body:"…plus that one stick at the start. Seventy-six.",more:'The trick in the story: Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|story|5"},"algebra-find-the-rule-alg":{id:"algebra-find-the-rule-alg",kind:"algebra",src:"stop:find-the-rule#alg",title:"The algebra behind “Find the rule”",body:"shape n = (shape 1 − d) + n × d",more:'In words: Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',cta:"See why",where:"The Strategy School · Level 7",level:7,route:"#/stop/find-the-rule|learn"},"try-find-the-rule-L7":{id:"try-find-the-rule-L7",kind:"try",level:7,src:"try:find-the-rule@7/1#0",title:"Find the rule — your turn",where:"The Strategy School · Level 7",route:"#/stop/find-the-rule|drill",cta:"Practise this stop",play:{q:"A pattern of matchsticks: shape 1 uses 5, shape 2 uses 8 and shape 3 uses 11. If the pattern carries on, how many matchsticks does shape 10 use?",opts:["32","42","320"],after:'Find what is added each time, step back to "shape 0", and then shape n is shape 0 plus n lots of the step.',show:[0,2,1]}},"trick-heads-and-legs-idea":{id:"trick-heads-and-legs-idea",kind:"trick",src:"stop:heads-and-legs#idea",title:"Pretend they are all the same",body:"Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference. Imagine all 12 animals were hens. That is 12 × 2 = 24 legs. But there are 34 — so 10 legs are not explained yet. Something must be a goat.",more:"In algebra: big kind = (total − count × small) ÷ (big − small)",cta:"Learn the trick",where:"The Strategy School · Level 7",level:7,route:"#/stop/heads-and-legs|learn"},"story-heads-and-legs-open":{id:"story-heads-and-legs-open",kind:"story",src:"story:heads-and-legs#open",badge:{id:"story",label:"A story"},title:"The farm count",body:"At a city farm, Rafi counts 12 heads and 34 legs in the hen-and-goat pen. — with Kwame and Rafi.",more:"The trick inside: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.",art:"art/s-garden.webp",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/heads-and-legs|story|0"},"idea-heads-and-legs-case0":{id:"idea-heads-and-legs-case0",kind:"idea",src:"stop:heads-and-legs#case0",title:"Pretend they are all the same: Heads and legs",body:"Pretend they are all the kind with fewer legs; each swap adds the difference in legs.",more:"The method: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/heads-and-legs|learn|0"},"idea-heads-and-legs-case1":{id:"idea-heads-and-legs-case1",kind:"idea",src:"stop:heads-and-legs#case1",title:"Pretend they are all the same: Two kinds of coin",body:"Pretend they are all the smaller coin; each swap adds the difference in value.",more:"The method: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/heads-and-legs|learn|1"},"idea-heads-and-legs-case2":{id:"idea-heads-and-legs-case2",kind:"idea",src:"stop:heads-and-legs#case2",title:"Pretend they are all the same: Points won and lost",body:"Pretend every answer was right; each wrong answer costs the points not won AND the points lost.",more:"The method: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/heads-and-legs|learn|2"},"why-heads-and-legs-why1":{id:"why-heads-and-legs-why1",kind:"why",src:"stop:heads-and-legs#why1",title:"Why “Pretend they are all the same” works",body:"Swapping one hen for a goat keeps the heads the same and adds 2 legs (a goat has 4, a hen 2). To find 10 more legs you need 10 ÷ 2 = 5 swaps. So there are 5 goats — and 7 hens. Check: 7 × 2 + 5 × 4 = 34.",more:"The trick: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.",cta:"See why",where:"The Strategy School · Level 7",level:7,route:"#/stop/heads-and-legs|learn"},"moment-heads-and-legs-beat3":{id:"moment-heads-and-legs-beat3",kind:"moment",src:"story:heads-and-legs#beat3",badge:{id:"story",label:"A story"},title:"The farm count — on the notepad",body:"Rafi: But there are 34, so some legs are not explained. 34 − 24 = 10",more:"The trick in the story: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/heads-and-legs|story|3"},"try-heads-and-legs-L7":{id:"try-heads-and-legs-L7",kind:"try",level:7,src:"try:heads-and-legs@7/1#0",title:"Pretend they are all the same — your turn",where:"The Strategy School · Level 7",route:"#/stop/heads-and-legs|drill",cta:"Practise this stop",play:{q:"A farm has hens (2 legs each) and goats (4 legs each): 11 heads and 26 legs altogether. How many goats are there?",opts:["2","4","22"],after:"Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.",show:[0,2,1]}},"trick-age-problems-idea":{id:"trick-age-problems-idea",kind:"trick",src:"stop:age-problems#idea",title:"The gap never changes",body:"Two people always stay the same number of years apart — so pin the question to the gap, which never moves. Every birthday, both people get one year older. So the GAP between their ages never changes: if Dax is 26 years younger than his uncle today, he will be 26 years younger for ever.",more:"In algebra: older = k × younger ⇒ younger = gap ÷ (k − 1)",cta:"Learn the trick",where:"The Strategy School · Level 7",level:7,route:"#/stop/age-problems|learn"},"story-age-problems-open":{id:"story-age-problems-open",kind:"story",src:"story:age-problems#open",badge:{id:"story",label:"A story"},title:"Twice as old",body:"At a family festival, Dax (11) and his uncle (37) wonder when the uncle will be exactly twice as old as Dax. — with Vesper and Dax.",more:"The trick inside: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.",art:"art/s-festival.webp",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/age-problems|story|0"},"idea-age-problems-case0":{id:"idea-age-problems-case0",kind:"idea",src:"stop:age-problems#case0",title:"The gap never changes: When will the total be…?",body:"The total of two ages grows by 2 every year — one year each.",more:"The method: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/age-problems|learn|0"},"idea-age-problems-case1":{id:"idea-age-problems-case1",kind:"idea",src:"stop:age-problems#case1",title:"The gap never changes: When will one be k times…?",body:"The gap stays fixed; when one is k times the other, the gap is (k − 1) lots of the younger age.",more:"The method: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/age-problems|learn|1"},"idea-age-problems-case2":{id:"idea-age-problems-case2",kind:"idea",src:"stop:age-problems#case2",title:"The gap never changes: How long ago was it?",body:"Same gap, other direction: find how old the younger one was then, and count back to it.",more:"The method: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/age-problems|learn|2"},"why-age-problems-why1":{id:"why-age-problems-why1",kind:"why",src:"stop:age-problems#why1",title:"Why “The gap never changes” works",body:`When the uncle is twice Dax's age, his age is Dax's age plus Dax's age again. That second "Dax's age" is the gap! So Dax will be 26, which is 26 − 11 = 15 years from now. For "three times as old", the gap is TWO lots of the younger age, so halve it.`,more:"The trick: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.",cta:"See why",where:"The Strategy School · Level 7",level:7,route:"#/stop/age-problems|learn"},"moment-age-problems-beat4":{id:"moment-age-problems-beat4",kind:"moment",src:"story:age-problems#beat4",badge:{id:"story",label:"A story"},title:"Twice as old — on the notepad",body:"Dax: Then he will be 52, which IS twice 26. (37 + 15) ÷ (11 + 15) = 2",more:"The trick in the story: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/age-problems|story|4"},"try-age-problems-L7":{id:"try-age-problems-L7",kind:"try",level:7,src:"try:age-problems@7/1#0",title:"The gap never changes — your turn",where:"The Strategy School · Level 7",route:"#/stop/age-problems|drill",cta:"Practise this stop",play:{q:"Maya is 3 and Tara is 8. In how many years will their ages add up to 31?",opts:["10","2","7"],after:"Two people always stay the same number of years apart — so pin the question to the gap, which never moves.",show:[1,0,2]}},"trick-simpler-case-idea":{id:"trick-simpler-case-idea",kind:"trick",src:"stop:simpler-case#idea",title:"Try a smaller one first",body:"When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one. A 60-metre fence is too long to draw, so draw a 10-metre one with a post every 5 metres. Count: post, gap, post, gap, post — 3 posts but only 2 gaps. The posts are always one more than the gaps. So the real fence has 60 ÷ 5 = 12 gaps and 13 posts.",more:"In algebra: posts in a line = gaps + 1 · posts in a ring = gaps · pieces = cuts + 1",cta:"Learn the trick",where:"The Strategy School · Level 7",level:7,route:"#/stop/simpler-case|learn"},"story-simpler-case-open":{id:"story-simpler-case-open",kind:"story",src:"story:simpler-case#open",badge:{id:"story",label:"A story"},title:"The rope fence",body:"For sports day, a 60-metre rope fence needs a post every 5 metres, with a post at each end. — with Theo and Pip.",more:"The trick inside: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.",art:"art/s-stadium.webp",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/simpler-case|story|0"},"idea-simpler-case-case0":{id:"idea-simpler-case-case0",kind:"idea",src:"stop:simpler-case#case0",title:"Try a smaller one first: Posts along a line",body:"A tiny fence shows it: posts are one more than the gaps.",more:"The method: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/simpler-case|learn|0"},"idea-simpler-case-case1":{id:"idea-simpler-case-case1",kind:"idea",src:"stop:simpler-case#case1",title:"Try a smaller one first: Cuts and pieces",body:"Two cuts make three pieces — the cuts are one fewer than the pieces.",more:"The method: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/simpler-case|learn|1"},"idea-simpler-case-case2":{id:"idea-simpler-case-case2",kind:"idea",src:"stop:simpler-case#case2",title:"Try a smaller one first: All the way round",body:"In a ring the last gap meets the first post, so trees and gaps are equal.",more:"The method: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/simpler-case|learn|2"},"idea-simpler-case-case3":{id:"idea-simpler-case-case3",kind:"idea",src:"stop:simpler-case#case3",title:"Try a smaller one first: Digits on the pages",body:"Split where the rule changes: one-digit pages, two-digit pages, three-digit pages.",more:"The method: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/simpler-case|learn|3"},"why-simpler-case-why1":{id:"why-simpler-case-why1",kind:"why",src:"stop:simpler-case#why1",title:"Why “Try a smaller one first” works",body:"The tiny case catches the trap that the quick answer falls into. Cutting a log into 3 pieces takes only 2 cuts, so pieces are one more than cuts. Round a pond, though, the last gap joins back to the first post, so trees and gaps are equal. Drawing a tiny ring shows it.",more:"The trick: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.",cta:"See why",where:"The Strategy School · Level 7",level:7,route:"#/stop/simpler-case|learn"},"moment-simpler-case-beat2":{id:"moment-simpler-case-beat2",kind:"moment",src:"story:simpler-case#beat2",badge:{id:"story",label:"A story"},title:"The rope fence — on the notepad",body:"Theo: Try a tiny one first: a 10-metre fence. Post, gap, post, gap, post. 10 ÷ 5 = 2",more:"The trick in the story: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/simpler-case|story|2"},"try-simpler-case-L7":{id:"try-simpler-case-L7",kind:"try",level:7,src:"try:simpler-case@7/1#0",title:"Try a smaller one first — your turn",where:"The Strategy School · Level 7",route:"#/stop/simpler-case|drill",cta:"Practise this stop",play:{q:"A straight fence is 16 metres long. There is a post every 2 metres, with a post at each end. How many posts are there?",opts:["9","3","8"],after:"When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.",show:[0,2,1]}},"trick-meeting-and-overtaking-idea":{id:"trick-meeting-and-overtaking-idea",kind:"trick",src:"stop:meeting-and-overtaking#idea",title:"Closing the gap",body:"Watch the GAP, not the people: find how much it shrinks each minute, and divide. Two people walking towards each other both eat up the gap between them. In one minute Nova covers 70 m and Suki 80 m, so the gap shrinks by 70 + 80 = 150 m. A 900 m gap takes 900 ÷ 150 = 6 minutes to close.",more:"In algebra: meet: time = gap ÷ (sum of speeds) · catch: time = head start ÷ (difference of speeds)",cta:"Learn the trick",where:"The Strategy School · Level 7",level:7,route:"#/stop/meeting-and-overtaking|learn"},"story-meeting-and-overtaking-open":{id:"story-meeting-and-overtaking-open",kind:"story",src:"story:meeting-and-overtaking#open",badge:{id:"story",label:"A story"},title:"Meeting at the bridge",body:"Nova and Suki stand at opposite ends of a 900-metre path round the pond. Nova walks 70 metres a minute, Suki 80. — with Nova and Suki.",more:"The trick inside: Watch the GAP, not the people: find how much it shrinks each minute, and divide.",art:"art/s-pond.webp",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/meeting-and-overtaking|story|0"},"idea-meeting-and-overtaking-case0":{id:"idea-meeting-and-overtaking-case0",kind:"idea",src:"stop:meeting-and-overtaking#case0",title:"Closing the gap: Towards each other: when?",body:"Both shrink the gap, so add the speeds.",more:"The method: Watch the GAP, not the people: find how much it shrinks each minute, and divide.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/meeting-and-overtaking|learn|0"},"idea-meeting-and-overtaking-case1":{id:"idea-meeting-and-overtaking-case1",kind:"idea",src:"stop:meeting-and-overtaking#case1",title:"Closing the gap: Towards each other: where?",body:"Find when first, then how far one of them has walked by then.",more:"The method: Watch the GAP, not the people: find how much it shrinks each minute, and divide.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/meeting-and-overtaking|learn|1"},"idea-meeting-and-overtaking-case2":{id:"idea-meeting-and-overtaking-case2",kind:"idea",src:"stop:meeting-and-overtaking#case2",title:"Closing the gap: Catching up: when?",body:"Same direction, so only the difference in speeds closes the gap.",more:"The method: Watch the GAP, not the people: find how much it shrinks each minute, and divide.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/meeting-and-overtaking|learn|2"},"idea-meeting-and-overtaking-case3":{id:"idea-meeting-and-overtaking-case3",kind:"idea",src:"stop:meeting-and-overtaking#case3",title:"Closing the gap: Catching up: where?",body:"Find when the chaser catches up, then how far the chaser has gone.",more:"The method: Watch the GAP, not the people: find how much it shrinks each minute, and divide.",cta:"See it worked",where:"The Strategy School · Level 7",level:7,route:"#/stop/meeting-and-overtaking|learn|3"},"why-meeting-and-overtaking-why1":{id:"why-meeting-and-overtaking-why1",kind:"why",src:"stop:meeting-and-overtaking#why1",title:"Why “Closing the gap” works",body:"When one chases the other in the same direction, the faster one gains only the DIFFERENCE in speeds each minute. If Bea walks 60 m a minute and Cal cycles 200, Cal closes the gap by 140 m every minute.",more:"The trick: Watch the GAP, not the people: find how much it shrinks each minute, and divide.",cta:"See why",where:"The Strategy School · Level 7",level:7,route:"#/stop/meeting-and-overtaking|learn"},"moment-meeting-and-overtaking-beat2":{id:"moment-meeting-and-overtaking-beat2",kind:"moment",src:"story:meeting-and-overtaking#beat2",badge:{id:"story",label:"A story"},title:"Meeting at the bridge — on the notepad",body:"Suki: Then we meet in this many minutes. 900 ÷ 150 = 6",more:"The trick in the story: Watch the GAP, not the people: find how much it shrinks each minute, and divide.",cta:"Read the story",where:"The Strategy School · Level 7",level:7,route:"#/stop/meeting-and-overtaking|story|2"},"try-meeting-and-overtaking-L7":{id:"try-meeting-and-overtaking-L7",kind:"try",level:7,src:"try:meeting-and-overtaking@7/1#0",title:"Closing the gap — your turn",where:"The Strategy School · Level 7",route:"#/stop/meeting-and-overtaking|drill",cta:"Practise this stop",play:{q:"Sami and Maya are 200 metres apart and walk towards each other. Sami walks 30 metres a minute and Maya walks 70 metres a minute. After how many minutes do they meet?",opts:["2","1","5"],after:"Watch the GAP, not the people: find how much it shrinks each minute, and divide.",show:[1,0,2]}},"word-arrangement":{id:"word-arrangement",kind:"word",src:"dictionary:arrangement#def",title:"arrangement",body:"One way of putting things in order, in a row or in named places. For example: A, B and C can go in 6 orders: ABC, ACB, BAC, BCA, CAB and CBA — that is 3! = 6.",more:"Taught at: Putting things in order · Factorials.",where:"The Data Carnival",route:"#/lib/dictionary|arrangement",cta:"arrangement in the Dictionary",level:7},"wordq-arrangement":{id:"wordq-arrangement",kind:"wordq",src:"dictionary:arrangement#ex",title:"Which maths word?",route:"#/lib/dictionary|arrangement",cta:"Look it up",play:{q:"Which word is this an example of? “A, B and C can go in 6 orders: ABC, ACB, BAC, BCA, CAB and CBA — that is 3! = 6.”",opts:["arrangement","net","integer"],after:"arrangement: One way of putting things in order, in a row or in named places.",show:[0,1,2]},level:7},"word-coefficient":{id:"word-coefficient",kind:"word",src:"dictionary:coefficient#def",title:"coefficient",body:"The number in front of a letter, which multiplies it. For example: In 4x it is 4.",more:"Taught at: Collecting like terms.",where:"Set Island",route:"#/lib/dictionary|coefficient",cta:"coefficient in the Dictionary",level:7},"wordq-coefficient":{id:"wordq-coefficient",kind:"wordq",src:"dictionary:coefficient#ex",title:"Which maths word?",route:"#/lib/dictionary|coefficient",cta:"Look it up",play:{q:"Which word is this an example of? “In 4x it is 4.”",opts:["coefficient","hundredth","long multiplication"],after:"coefficient: The number in front of a letter, which multiplies it.",show:[1,2,0]},level:7},"word-compound-measure":{id:"word-compound-measure",kind:"word",src:"dictionary:compound measure#def",title:"compound measure",body:"A measure made from two others, like kilometres per hour or grams per cubic centimetre. For example: 90 km/h means 90 km in each hour.",more:"Taught at: Speed, distance and time.",where:"The Decimal Dock",route:"#/lib/dictionary|compound measure",cta:"compound measure in the Dictionary",level:7},"wordq-compound-measure":{id:"wordq-compound-measure",kind:"wordq",src:"dictionary:compound measure#ex",title:"Which maths word?",route:"#/lib/dictionary|compound measure",cta:"Look it up",play:{q:"Which word is this an example of? “90 km/h means 90 km in each hour.”",opts:["compound measure","inverse operation","exterior angle"],after:"compound measure: A measure made from two others, like kilometres per hour or grams per cubic centimetre.",show:[0,2,1]},level:7},"word-cube-number":{id:"word-cube-number",kind:"word",src:"dictionary:cube number#def",title:"cube number",body:"A whole number multiplied by itself and then by itself again — that many small blocks build one big block with equal edges. For example: 64 = 4 × 4 × 4.",more:"Taught at: Cubes and cube roots.",where:"The Square Palace",route:"#/lib/dictionary|cube number",cta:"cube number in the Dictionary",level:7},"wordq-cube-number":{id:"wordq-cube-number",kind:"wordq",src:"dictionary:cube number#ex",title:"Which maths word?",route:"#/lib/dictionary|cube number",cta:"Look it up",play:{q:"Which word is this an example of? “64 = 4 × 4 × 4.”",opts:["cube number","perpendicular height","density"],after:"cube number: A whole number multiplied by itself and then by itself again — that many small blocks build one big block with equal edges.",show:[0,1,2]},level:7},"word-cube-root":{id:"word-cube-root",kind:"word",src:"dictionary:cube root#def",title:"cube root",body:"The number which, used three times in a multiplication, gives the one you started with. Sign: ∛. For example: ∛125 = 5, because 5 × 5 × 5 = 125.",more:"Taught at: Cubes and cube roots.",where:"The Square Palace",route:"#/lib/dictionary|cube root",cta:"cube root in the Dictionary",level:7},"wordq-cube-root":{id:"wordq-cube-root",kind:"wordq",src:"dictionary:cube root#ex",title:"Which maths word?",route:"#/lib/dictionary|cube root",cta:"Look it up",play:{q:"Which word is this an example of? “∛125 = 5, because 5 × 5 × 5 = 125.”",opts:["cube root","mode","Euler’s formula"],after:"cube root: The number which, used three times in a multiplication, gives the one you started with. Sign: ∛.",show:[0,2,1]},level:7},"word-cubic-centimetre":{id:"word-cubic-centimetre",kind:"word",src:"dictionary:cubic centimetre#def",title:"cubic centimetre",body:"The volume of a cube 1 cm by 1 cm by 1 cm. Written cm³. For example: A 1 ml spoonful of water fills 1 cm³.",more:"Taught at: Volume and surface area.",where:"The Clock Tower",route:"#/lib/dictionary|cubic centimetre",cta:"cubic centimetre in the Dictionary",level:7},"wordq-cubic-centimetre":{id:"wordq-cubic-centimetre",kind:"wordq",src:"dictionary:cubic centimetre#ex",title:"Which maths word?",route:"#/lib/dictionary|cubic centimetre",cta:"Look it up",play:{q:"Which word is this an example of? “A 1 ml spoonful of water fills 1 cm³.”",opts:["cubic centimetre","empty set","even chance"],after:"cubic centimetre: The volume of a cube 1 cm by 1 cm by 1 cm. Written cm³.",show:[2,1,0]},level:7},"word-cuboid":{id:"word-cuboid",kind:"word",src:"dictionary:cuboid#def",title:"cuboid",body:"A box shape: a solid with six rectangular faces. For example: A box 30 cm × 20 cm × 10 cm.",more:"Taught at: Volume and surface area.",where:"The Clock Tower",route:"#/lib/dictionary|cuboid",cta:"cuboid in the Dictionary",level:7},"wordq-cuboid":{id:"wordq-cuboid",kind:"wordq",src:"dictionary:cuboid#ex",title:"Which maths word?",route:"#/lib/dictionary|cuboid",cta:"Look it up",play:{q:"Which word is this an example of? “A box 30 cm × 20 cm × 10 cm.”",opts:["cuboid","order of operations","quotient"],after:"cuboid: A box shape: a solid with six rectangular faces.",show:[2,1,0]},level:7},"word-density":{id:"word-density",kind:"word",src:"dictionary:density#def",title:"density",body:"How much mass is packed into each unit of volume. For example: 200 g in 100 cm³ is 2 g/cm³.",more:"Taught at: Speed, distance and time.",where:"The Decimal Dock",route:"#/lib/dictionary|density",cta:"density in the Dictionary",level:7},"wordq-density":{id:"wordq-density",kind:"wordq",src:"dictionary:density#ex",title:"Which maths word?",route:"#/lib/dictionary|density",cta:"Look it up",play:{q:"Which word is this an example of? “200 g in 100 cm³ is 2 g/cm³.”",opts:["density","diameter","divisible"],after:"density: How much mass is packed into each unit of volume.",show:[1,0,2]},level:7},"word-direct-proportion":{id:"word-direct-proportion",kind:"word",src:"dictionary:direct proportion#def",title:"direct proportion",body:"When one amount doubles, the other doubles too; when one halves, so does the other. For example: 3 pens cost £6, so 6 pens cost £12.",more:"Taught at: Find one, then scale.",where:"The Decimal Dock",route:"#/lib/dictionary|direct proportion",cta:"direct proportion in the Dictionary",level:7},"wordq-direct-proportion":{id:"wordq-direct-proportion",kind:"wordq",src:"dictionary:direct proportion#ex",title:"Which maths word?",route:"#/lib/dictionary|direct proportion",cta:"Look it up",play:{q:"Which word is this an example of? “3 pens cost £6, so 6 pens cost £12.”",opts:["direct proportion","times table","mean"],after:"direct proportion: When one amount doubles, the other doubles too; when one halves, so does the other.",show:[2,0,1]},level:7},"word-distance":{id:"word-distance",kind:"word",src:"dictionary:distance#def",title:"distance",body:"How far it is from one place to another. For example: 3 hours at 50 km/h covers 150 km.",more:"Taught at: Speed, distance and time.",where:"The Decimal Dock",route:"#/lib/dictionary|distance",cta:"distance in the Dictionary",level:7},"wordq-distance":{id:"wordq-distance",kind:"wordq",src:"dictionary:distance#ex",title:"Which maths word?",route:"#/lib/dictionary|distance",cta:"Look it up",play:{q:"Which word is this an example of? “3 hours at 50 km/h covers 150 km.”",opts:["distance","tenth","square root"],after:"distance: How far it is from one place to another.",show:[1,2,0]},level:7},"word-equally-likely":{id:"word-equally-likely",kind:"word",src:"dictionary:equally likely#def",title:"equally likely",body:"Having exactly the same chance as each other. For example: Each face of a fair dice: 1/6 each.",more:"Taught at: Chance as a fraction.",where:"The Data Carnival",route:"#/lib/dictionary|equally likely",cta:"equally likely in the Dictionary",level:7},"wordq-equally-likely":{id:"wordq-equally-likely",kind:"wordq",src:"dictionary:equally likely#ex",title:"Which maths word?",route:"#/lib/dictionary|equally likely",cta:"Look it up",play:{q:"Which word is this an example of? “Each face of a fair dice: 1/6 each.”",opts:["equally likely","metric","compound measure"],after:"equally likely: Having exactly the same chance as each other.",show:[2,1,0]},level:7},"word-factorial":{id:"word-factorial",kind:"word",src:"dictionary:factorial#def",title:"factorial",body:"A whole number multiplied by every whole number below it, down to 1 — the number of orders that many different things can go in. Sign: !. For example: 5! = 5 × 4 × 3 × 2 × 1 = 120, and 0! = 1.",more:"Taught at: Factorials · Putting things in order.",where:"The Data Carnival",route:"#/lib/dictionary|factorial",cta:"factorial in the Dictionary",level:7},"wordq-factorial":{id:"wordq-factorial",kind:"wordq",src:"dictionary:factorial#ex",title:"Which maths word?",route:"#/lib/dictionary|factorial",cta:"Look it up",play:{q:"Which word is this an example of? “5! = 5 × 4 × 3 × 2 × 1 = 120, and 0! = 1.”",opts:["factorial","diagonal","mental maths"],after:"factorial: A whole number multiplied by every whole number below it, down to 1 — the number of orders that many different things can go in. Sign: !.",show:[2,0,1]},level:7},"word-outcome":{id:"word-outcome",kind:"word",src:"dictionary:outcome#def",title:"outcome",body:"One possible result of something like a roll or a spin. For example: A dice has six: 1, 2, 3, 4, 5 and 6.",more:"Taught at: Counting all the ways.",where:"The Data Carnival",route:"#/lib/dictionary|outcome",cta:"outcome in the Dictionary",level:7},"wordq-outcome":{id:"wordq-outcome",kind:"wordq",src:"dictionary:outcome#ex",title:"Which maths word?",route:"#/lib/dictionary|outcome",cta:"Look it up",play:{q:"Which word is this an example of? “A dice has six: 1, 2, 3, 4, 5 and 6.”",opts:["outcome","linear","substitute"],after:"outcome: One possible result of something like a roll or a spin.",show:[2,1,0]},level:7},"word-probability":{id:"word-probability",kind:"word",src:"dictionary:probability#def",title:"probability",body:"How likely something is, as a number from 0 (it cannot happen) to 1 (it must). For example: A fair coin landing heads: 1/2.",more:"Taught at: Chance as a fraction.",where:"The Data Carnival",route:"#/lib/dictionary|probability",cta:"probability in the Dictionary",level:7},"word-rate":{id:"word-rate",kind:"word",src:"dictionary:rate#def",title:"rate",body:"How much of one thing there is for each one of another. For example: 60 km per hour; £8 per kilogram.",more:"Taught at: Speed, distance and time · Find one, then scale.",where:"The Decimal Dock",route:"#/lib/dictionary|rate",cta:"rate in the Dictionary",level:7},"wordq-rate":{id:"wordq-rate",kind:"wordq",src:"dictionary:rate#ex",title:"Which maths word?",route:"#/lib/dictionary|rate",cta:"Look it up",play:{q:"Which word is this an example of? “60 km per hour; £8 per kilogram.”",opts:["rate","decimal point","Venn diagram"],after:"rate: How much of one thing there is for each one of another.",show:[0,2,1]},level:7},"word-sample-space":{id:"word-sample-space",kind:"word",src:"dictionary:sample space#def",title:"sample space",body:"A list or table of every possible outcome. For example: Two coins: HH, HT, TH, TT — 4 outcomes.",more:"Taught at: Counting all the ways.",where:"The Data Carnival",route:"#/lib/dictionary|sample space",cta:"sample space in the Dictionary",level:7},"wordq-sample-space":{id:"wordq-sample-space",kind:"wordq",src:"dictionary:sample space#ex",title:"Which maths word?",route:"#/lib/dictionary|sample space",cta:"Look it up",play:{q:"Which word is this an example of? “Two coins: HH, HT, TH, TT — 4 outcomes.”",opts:["sample space","empty set","prime factorisation"],after:"sample space: A list or table of every possible outcome.",show:[0,2,1]},level:7},"word-simple-interest":{id:"word-simple-interest",kind:"word",src:"dictionary:simple interest#def",title:"simple interest",body:"Extra money on savings or a loan worked out on the starting amount only, so the same amount is added every year. For example: £200 at 5% for 3 years: 3 × £10 = £30.",more:"Taught at: Percentages of an amount.",where:"The Decimal Dock",route:"#/lib/dictionary|simple interest",cta:"simple interest in the Dictionary",level:7},"wordq-simple-interest":{id:"wordq-simple-interest",kind:"wordq",src:"dictionary:simple interest#ex",title:"Which maths word?",route:"#/lib/dictionary|simple interest",cta:"Look it up",play:{q:"Which word is this an example of? “£200 at 5% for 3 years: 3 × £10 = £30.”",opts:["simple interest","chance","like terms"],after:"simple interest: Extra money on savings or a loan worked out on the starting amount only, so the same amount is added every year.",show:[2,0,1]},level:7},"word-speed":{id:"word-speed",kind:"word",src:"dictionary:speed#def",title:"speed",body:"How far something travels in each unit of time. For example: 120 km in 2 hours is 60 km/h.",more:"Taught at: Speed, distance and time.",where:"The Decimal Dock",route:"#/lib/dictionary|speed",cta:"speed in the Dictionary",level:7},"wordq-speed":{id:"wordq-speed",kind:"wordq",src:"dictionary:speed#ex",title:"Which maths word?",route:"#/lib/dictionary|speed",cta:"Look it up",play:{q:"Which word is this an example of? “120 km in 2 hours is 60 km/h.”",opts:["speed","short division","proportion"],after:"speed: How far something travels in each unit of time.",show:[0,1,2]},level:7},"word-surface-area":{id:"word-surface-area",kind:"word",src:"dictionary:surface area#def",title:"surface area",body:"The total area of all the faces of a solid. For example: A 1 cm cube: 6 faces × 1 cm² = 6 cm².",more:"Taught at: Volume and surface area.",where:"The Clock Tower",route:"#/lib/dictionary|surface area",cta:"surface area in the Dictionary",level:7},"wordq-surface-area":{id:"wordq-surface-area",kind:"wordq",src:"dictionary:surface area#ex",title:"Which maths word?",route:"#/lib/dictionary|surface area",cta:"Look it up",play:{q:"Which word is this an example of? “A 1 cm cube: 6 faces × 1 cm² = 6 cm².”",opts:["surface area","negative number","product"],after:"surface area: The total area of all the faces of a solid.",show:[1,2,0]},level:7},"word-unitary-method":{id:"word-unitary-method",kind:"word",src:"dictionary:unitary method#def",title:"unitary method",body:"Find the value of one first, then multiply up to the amount you need. For example: 4 cakes cost £8 → 1 costs £2 → 7 cost £14.",more:"Taught at: Find one, then scale.",where:"The Decimal Dock",route:"#/lib/dictionary|unitary method",cta:"unitary method in the Dictionary",level:7},"wordq-unitary-method":{id:"wordq-unitary-method",kind:"wordq",src:"dictionary:unitary method#ex",title:"Which maths word?",route:"#/lib/dictionary|unitary method",cta:"Look it up",play:{q:"Which word is this an example of? “4 cakes cost £8 → 1 costs £2 → 7 cost £14.”",opts:["unitary method","scalene triangle","hundredth"],after:"unitary method: Find the value of one first, then multiply up to the amount you need.",show:[0,1,2]},level:7},"word-volume":{id:"word-volume",kind:"word",src:"dictionary:volume#def",title:"volume",body:"How much space a solid takes up, counted in cubes. For example: 4 × 3 × 2 = 24 cm³.",more:"Taught at: Volume and surface area.",where:"The Clock Tower",route:"#/lib/dictionary|volume",cta:"volume in the Dictionary",level:7},"wordq-volume":{id:"wordq-volume",kind:"wordq",src:"dictionary:volume#ex",title:"Which maths word?",route:"#/lib/dictionary|volume",cta:"Look it up",play:{q:"Which word is this an example of? “4 × 3 × 2 = 24 cm³.”",opts:["volume","power","rounding"],after:"volume: How much space a solid takes up, counted in cubes.",show:[2,0,1]},level:7},"word-working-backwards":{id:"word-working-backwards",kind:"word",src:"dictionary:working backwards#def",title:"working backwards",body:"Undoing each step in reverse order to find what you started with. For example: Out 13, rule “× 2 then + 3”: 13 − 3 = 10, 10 ÷ 2 = 5.",more:"Taught at: Working backwards.",where:"The Data Carnival",route:"#/lib/dictionary|working backwards",cta:"working backwards in the Dictionary",level:7},"wordq-working-backwards":{id:"wordq-working-backwards",kind:"wordq",src:"dictionary:working backwards#ex",title:"Which maths word?",route:"#/lib/dictionary|working backwards",cta:"Look it up",play:{q:"Which word is this an example of? “Out 13, rule “× 2 then + 3”: 13 − 3 = 10, 10 ÷ 2 = 5.”",opts:["working backwards","triangle","sum"],after:"working backwards: Undoing each step in reverse order to find what you started with.",show:[1,0,2]},level:7},"formula-volume-cuboid":{id:"formula-volume-cuboid",kind:"formula",src:"formula:volume-cuboid",title:"Volume of a cuboid",body:"V = l × w × h. One layer is l × w cubes; there are h layers.",more:"Taught at: Volume and surface area.",where:"The Clock Tower",route:"#/lib/formulas|volume-cuboid",cta:"Volume of a cuboid in the Formula Book",play:{q:"Volume of a cuboid: A box 5 cm by 4 cm by 3 cm.",opts:["60","50","6"],after:"one layer: 5 × 4 = 20 · V = 20 × 3 = 60 cm³",show:[1,2,0]},level:7},"formula-why-volume-cuboid-0":{id:"formula-why-volume-cuboid-0",kind:"formula-why",src:"formula:volume-cuboid#why0",title:"Why V = l × w × h",body:"Fill the bottom of the box with centimetre cubes: that is l × w cubes, one layer.",more:"The card: Volume of a cuboid — One layer is l × w cubes; there are h layers.",route:"#/lib/formulas|volume-cuboid",cta:"Volume of a cuboid in the Formula Book",level:7},"formula-why-volume-cuboid-1":{id:"formula-why-volume-cuboid-1",kind:"formula-why",src:"formula:volume-cuboid#why1",title:"Why V = l × w × h",body:"Stack h layers like that and the box is full. So the volume is l × w × h cubic units — the floor’s area times the height.",more:"The card: Volume of a cuboid — One layer is l × w cubes; there are h layers.",route:"#/lib/formulas|volume-cuboid",cta:"Volume of a cuboid in the Formula Book",level:7},"formula-story-volume-cuboid":{id:"formula-story-volume-cuboid",kind:"formula-story",src:"formula:volume-cuboid#story",badge:{id:"story",label:"A story"},title:"Packing the sugar cubes",body:"Suki is filling a box with sugar cubes. It fits 5 cubes along, 4 across and 3 layers high. — with Nova and Suki.",art:"art/s-shop.webp",route:"#/lib/formulas|volume-cuboid",cta:"Volume of a cuboid in the Formula Book",level:7},"formula-try-volume-cuboid":{id:"formula-try-volume-cuboid",kind:"formula-try",src:"formula:volume-cuboid#gen0",title:"Volume of a cuboid — your turn",route:"#/lib/formulas|volume-cuboid",cta:"Volume of a cuboid in the Formula Book",play:{q:"Volume of a box 5 cm by 10 cm by 6 cm (in cm³) = ?",opts:["300","3000","400"],after:"V = l × w × h",show:[1,0,2]},level:7},"formula-surface-area-cuboid":{id:"formula-surface-area-cuboid",kind:"formula",src:"formula:surface-area-cuboid",title:"Surface area of a cuboid",body:"S = 2 × (lw + lh + wh). Unfold the box: three pairs of matching faces.",more:"Taught at: Volume and surface area.",where:"The Clock Tower",route:"#/lib/formulas|surface-area-cuboid",cta:"Surface area of a cuboid in the Formula Book",play:{q:"Surface area of a cuboid: A box 5 cm by 3 cm by 2 cm.",opts:["62","52","26"],after:"5 × 3 + 5 × 2 + 3 × 2 = 15 + 10 + 6 = 31 · S = 2 × 31 = 62 cm²",show:[1,2,0]},level:7},"formula-why-surface-area-cuboid-0":{id:"formula-why-surface-area-cuboid-0",kind:"formula-why",src:"formula:surface-area-cuboid#why0",title:"Why S = 2 × (lw + lh + wh)",body:"A box has six faces, and they come in three matching pairs: top and bottom, front and back, left and right.",more:"The card: Surface area of a cuboid — Unfold the box: three pairs of matching faces.",route:"#/lib/formulas|surface-area-cuboid",cta:"Surface area of a cuboid in the Formula Book",level:7},"formula-why-surface-area-cuboid-1":{id:"formula-why-surface-area-cuboid-1",kind:"formula-why",src:"formula:surface-area-cuboid#why1",title:"Why S = 2 × (lw + lh + wh)",body:"The pairs have areas l × w, l × h and w × h. Add one of each and double: S = 2 × (lw + lh + wh). Unfold the box into its net and you can see all six at once.",more:"The card: Surface area of a cuboid — Unfold the box: three pairs of matching faces.",route:"#/lib/formulas|surface-area-cuboid",cta:"Surface area of a cuboid in the Formula Book",level:7},"formula-story-surface-area-cuboid":{id:"formula-story-surface-area-cuboid",kind:"formula-story",src:"formula:surface-area-cuboid#story",badge:{id:"story",label:"A story"},title:"Wrapping the present",body:"Dax is wrapping a box 30 cm long, 20 cm wide and 10 cm tall. How much paper covers it exactly? — with Ines and Dax.",art:"art/s-festival.webp",route:"#/lib/formulas|surface-area-cuboid",cta:"Surface area of a cuboid in the Formula Book",level:7},"formula-try-surface-area-cuboid":{id:"formula-try-surface-area-cuboid",kind:"formula-try",src:"formula:surface-area-cuboid#gen0",title:"Surface area of a cuboid — your turn",route:"#/lib/formulas|surface-area-cuboid",cta:"Surface area of a cuboid in the Formula Book",play:{q:"Surface area of a box 9 cm by 5 cm by 7 cm (in cm²) = ?",opts:["286","186","276"],after:"S = 2 × (lw + lh + wh)",show:[2,0,1]},level:7},"formula-volume-cube":{id:"formula-volume-cube",kind:"formula",src:"formula:volume-cube",title:"Volume of a cube",body:"V = s × s × s = s³. s × s in a layer, and s layers: s³, “s cubed”.",more:"Taught at: Cubes and cube roots · Volume and surface area.",where:"The Square Palace",route:"#/lib/formulas|volume-cube",cta:"Volume of a cube in the Formula Book",play:{q:"Volume of a cube: A cube with 4 cm edges.",opts:["64","640","74"],after:"4 × 4 = 16 in a layer · V = 16 × 4 = 64 cm³",show:[0,2,1]},level:7},"formula-why-volume-cube-0":{id:"formula-why-volume-cube-0",kind:"formula-why",src:"formula:volume-cube#why0",title:"Why V = s × s × s = s³",body:"A cube is a cuboid whose length, width and height are all the same, so l × w × h becomes s × s × s.",more:"The card: Volume of a cube — s × s in a layer, and s layers: s³, “s cubed”.",route:"#/lib/formulas|volume-cube",cta:"Volume of a cube in the Formula Book",level:7},"formula-why-volume-cube-1":{id:"formula-why-volume-cube-1",kind:"formula-why",src:"formula:volume-cube#why1",title:"Why V = s × s × s = s³",body:"That is why s³ is called “s cubed”: it counts the little cubes in a big cube of side s. A 3 by 3 by 3 cube holds 9 in each layer and 3 layers: 27.",more:"The card: Volume of a cube — s × s in a layer, and s layers: s³, “s cubed”.",route:"#/lib/formulas|volume-cube",cta:"Volume of a cube in the Formula Book",level:7},"formula-story-volume-cube":{id:"formula-story-volume-cube",kind:"formula-story",src:"formula:volume-cube#story",badge:{id:"story",label:"A story"},title:"The block tower",body:"Pip builds one big cube out of little wooden blocks, 4 blocks along every edge. — with Mira and Pip.",art:"art/s-room.webp",route:"#/lib/formulas|volume-cube",cta:"Volume of a cube in the Formula Book",level:7},"formula-try-volume-cube":{id:"formula-try-volume-cube",kind:"formula-try",src:"formula:volume-cube#gen0",title:"Volume of a cube — your turn",route:"#/lib/formulas|volume-cube",cta:"Volume of a cube in the Formula Book",play:{q:"Volume of a cube with 5 cm edges (in cm³) = ?",opts:["125","115","25"],after:"V = s × s × s = s³",show:[1,0,2]},level:7},"formula-volume-prism":{id:"formula-volume-prism",kind:"formula",src:"formula:volume-prism",title:"Volume of a prism",body:"V = area of end × length. Every slice is the same as the end, so stack the end along the length.",more:"Taught at: Volume and surface area · Triangles and parallelograms.",where:"The Clock Tower",route:"#/lib/formulas|volume-prism",cta:"Volume of a prism in the Formula Book",play:{q:"Volume of a prism: A prism whose end is a triangle, base 6 cm and height 4 cm, 10 cm long.",opts:["120","20","210"],after:"end: 6 × 4 ÷ 2 = 12 cm² · V = 12 × 10 = 120 cm³",show:[1,2,0]},level:7},"formula-why-volume-prism-0":{id:"formula-why-volume-prism-0",kind:"formula-why",src:"formula:volume-prism#why0",title:"Why V = area of end × length",body:"A prism is the same shape all the way through, like a loaf of bread: every slice is a copy of the end.",more:"The card: Volume of a prism — Every slice is the same as the end, so stack the end along the length.",route:"#/lib/formulas|volume-prism",cta:"Volume of a prism in the Formula Book",level:7},"formula-why-volume-prism-1":{id:"formula-why-volume-prism-1",kind:"formula-why",src:"formula:volume-prism#why1",title:"Why V = area of end × length",body:"So the end’s area tells you how much fills one slice 1 unit thick, and the length tells you how many slices there are. V = area of the end × length. A cuboid is simply a prism with a rectangle for its end.",more:"The card: Volume of a prism — Every slice is the same as the end, so stack the end along the length.",route:"#/lib/formulas|volume-prism",cta:"Volume of a prism in the Formula Book",level:7},"formula-story-volume-prism":{id:"formula-story-volume-prism",kind:"formula-story",src:"formula:volume-prism#story",badge:{id:"story",label:"A story"},title:"The tent",body:"Theo and Suki pitch a tent shaped like a triangular prism. The end is 2 m wide and 1.5 m tall; the tent is 3 m long. — with Suki and Theo.",art:"art/s-forest.webp",route:"#/lib/formulas|volume-prism",cta:"Volume of a prism in the Formula Book",level:7},"formula-try-volume-prism":{id:"formula-try-volume-prism",kind:"formula-try",src:"formula:volume-prism#gen0",title:"Volume of a prism — your turn",route:"#/lib/formulas|volume-prism",cta:"Volume of a prism in the Formula Book",play:{q:"A prism’s end is a triangle, base 10 cm and height 7 cm. It is 5 cm long. Volume (in cm³)?",opts:["175","715","1750"],after:"V = area of end × length",show:[2,1,0]},level:7},"formula-percent-of-amount":{id:"formula-percent-of-amount",kind:"formula",src:"formula:percent-of-amount",title:"A percentage of an amount",body:"p% of x = x ÷ 100 × p. 15% is 15 squares out of every 100.",more:"Taught at: Percentages of an amount.",where:"The Decimal Dock",route:"#/lib/formulas|percent-of-amount",cta:"A percentage of an amount in the Formula Book",play:{q:"A percentage of an amount: 15% of 80.",opts:["12","2","6"],after:"10% = 8, 5% = 4 · 15% = 8 + 4 = 12",show:[1,2,0]},level:7},"formula-why-percent-of-amount-0":{id:"formula-why-percent-of-amount-0",kind:"formula-why",src:"formula:percent-of-amount#why0",title:"Why p% of x = x ÷ 100 × p",body:"Per cent means “out of every hundred”. Split the amount into 100 equal parts and each part is 1%: x ÷ 100. Then take p of those parts.",more:"The card: A percentage of an amount — 15% is 15 squares out of every 100.",route:"#/lib/formulas|percent-of-amount",cta:"A percentage of an amount in the Formula Book",level:7},"formula-why-percent-of-amount-1":{id:"formula-why-percent-of-amount-1",kind:"formula-why",src:"formula:percent-of-amount#why1",title:"Why p% of x = x ÷ 100 × p",body:"Often it is quicker to find 10% (divide by 10) and build from it: 30% is three lots of 10%, 5% is half of 10%, 15% is 10% and 5% together.",more:"The card: A percentage of an amount — 15% is 15 squares out of every 100.",route:"#/lib/formulas|percent-of-amount",cta:"A percentage of an amount in the Formula Book",level:7},"formula-story-percent-of-amount":{id:"formula-story-percent-of-amount",kind:"formula-story",src:"formula:percent-of-amount#story",badge:{id:"story",label:"A story"},title:"The sale rail",body:"A jacket costs £60. The shop takes 15% off. How much is taken off? — with Ines and Dax.",art:"art/s-shop.webp",route:"#/lib/formulas|percent-of-amount",cta:"A percentage of an amount in the Formula Book",level:7},"formula-try-percent-of-amount":{id:"formula-try-percent-of-amount",kind:"formula-try",src:"formula:percent-of-amount#gen0",title:"A percentage of an amount — your turn",route:"#/lib/formulas|percent-of-amount",cta:"A percentage of an amount in the Formula Book",play:{q:"40% of 280 = ?",opts:["112","122","121"],after:"p% of x = x ÷ 100 × p",show:[0,2,1]},level:7},"formula-speed-distance-time":{id:"formula-speed-distance-time",kind:"formula",src:"formula:speed-distance-time",title:"Speed, distance and time",body:"speed = distance ÷ time. Cover the one you want; the other two tell you what to do.",more:"Taught at: Speed, distance and time.",where:"The Decimal Dock",route:"#/lib/formulas|speed-distance-time",cta:"Speed, distance and time in the Formula Book",play:{q:"Speed, distance and time: 240 km in 3 hours.",opts:["80","42","8"],after:"speed = 240 ÷ 3 · = 80 km/h",show:[0,1,2]},level:7},"formula-why-speed-distance-time-0":{id:"formula-why-speed-distance-time-0",kind:"formula-why",src:"formula:speed-distance-time#why0",title:"Why speed = distance ÷ time",body:"Speed says how far you go in each hour (or each second). If a train goes 240 km in 3 hours at a steady speed, each hour carries it the same distance: 240 ÷ 3 = 80 km.",more:"The card: Speed, distance and time — Cover the one you want; the other two tell you what to do.",route:"#/lib/formulas|speed-distance-time",cta:"Speed, distance and time in the Formula Book",level:7},"formula-why-speed-distance-time-1":{id:"formula-why-speed-distance-time-1",kind:"formula-why",src:"formula:speed-distance-time#why1",title:"Why speed = distance ÷ time",body:"The same fact turns round: distance = speed × time, and time = distance ÷ speed. Cover the one you want in the triangle — D on top, S and T below — and the other two tell you what to do.",more:"The card: Speed, distance and time — Cover the one you want; the other two tell you what to do.",route:"#/lib/formulas|speed-distance-time",cta:"Speed, distance and time in the Formula Book",level:7},"formula-story-speed-distance-time":{id:"formula-story-speed-distance-time",kind:"formula-story",src:"formula:speed-distance-time#story",badge:{id:"story",label:"A story"},title:"The train to the coast",body:"The train to the coast covers 180 km in 2 hours. Dax wants to know how fast it goes. — with Theo and Dax.",art:"art/s-train.webp",route:"#/lib/formulas|speed-distance-time",cta:"Speed, distance and time in the Formula Book",level:7},"formula-try-speed-distance-time":{id:"formula-try-speed-distance-time",kind:"formula-try",src:"formula:speed-distance-time#gen0",title:"Speed, distance and time — your turn",route:"#/lib/formulas|speed-distance-time",cta:"Speed, distance and time in the Formula Book",play:{q:"A cyclist covers 720 km at 120 km/h. How many hours does it take?",opts:["6","5","2"],after:"speed = distance ÷ time",show:[0,1,2]},level:7},"formula-density":{id:"formula-density",kind:"formula",src:"formula:density",title:"Density",body:"density = mass ÷ volume. Same size, different mass in every cube: different density.",more:"Taught at: Speed, distance and time · Volume and surface area.",where:"The Decimal Dock",route:"#/lib/formulas|density",cta:"Density in the Formula Book",play:{q:"Density: A block of 600 g with a volume of 200 cm³.",opts:["3","2","6"],after:"density = 600 ÷ 200 · = 3 g/cm³",show:[2,1,0]},level:7},"formula-why-density-0":{id:"formula-why-density-0",kind:"formula-why",src:"formula:density#why0",title:"Why density = mass ÷ volume",body:"Density is a compound measure, like speed: it says how many grams are packed into each cubic centimetre. Share the mass equally over the volume: mass ÷ volume.",more:"The card: Density — Same size, different mass in every cube: different density.",route:"#/lib/formulas|density",cta:"Density in the Formula Book",level:7},"formula-why-density-1":{id:"formula-why-density-1",kind:"formula-why",src:"formula:density#why1",title:"Why density = mass ÷ volume",body:"A brick and a sponge of the same size have the same volume but very different masses, so very different densities. Like speed, it turns round: mass = density × volume.",more:"The card: Density — Same size, different mass in every cube: different density.",route:"#/lib/formulas|density",cta:"Density in the Formula Book",level:7},"formula-story-density":{id:"formula-story-density",kind:"formula-story",src:"formula:density#story",badge:{id:"story",label:"A story"},title:"The mystery stone",body:"Theo finds a smooth stone on the beach. It has a mass of 270 g. Dropped into a measuring jug, it pushes the water up by 100 cm³. — with Theo and Mira.",art:"art/s-beach.webp",route:"#/lib/formulas|density",cta:"Density in the Formula Book",level:7},"formula-try-density":{id:"formula-try-density",kind:"formula-try",src:"formula:density#gen0",title:"Density — your turn",route:"#/lib/formulas|density",cta:"Density in the Formula Book",play:{q:"A block has a mass of 90 g and a volume of 10 cm³. Its density (in g/cm³)?",opts:["9","8","6"],after:"density = mass ÷ volume",show:[1,0,2]},level:7},"formula-probability":{id:"formula-probability",kind:"formula",src:"formula:probability",title:"Probability",body:"P = ways it can happen ÷ all the ways. Count what you want, over everything that could happen.",more:"Taught at: Chance as a fraction · Counting all the ways.",where:"The Data Carnival",route:"#/lib/formulas|probability",cta:"Probability in the Formula Book",play:{q:"Probability: A bag of 3 red and 5 blue counters. The chance of red?",opts:["3/8","8/3","5/8"],after:"all the ways: 3 + 5 = 8 · P(red) = 3/8",show:[2,0,1]},level:7},"formula-why-probability-0":{id:"formula-why-probability-0",kind:"formula-why",src:"formula:probability#why0",title:"Why P = ways it can happen ÷ all the ways",body:"When every outcome is equally likely, count them all: that is the bottom of the fraction. Count the ones you want: that is the top.",more:"The card: Probability — Count what you want, over everything that could happen.",route:"#/lib/formulas|probability",cta:"Probability in the Formula Book",level:7},"formula-why-probability-1":{id:"formula-why-probability-1",kind:"formula-why",src:"formula:probability#why1",title:"Why P = ways it can happen ÷ all the ways",body:"A bag with 3 red and 5 blue counters has 8 counters, so the chance of red is 3/8. The chances of everything that could happen always add up to 1 — here 3/8 + 5/8 = 1.",more:"The card: Probability — Count what you want, over everything that could happen.",route:"#/lib/formulas|probability",cta:"Probability in the Formula Book",level:7},"formula-story-probability":{id:"formula-story-probability",kind:"formula-story",src:"formula:probability#story",badge:{id:"story",label:"A story"},title:"The raffle",body:"The carnival raffle sold 50 tickets. Pip bought 5 of them. What is his chance of winning the prize? — with Ines and Pip.",art:"art/s-carnival.webp",route:"#/lib/formulas|probability",cta:"Probability in the Formula Book",level:7},"formula-try-probability":{id:"formula-try-probability",kind:"formula-try",src:"formula:probability#gen0",title:"Probability — your turn",route:"#/lib/formulas|probability",cta:"Probability in the Formula Book",play:{q:"A bag has 6 red and 8 blue counters. You pick one without looking. The chance it is red, as a fraction?",opts:["6/14","6/15","6/16"],after:"P = ways it can happen ÷ all the ways",show:[2,1,0]},level:7},"stone-vedic-urdhva-1":{src:"journey:vedic/urdhva#1",badge:{id:"review",label:"Being checked"},source:"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).",route:"#/lib/vedic|urdhva",cta:"Stone 8: Vertically and crosswise",where:"The Vedic Maths Journey · stone 8 of 13",id:"stone-vedic-urdhva-1",kind:"stone-step",title:"Vertically and crosswise (2 of 4)",body:"23 × 41: units 3 × 1 = 3. Crosswise 2 × 1 + 3 × 4 = 14 — write 4, carry 1. Tens 2 × 4 = 8, and the 1 carried makes 9. Answer 943.",level:7},"stone-vedic-urdhva-3":{src:"journey:vedic/urdhva#3",badge:{id:"review",label:"Being checked"},source:"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).",route:"#/lib/vedic|urdhva",cta:"Stone 8: Vertically and crosswise",where:"The Vedic Maths Journey · stone 8 of 13",id:"stone-vedic-urdhva-3",kind:"stone-step",title:"Vertically and crosswise (4 of 4)",body:'Three digits make five columns: vertical, crosswise, a "star" of three pairs in the middle, crosswise, vertical. It is the same idea, one column at a time (you meet it on the Stretch level).',level:7}};export{e as BODY};
